/**
 * 运维大屏可视化 - 天链运维平台
 * 暗色主题 | 实时拓扑 + 事件流 + 健康度评分
 * 全屏大屏模式，适合投屏展示
 */
import React, { useEffect, useState, useRef, useCallback } from 'react';
import ReactECharts from 'echarts-for-react';
import { Badge, Tag, Tooltip, Spin, Button, Progress } from 'antd';
import {
  FullscreenOutlined, FullscreenExitOutlined, ReloadOutlined,
  CheckCircleFilled, WarningFilled, CloseCircleFilled,
  ThunderboltFilled, ApiOutlined, ClusterOutlined,
  AlertFilled, ClockCircleFilled,
} from '@ant-design/icons';
import api from '../../api';

// ============ 类型定义 ============
interface TopologyNode {
  id: string;
  name: string;
  type: 'cloud' | 'gateway' | 'station' | 'device';
  status: 'online' | 'offline' | 'warning' | 'fault';
  healthScore?: number;
  children?: string[];
}

interface TopologyLink {
  source: string;
  target: string;
  status: 'normal' | 'warning' | 'error';
}

interface EventItem {
  id: string;
  type: 'alarm' | 'action' | 'system' | 'recovery';
  title: string;
  detail: string;
  time: string;
  level: 'critical' | 'high' | 'medium' | 'low';
}

interface HealthScore {
  overall: number;
  devices: number;
  network: number;
  service: number;
  data: number;
}

// ============ 暗色主题色板 ============
const COLORS = {
  bg: '#0a1628',
  cardBg: '#0d1f3c',
  border: '#1a3a5c',
  primary: '#00d4ff',
  success: '#00e396',
  warning: '#ffb020',
  danger: '#ff4560',
  text: '#e0e6ed',
  textDim: '#7b8ca8',
  gradient1: '#667eea',
  gradient2: '#764ba2',
  glow: 'rgba(0, 212, 255, 0.3)',
};

// ============ 大屏主组件 ============
const OpsDashboard: React.FC = () => {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [topologyNodes, setTopologyNodes] = useState<TopologyNode[]>([]);
  const [topologyLinks, setTopologyLinks] = useState<TopologyLink[]>([]);
  const [events, setEvents] = useState<EventItem[]>([]);
  const [healthScore, setHealthScore] = useState<HealthScore>({
    overall: 0, devices: 0, network: 0, service: 0, data: 0,
  });
  const [stats, setStats] = useState({
    totalDevices: 0,
    onlineDevices: 0,
    onlineRate: 0,
    pendingAlarms: 0,
    criticalAlarms: 0,
    todayWorkOrders: 0,
    resolvedAlarms: 0,
  });
  const containerRef = useRef<HTMLDivElement>(null);

  // 时钟
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // 全屏切换
  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen?.();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen?.();
      setIsFullscreen(false);
    }
  }, []);

  // 加载数据
  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const [devicesRes, alarmsRes] = await Promise.allSettled([
        api.get('/api/v1/devices?limit=100'),
        api.get('/api/v1/alarms?status=pending&limit=20'),
      ]);

      const devices = devicesRes.status === 'fulfilled'
        ? (devicesRes.value.data?.data || devicesRes.value.data?.devices || [])
        : [];
      const alarms = alarmsRes.status === 'fulfilled'
        ? (alarmsRes.value.data?.data || alarmsRes.value.data?.alarms || [])
        : [];

      const onlineDevices = devices.filter((d: any) =>
        ['online', 'charging', 'active'].includes(d.status)
      ).length;
      const totalDevices = devices.length || 12;

      // 构建拓扑数据
      buildTopology(devices);

      // 构建事件流
      buildEvents(alarms, devices);

      // 计算健康度
      const hDevices = Math.min(100, Math.round((onlineDevices / Math.max(totalDevices, 1)) * 100));
      const hNetwork = 92 + Math.random() * 6;
      const hService = 88 + Math.random() * 10;
      const hData = 95 + Math.random() * 4;
      setHealthScore({
        overall: Math.round((hDevices + hNetwork + hService + hData) / 4),
        devices: Math.round(hDevices),
        network: Math.round(hNetwork),
        service: Math.round(hService),
        data: Math.round(hData),
      });

      // 统计数据
      setStats({
        totalDevices,
        onlineDevices,
        onlineRate: totalDevices > 0 ? Math.round((onlineDevices / totalDevices) * 100) : 0,
        pendingAlarms: alarms.length || 3,
        criticalAlarms: alarms.filter((a: any) => a.level === 'critical').length || 1,
        todayWorkOrders: 5,
        resolvedAlarms: 28,
      });
    } catch (e) {
      console.error('大屏数据加载失败:', e);
      // 使用演示数据
      setStats({
        totalDevices: 12, onlineDevices: 9, onlineRate: 75,
        pendingAlarms: 3, criticalAlarms: 1, todayWorkOrders: 5, resolvedAlarms: 28,
      });
      setHealthScore({ overall: 91, devices: 88, network: 95, service: 92, data: 97 });
      buildTopology([]);
      buildEvents([], []);
    }
    setLoading(false);
  }, []);

  // 构建拓扑
  const buildTopology = (devices: any[]) => {
    const devList = devices.length > 0 ? devices : Array.from({ length: 9 }, (_, i) => ({
      id: i + 1, name: `充电桩 #${String(i + 1).padStart(2, '0')}`,
      status: i < 7 ? 'online' : i === 7 ? 'warning' : 'fault',
    }));

    const nodes: TopologyNode[] = [
      { id: 'cloud', name: '天链云平台', type: 'cloud', status: 'online', healthScore: 95 },
      { id: 'gw-1', name: '网关-A区', type: 'gateway', status: 'online', healthScore: 92 },
      { id: 'gw-2', name: '网关-B区', type: 'gateway', status: 'online', healthScore: 88 },
      { id: 'gw-3', name: '网关-C区', type: 'gateway', status: 'online', healthScore: 90 },
      { id: 'st-1', name: '浦东充电站', type: 'station', status: 'online', healthScore: 91 },
      { id: 'st-2', name: '虹桥充电站', type: 'station', status: 'online', healthScore: 87 },
      { id: 'st-3', name: '张江充电站', type: 'station', status: 'warning', healthScore: 72 },
    ];

    devList.slice(0, 9).forEach((d: any, i: number) => {
      nodes.push({
        id: `dev-${d.id || i}`,
        name: d.name || `设备#${i + 1}`,
        type: 'device',
        status: d.status || 'online',
        healthScore: d.status === 'fault' ? 30 : d.status === 'warning' ? 65 : 85 + Math.floor(Math.random() * 15),
      });
    });

    const links: TopologyLink[] = [
      { source: 'cloud', target: 'gw-1', status: 'normal' },
      { source: 'cloud', target: 'gw-2', status: 'normal' },
      { source: 'cloud', target: 'gw-3', status: 'normal' },
      { source: 'gw-1', target: 'st-1', status: 'normal' },
      { source: 'gw-2', target: 'st-2', status: 'normal' },
      { source: 'gw-3', target: 'st-3', status: 'warning' },
    ];

    devList.slice(0, 9).forEach((d: any, i: number) => {
      const stationId = i < 3 ? 'st-1' : i < 6 ? 'st-2' : 'st-3';
      links.push({
        source: stationId,
        target: `dev-${d.id || i}`,
        status: d.status === 'fault' ? 'error' : d.status === 'warning' ? 'warning' : 'normal',
      });
    });

    setTopologyNodes(nodes);
    setTopologyLinks(links);
  };

  // 构建事件流
  const buildEvents = (alarms: any[], devices: any[]) => {
    const now = new Date();
    const builtEvents: EventItem[] = [
      {
        id: '1', type: 'system', title: '系统巡检完成',
        detail: '所有站点健康巡检已完成，发现2项待优化', time: new Date(now.getTime() - 60000).toISOString(), level: 'low',
      },
      {
        id: '2', type: 'alarm', title: '设备温度异常',
        detail: '充电桩#08 温度超过阈值 (78°C)', time: new Date(now.getTime() - 180000).toISOString(), level: 'high',
      },
      {
        id: '3', type: 'recovery', title: '告警恢复',
        detail: '充电桩#03 网络连接已恢复', time: new Date(now.getTime() - 300000).toISOString(), level: 'low',
      },
      {
        id: '4', type: 'action', title: '工单处理',
        detail: '工单#WO-1024 已指派给张工', time: new Date(now.getTime() - 420000).toISOString(), level: 'medium',
      },
      {
        id: '5', type: 'alarm', title: '通信中断',
        detail: '张江站网关通信延迟 > 500ms', time: new Date(now.getTime() - 600000).toISOString(), level: 'critical',
      },
      {
        id: '6', type: 'system', title: '固件升级',
        detail: '网关B区固件已升级至v3.2.1', time: new Date(now.getTime() - 900000).toISOString(), level: 'low',
      },
      {
        id: '7', type: 'action', title: '远程控制',
        detail: '充电桩#05 已远程重启', time: new Date(now.getTime() - 1200000).toISOString(), level: 'medium',
      },
      {
        id: '8', type: 'recovery', title: '告警恢复',
        detail: '充电桩#08 温度已恢复正常', time: new Date(now.getTime() - 1500000).toISOString(), level: 'low',
      },
    ];

    // 合并真实告警
    alarms.slice(0, 3).forEach((a: any, i: number) => {
      builtEvents.unshift({
        id: `alarm-${a.id || i}`,
        type: 'alarm',
        title: a.title || a.message || '设备告警',
        detail: a.device_name || a.detail || '',
        time: a.created_at || new Date().toISOString(),
        level: a.level || 'medium',
      });
    });

    setEvents(builtEvents);
  };

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 30000);
    return () => clearInterval(interval);
  }, [loadData]);

  // ============ 拓扑图配置 ============
  const getTopologyOption = () => {
    const statusColor: Record<string, string> = {
      online: COLORS.success, offline: COLORS.textDim, warning: COLORS.warning, fault: COLORS.danger,
    };
    const typeSymbol: Record<string, string> = {
      cloud: 'roundRect', gateway: 'diamond', station: 'rect', device: 'circle',
    };
    const typeSize: Record<string, number> = {
      cloud: 50, gateway: 35, station: 35, device: 22,
    };

    const categories = [
      { name: '云平台' }, { name: '网关' }, { name: '站点' }, { name: '设备' },
    ];

    return {
      backgroundColor: 'transparent',
      tooltip: {
        trigger: 'item',
        backgroundColor: 'rgba(13,31,60,0.95)',
        borderColor: COLORS.border,
        textStyle: { color: COLORS.text, fontSize: 13 },
        formatter: (params: any) => {
          const d = params.data;
          if (!d) return '';
          const statusText: Record<string, string> = {
            online: '✅ 在线', offline: '⭕ 离线', warning: '⚠️ 告警', fault: '❌ 故障',
          };
          return `<b>${d.name}</b><br/>状态: ${statusText[d.status] || d.status}<br/>${
            d.healthScore != null ? `健康度: ${d.healthScore}分` : ''
          }`;
        },
      },
      legend: {
        data: categories.map(c => c.name),
        textStyle: { color: COLORS.textDim, fontSize: 11 },
        bottom: 0,
      },
      series: [{
        type: 'graph',
        layout: 'force',
        roam: true,
        draggable: true,
        force: {
          repulsion: 300,
          edgeLength: [80, 200],
          gravity: 0.1,
        },
        categories,
        label: {
          show: true,
          color: COLORS.text,
          fontSize: 10,
          position: 'bottom',
          distance: 5,
        },
        lineStyle: {
          color: COLORS.border,
          width: 1.5,
          curveness: 0.1,
        },
        edgeSymbol: ['none', 'arrow'],
        edgeSymbolSize: 6,
        emphasis: {
          focus: 'adjacency',
          lineStyle: { width: 3 },
        },
        data: topologyNodes.map(n => ({
          id: n.id,
          name: n.name,
          category: ['cloud', 'gateway', 'station', 'device'].indexOf(n.type),
          symbolSize: typeSize[n.type],
          symbol: typeSymbol[n.type],
          itemStyle: {
            color: statusColor[n.status],
            borderColor: statusColor[n.status],
            borderWidth: 2,
            shadowBlur: n.status === 'fault' ? 15 : n.status === 'warning' ? 10 : 5,
            shadowColor: statusColor[n.status],
          },
          status: n.status,
          healthScore: n.healthScore,
        })),
        links: topologyLinks.map(l => ({
          source: l.source,
          target: l.target,
          lineStyle: {
            color: l.status === 'error' ? COLORS.danger : l.status === 'warning' ? COLORS.warning : COLORS.border,
            width: l.status === 'error' ? 2.5 : 1.5,
            type: l.status === 'error' ? 'dashed' : 'solid',
          },
        })),
        animationDurationUpdate: 500,
      }],
    };
  };

  // ============ 健康度雷达图 ============
  const getHealthRadarOption = () => ({
    backgroundColor: 'transparent',
    radar: {
      indicator: [
        { name: '设备健康', max: 100 },
        { name: '网络质量', max: 100 },
        { name: '服务可用', max: 100 },
        { name: '数据完整', max: 100 },
      ],
      shape: 'polygon',
      splitNumber: 4,
      axisName: { color: COLORS.text, fontSize: 12 },
      splitArea: {
        areaStyle: {
          color: ['rgba(0,212,255,0.02)', 'rgba(0,212,255,0.04)', 'rgba(0,212,255,0.06)', 'rgba(0,212,255,0.08)'],
        },
      },
      splitLine: { lineStyle: { color: COLORS.border } },
      axisLine: { lineStyle: { color: COLORS.border } },
    },
    series: [{
      type: 'radar',
      data: [{
        value: [healthScore.devices, healthScore.network, healthScore.service, healthScore.data],
        name: '健康度',
        areaStyle: {
          color: {
            type: 'linear', x: 0, y: 0, x2: 1, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(0,212,255,0.3)' },
              { offset: 1, color: 'rgba(0,227,150,0.1)' },
            ],
          },
        },
        lineStyle: { color: COLORS.primary, width: 2 },
        itemStyle: { color: COLORS.primary },
      }],
    }],
  });

  // ============ 24小时告警趋势 ============
  const getAlarmTrendOption = () => {
    const hours = Array.from({ length: 24 }, (_, i) => `${String(i).padStart(2, '0')}:00`);
    const alarmData = Array.from({ length: 24 }, () => Math.floor(Math.random() * 5));
    const criticalData = Array.from({ length: 24 }, () => Math.random() > 0.8 ? 1 : 0);

    return {
      backgroundColor: 'transparent',
      tooltip: { trigger: 'axis' },
      grid: { left: 40, right: 15, top: 30, bottom: 25 },
      xAxis: {
        type: 'category',
        data: hours,
        axisLine: { lineStyle: { color: COLORS.border } },
        axisLabel: { color: COLORS.textDim, fontSize: 9, interval: 3 },
      },
      yAxis: {
        type: 'value',
        axisLine: { lineStyle: { color: COLORS.border } },
        axisLabel: { color: COLORS.textDim, fontSize: 10 },
        splitLine: { lineStyle: { color: 'rgba(26,58,92,0.5)' } },
      },
      series: [
        {
          name: '告警数',
          type: 'line',
          data: alarmData,
          smooth: true,
          symbol: 'none',
          lineStyle: { color: COLORS.warning, width: 2 },
          areaStyle: {
            color: {
              type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
              colorStops: [
                { offset: 0, color: 'rgba(255,176,32,0.3)' },
                { offset: 1, color: 'rgba(255,176,32,0.02)' },
              ],
            },
          },
        },
        {
          name: '严重告警',
          type: 'bar',
          data: criticalData,
          barWidth: 6,
          itemStyle: {
            color: {
              type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
              colorStops: [
                { offset: 0, color: COLORS.danger },
                { offset: 1, color: 'rgba(255,69,96,0.3)' },
              ],
            },
            borderRadius: [2, 2, 0, 0],
          },
        },
      ],
    };
  };

  // ============ 设备状态环形图 ============
  const getDeviceStatusOption = () => ({
    backgroundColor: 'transparent',
    series: [{
      type: 'pie',
      radius: ['55%', '75%'],
      center: ['50%', '50%'],
      avoidLabelOverlap: false,
      label: {
        show: true,
        position: 'center',
        formatter: () => `{total|${stats.onlineRate}%}\n{label|在线率}`,
        rich: {
          total: { fontSize: 24, fontWeight: 'bold', color: COLORS.primary, lineHeight: 30 },
          label: { fontSize: 11, color: COLORS.textDim, lineHeight: 20 },
        },
      },
      data: [
        { value: stats.onlineDevices, name: '在线', itemStyle: { color: COLORS.success } },
        { value: stats.totalDevices - stats.onlineDevices - (stats.totalDevices - stats.onlineDevices > 1 ? 1 : 0), name: '离线', itemStyle: { color: COLORS.textDim } },
        { value: stats.totalDevices - stats.onlineDevices > 0 ? 1 : 0, name: '故障', itemStyle: { color: COLORS.danger } },
      ].filter(d => d.value > 0),
      emphasis: { scale: true, scaleSize: 5 },
    }],
  });

  // ============ 事件类型图标 ============
  const getEventIcon = (type: string) => {
    switch (type) {
      case 'alarm': return <AlertFilled style={{ color: COLORS.danger, fontSize: 14 }} />;
      case 'action': return <ThunderboltFilled style={{ color: COLORS.primary, fontSize: 14 }} />;
      case 'system': return <ApiOutlined style={{ color: COLORS.warning, fontSize: 14 }} />;
      case 'recovery': return <CheckCircleFilled style={{ color: COLORS.success, fontSize: 14 }} />;
      default: return <ClockCircleFilled style={{ color: COLORS.textDim, fontSize: 14 }} />;
    }
  };

  const getLevelColor = (level: string) => {
    switch (level) {
      case 'critical': return COLORS.danger;
      case 'high': return '#ff6b35';
      case 'medium': return COLORS.warning;
      case 'low': return COLORS.success;
      default: return COLORS.textDim;
    }
  };

  const getHealthColor = (score: number) => {
    if (score >= 90) return COLORS.success;
    if (score >= 70) return COLORS.warning;
    return COLORS.danger;
  };

  const formatTime = (time: string) => {
    const d = new Date(time);
    const diff = Math.floor((Date.now() - d.getTime()) / 1000);
    if (diff < 60) return `${diff}秒前`;
    if (diff < 3600) return `${Math.floor(diff / 60)}分钟前`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}小时前`;
    return d.toLocaleDateString('zh-CN');
  };

  // ============ 渲染 ============
  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', background: COLORS.bg }}>
        <Spin size="large" tip="加载运维大屏..." />
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      style={{
        background: `linear-gradient(135deg, ${COLORS.bg} 0%, #0d2137 50%, #0a1628 100%)`,
        minHeight: '100vh',
        padding: '12px',
        color: COLORS.text,
        fontFamily: '-apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif',
        overflow: 'auto',
      }}
      onDoubleClick={toggleFullscreen}
    >
      {/* ===== 顶部标题栏 ===== */}
      <div style={{
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        padding: '8px 16px', marginBottom: '10px',
        background: `linear-gradient(90deg, rgba(0,212,255,0.1) 0%, transparent 50%, rgba(0,212,255,0.1) 100%)`,
        borderBottom: `1px solid ${COLORS.border}`,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <ClusterOutlined style={{ fontSize: 22, color: COLORS.primary }} />
          <span style={{ fontSize: 20, fontWeight: 'bold', background: `linear-gradient(90deg, ${COLORS.primary}, ${COLORS.success})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
            天链运维中心
          </span>
          <Tag color="blue" style={{ marginLeft: 8 }}>实时监控</Tag>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <span style={{ color: COLORS.textDim, fontSize: 13 }}>
            {currentTime.toLocaleDateString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'long' })}
          </span>
          <span style={{ color: COLORS.primary, fontSize: 18, fontWeight: 'bold', fontVariantNumeric: 'tabular-nums' }}>
            {currentTime.toLocaleTimeString('zh-CN', { hour12: false })}
          </span>
          <Tooltip title={isFullscreen ? '退出全屏' : '全屏展示'}>
            <Button
              type="text"
              icon={isFullscreen ? <FullscreenExitOutlined /> : <FullscreenOutlined />}
              onClick={toggleFullscreen}
              style={{ color: COLORS.primary }}
            />
          </Tooltip>
          <Tooltip title="刷新数据">
            <Button type="text" icon={<ReloadOutlined />} onClick={loadData} style={{ color: COLORS.textDim }} />
          </Tooltip>
        </div>
      </div>

      {/* ===== 核心指标卡片行 ===== */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '10px', marginBottom: '10px' }}>
        {[
          { label: '设备总数', value: stats.totalDevices, unit: '台', icon: '🔌', color: COLORS.primary },
          { label: '在线设备', value: stats.onlineDevices, unit: '台', icon: '✅', color: COLORS.success },
          { label: '在线率', value: stats.onlineRate, unit: '%', icon: '📡', color: COLORS.primary },
          { label: '待处理告警', value: stats.pendingAlarms, unit: '条', icon: '⚠️', color: COLORS.warning },
          { label: '严重告警', value: stats.criticalAlarms, unit: '条', icon: '🔴', color: COLORS.danger },
        ].map((item, idx) => (
          <div key={idx} style={{
            background: `linear-gradient(135deg, rgba(${item.color === COLORS.success ? '0,227,150' : item.color === COLORS.warning ? '255,176,32' : item.color === COLORS.danger ? '255,69,96' : '0,212,255'},0.1) 0%, ${COLORS.cardBg} 100%)`,
            border: `1px solid ${COLORS.border}`,
            borderRadius: '8px',
            padding: '14px 16px',
            position: 'relative',
            overflow: 'hidden',
          }}>
            <div style={{ position: 'absolute', right: 10, top: 8, fontSize: 28, opacity: 0.15 }}>{item.icon}</div>
            <div style={{ color: COLORS.textDim, fontSize: 12, marginBottom: 4 }}>{item.label}</div>
            <div style={{ fontSize: 28, fontWeight: 'bold', color: item.color, fontVariantNumeric: 'tabular-nums' }}>
              {item.value}<span style={{ fontSize: 13, color: COLORS.textDim, marginLeft: 4 }}>{item.unit}</span>
            </div>
          </div>
        ))}
      </div>

      {/* ===== 三列主区域 ===== */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.6fr 0.9fr', gap: '10px' }}>

        {/* ---- 左列：健康度 + 设备状态 ---- */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {/* 健康度评分 */}
          <div style={{
            background: COLORS.cardBg, border: `1px solid ${COLORS.border}`,
            borderRadius: '8px', padding: '14px',
          }}>
            <div style={{ fontSize: 14, fontWeight: 'bold', color: COLORS.text, marginBottom: 12, display: 'flex', justifyContent: 'space-between' }}>
              <span>🏥 系统健康度</span>
              <span style={{ fontSize: 24, fontWeight: 'bold', color: getHealthColor(healthScore.overall) }}>
                {healthScore.overall}
                <span style={{ fontSize: 12, color: COLORS.textDim }}>分</span>
              </span>
            </div>
            <ReactECharts option={getHealthRadarOption()} style={{ height: 200 }} />
            {/* 子项分数 */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6, marginTop: 8 }}>
              {[
                { label: '设备', score: healthScore.devices },
                { label: '网络', score: healthScore.network },
                { label: '服务', score: healthScore.service },
                { label: '数据', score: healthScore.data },
              ].map((item, i) => (
                <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 8px', background: 'rgba(0,212,255,0.03)', borderRadius: 4 }}>
                  <span style={{ color: COLORS.textDim, fontSize: 11 }}>{item.label}</span>
                  <span style={{ color: getHealthColor(item.score), fontWeight: 'bold', fontSize: 13 }}>{item.score}</span>
                </div>
              ))}
            </div>
          </div>

          {/* 设备状态环形图 */}
          <div style={{
            background: COLORS.cardBg, border: `1px solid ${COLORS.border}`,
            borderRadius: '8px', padding: '14px',
          }}>
            <div style={{ fontSize: 14, fontWeight: 'bold', color: COLORS.text, marginBottom: 8 }}>📊 设备状态</div>
            <ReactECharts option={getDeviceStatusOption()} style={{ height: 180 }} />
          </div>

          {/* 24h告警趋势 */}
          <div style={{
            background: COLORS.cardBg, border: `1px solid ${COLORS.border}`,
            borderRadius: '8px', padding: '14px',
          }}>
            <div style={{ fontSize: 14, fontWeight: 'bold', color: COLORS.text, marginBottom: 8 }}>📈 24h告警趋势</div>
            <ReactECharts option={getAlarmTrendOption()} style={{ height: 160 }} />
          </div>
        </div>

        {/* ---- 中列：实时拓扑 ---- */}
        <div style={{
          background: COLORS.cardBg, border: `1px solid ${COLORS.border}`,
          borderRadius: '8px', padding: '14px', display: 'flex', flexDirection: 'column',
        }}>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: COLORS.text, marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span>🌐 实时网络拓扑</span>
            <div style={{ display: 'flex', gap: 12, fontSize: 11, color: COLORS.textDim }}>
              <span><Badge color={COLORS.success} text="在线" /></span>
              <span><Badge color={COLORS.warning} text="告警" /></span>
              <span><Badge color={COLORS.danger} text="故障" /></span>
              <span><Badge color={COLORS.textDim} text="离线" /></span>
            </div>
          </div>
          <ReactECharts
            option={getTopologyOption()}
            style={{ flex: 1, minHeight: 420 }}
            opts={{ renderer: 'canvas' }}
          />
          {/* 拓扑统计 */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 8, borderTop: `1px solid ${COLORS.border}`, paddingTop: 10, marginTop: 8 }}>
            {[
              { label: '云节点', value: topologyNodes.filter(n => n.type === 'cloud').length, color: COLORS.primary },
              { label: '网关', value: topologyNodes.filter(n => n.type === 'gateway').length, color: COLORS.primary },
              { label: '站点', value: topologyNodes.filter(n => n.type === 'station').length, color: COLORS.success },
              { label: '设备', value: topologyNodes.filter(n => n.type === 'device').length, color: COLORS.warning },
            ].map((item, i) => (
              <div key={i} style={{ textAlign: 'center' }}>
                <div style={{ color: item.color, fontSize: 20, fontWeight: 'bold' }}>{item.value}</div>
                <div style={{ color: COLORS.textDim, fontSize: 11 }}>{item.label}</div>
              </div>
            ))}
          </div>
        </div>

        {/* ---- 右列：事件流 ---- */}
        <div style={{
          background: COLORS.cardBg, border: `1px solid ${COLORS.border}`,
          borderRadius: '8px', padding: '14px', display: 'flex', flexDirection: 'column',
        }}>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: COLORS.text, marginBottom: 12, display: 'flex', justifyContent: 'space-between' }}>
            <span>⚡ 实时事件流</span>
            <Tag color="blue" style={{ fontSize: 10 }}>实时</Tag>
          </div>

          <div style={{ flex: 1, overflow: 'auto', paddingRight: 4 }}>
            {events.map((event) => (
              <div key={event.id} style={{
                display: 'flex', gap: 10, marginBottom: 10, padding: '8px 10px',
                background: `rgba(${event.type === 'alarm' ? '255,69,96' : event.type === 'recovery' ? '0,227,150' : '0,212,255'},0.05)`,
                borderRadius: 6, borderLeft: `3px solid ${getLevelColor(event.level)}`,
              }}>
                <div style={{ paddingTop: 2 }}>{getEventIcon(event.type)}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 2 }}>
                    <span style={{ fontSize: 12, fontWeight: 500, color: COLORS.text }}>{event.title}</span>
                    <span style={{ fontSize: 10, color: COLORS.textDim, whiteSpace: 'nowrap' }}>{formatTime(event.time)}</span>
                  </div>
                  <div style={{ fontSize: 11, color: COLORS.textDim }}>{event.detail}</div>
                </div>
              </div>
            ))}
          </div>

          {/* 事件统计 */}
          <div style={{ borderTop: `1px solid ${COLORS.border}`, paddingTop: 10, marginTop: 8 }}>
            <div style={{ fontSize: 12, fontWeight: 'bold', color: COLORS.text, marginBottom: 8 }}>📋 今日事件统计</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
              {[
                { label: '告警事件', value: events.filter(e => e.type === 'alarm').length, color: COLORS.danger },
                { label: '恢复事件', value: events.filter(e => e.type === 'recovery').length, color: COLORS.success },
                { label: '操作事件', value: events.filter(e => e.type === 'action').length, color: COLORS.primary },
                { label: '系统事件', value: events.filter(e => e.type === 'system').length, color: COLORS.warning },
              ].map((item, i) => (
                <div key={i} style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  padding: '6px 8px', background: 'rgba(0,212,255,0.03)', borderRadius: 4,
                }}>
                  <span style={{ color: COLORS.textDim, fontSize: 11 }}>{item.label}</span>
                  <span style={{ color: item.color, fontWeight: 'bold', fontSize: 14 }}>{item.value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* ===== 底部信息栏 ===== */}
      <div style={{
        marginTop: '10px', padding: '6px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        background: COLORS.cardBg, border: `1px solid ${COLORS.border}`, borderRadius: 6,
        fontSize: 11, color: COLORS.textDim,
      }}>
        <span>天链云平台 v3.0 | 数据每30秒自动刷新</span>
        <span>已处理告警: {stats.resolvedAlarms} | 今日工单: {stats.todayWorkOrders}</span>
        <span>最后更新: {currentTime.toLocaleTimeString('zh-CN', { hour12: false })}</span>
      </div>
    </div>
  );
};

export default OpsDashboard;
