/**
 * 布局组件 - 包含侧边栏和头部
 * 支持亮色/暗黑主题 + 权限控制
 */
import React, { useState, useEffect } from 'react';
import { Layout, Menu, Avatar, Dropdown, Badge, Space, theme, Switch, ConfigProvider } from 'antd';
import {
  DashboardOutlined, DesktopOutlined, ControlOutlined, MonitorOutlined,
  AlertOutlined, NotificationOutlined, SafetyOutlined, GlobalOutlined,
  UserOutlined, SettingOutlined, LogoutOutlined, MenuFoldOutlined, MenuUnfoldOutlined,
  BellOutlined, BulbOutlined, BulbFilled, BarChartOutlined, BookOutlined,
  QrcodeOutlined, MedicineBoxOutlined, BarcodeOutlined, ClusterOutlined, ToolOutlined,
  TeamOutlined,
} from '@ant-design/icons';
import { useNavigate, useLocation } from 'react-router-dom';

const { Header, Sider, Content } = Layout;

interface AdminLayoutProps {
  children: React.ReactNode;
}

const AdminLayout: React.FC<AdminLayoutProps> = ({ children }) => {
  const [collapsed, setCollapsed] = useState(false);
  const [isDark, setIsDark] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const [accountType, setAccountType] = useState<string>('platform');

  useEffect(() => {
    // 根据路由设置页面标题
    const titleMap: Record<string, string> = {
      '/dashboard': '天链 - 仪表盘',
      '/stations': '天链 - 站点管理',
      '/devices': '天链 - 设备管理',
      '/gateways': '天链 - 网关管理',
      '/gateway-sn': '天链 - SN码管理',
      '/workorders': '天链 - 工单管理',
      '/alarms': '天链 - 告警管理',
      '/alarm-notices': '天链 - 告警通知',
      '/health': '天链 - 健康监控',
      '/monitor': '天链 - 实时监控',
      '/map': '天链 - 站点地图',
      '/teams': '天链 - 团队管理',
      '/users': '天链 - 用户管理',
      '/rbac': '天链 - 权限管理',
      '/knowledge': '天链 - 知识库',
      '/reports': '天链 - 报表导出',
      '/config': '天链 - 系统配置',
      '/remote-control': '天链 - 远程控制',
      '/qrcode-print': '天链 - 二维码打印',
      '/diagnosis': '天链 - 智能诊断',
      '/security': '天链 - 安全增强',
    };
    document.title = titleMap[location.pathname] || '天链运维系统';
    
    const savedTheme = localStorage.getItem('theme');
    const savedAccountType = localStorage.getItem('admin_account_type') || 'platform';
    if (savedTheme === 'dark') setIsDark(true);
    setAccountType(savedAccountType);
  }, [location.pathname]);

  // 根据账户类型动态生成菜单
  const getMenuItems = () => {
    const platformOnlyItems = accountType === 'platform' ? [
      { key: '/gateway-sn', icon: <BarcodeOutlined />, label: 'SN码管理' },
      { key: '/rbac', icon: <UserOutlined />, label: '角色权限' },
    ] : [];

    return [
      { key: '/dashboard', icon: <DashboardOutlined />, label: '首页概览' },
      { key: '/ops-dashboard', icon: <MonitorOutlined />, label: '运维大屏' },
      { key: '/diagnosis', icon: <MedicineBoxOutlined />, label: '智能诊断' },
      { key: '/qrcode-print', icon: <QrcodeOutlined />, label: '二维码打印' },
      { type: 'divider' as const },
      { key: 'devices', icon: <DesktopOutlined />, label: '设备管理', children: [
        { key: '/devices', icon: <DesktopOutlined />, label: '设备列表' },
        { key: '/gateways', icon: <ClusterOutlined />, label: '网关管理' },
        ...platformOnlyItems.filter(item => item.key === '/gateway-sn'),
      ]},
      { key: '/stations', icon: <GlobalOutlined />, label: '站点管理' },
      { key: '/teams', icon: <TeamOutlined />, label: '团队管理' },
      { key: '/users', icon: <UserOutlined />, label: '用户管理' },
      { key: '/workorders', icon: <ToolOutlined />, label: '工单管理' },
      { key: '/remote-control', icon: <ControlOutlined />, label: '远程控制' },
      { key: '/monitor', icon: <MonitorOutlined />, label: '动态监控' },
      { type: 'divider' as const },
      { key: 'alarms', icon: <AlertOutlined />, label: '告警管理', children: [
        { key: '/alarms', icon: <AlertOutlined />, label: '告警概览' },
        { key: '/alarm-notices', icon: <NotificationOutlined />, label: '告警通知' },
      ]},
      { key: '/health', icon: <SafetyOutlined />, label: '健康巡检' },
      { key: '/security', icon: <SafetyOutlined />, label: '安全增强' },
      { key: '/map', icon: <GlobalOutlined />, label: '站点地图' },
      { key: '/reports', icon: <BarChartOutlined />, label: '数据报表' },
      { key: '/knowledge', icon: <BookOutlined />, label: '知识库' },
      ...platformOnlyItems.filter(item => item.key === '/rbac'),
    ];
  };

  const menuItems = getMenuItems();

  const handleLogout = () => {
    localStorage.removeItem('admin_token');
    localStorage.removeItem('admin_user');
    localStorage.removeItem('admin_account_type');
    navigate('/login');
  };

  const toggleTheme = (checked: boolean) => {
    setIsDark(checked);
    localStorage.setItem('theme', checked ? 'dark' : 'light');
  };

  const userMenu = (
    <Menu>
      <Menu.Item key="account">
        <Space>
          <UserOutlined />
          {accountType === 'platform' ? '平台运维' : '运维团队'}
        </Space>
      </Menu.Item>
      <Menu.Item key="theme">
        <Space>
          {isDark ? <BulbFilled /> : <BulbOutlined />}
          主题切换
          <Switch checked={isDark} onChange={toggleTheme} size="small" />
        </Space>
      </Menu.Item>
      <Menu.Divider />
      <Menu.Item key="logout" onClick={handleLogout} danger>
        <Space>
          <LogoutOutlined />
          退出登录
        </Space>
      </Menu.Item>
    </Menu>
  );

  const { defaultAlgorithm, darkAlgorithm } = theme;

  return (
    <ConfigProvider theme={{ algorithm: isDark ? darkAlgorithm : defaultAlgorithm }}>
      <Layout style={{ minHeight: '100vh' }}>
        <Sider
          trigger={null}
          collapsible
          collapsed={collapsed}
          style={{ overflow: 'auto', height: '100vh', position: 'fixed', left: 0 }}
        >
          <div style={{ height: 64, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Avatar style={{ backgroundColor: '#1890ff' }} icon={<GlobalOutlined />} />
            {!collapsed && <span style={{ marginLeft: 12, color: '#fff' }}>天链运维</span>}
          </div>
          <Menu
            theme="dark"
            mode="inline"
            selectedKeys={[location.pathname]}
            defaultOpenKeys={['devices', 'alarms']}
            items={menuItems}
            onClick={({ key }) => navigate(key)}
          />
        </Sider>

        <Layout style={{ marginLeft: collapsed ? 80 : 200, transition: 'all 0.2s' }}>
          <Header style={{ padding: '0 24px', background: isDark ? '#141414' : '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Space>
              {collapsed ? (
                <MenuUnfoldOutlined onClick={() => setCollapsed(false)} style={{ fontSize: 18 }} />
              ) : (
                <MenuFoldOutlined onClick={() => setCollapsed(true)} style={{ fontSize: 18 }} />
              )}
            </Space>

            <Space>
              <Badge count={0}>
                <BellOutlined style={{ fontSize: 18 }} />
              </Badge>
              <Dropdown dropdownRender={() => userMenu} placement="bottomRight">
                <Space style={{ cursor: 'pointer' }}>
                  <Avatar style={{ backgroundColor: '#1890ff' }} icon={<UserOutlined />} />
                  <span>{accountType === 'platform' ? '平台运维' : '运维团队'}</span>
                </Space>
              </Dropdown>
            </Space>
          </Header>

          <Content style={{ margin: '24px 16px', padding: 24, background: isDark ? '#141414' : '#fff', borderRadius: 8, minHeight: 'calc(100vh - 112px)' }}>
            {children}
          </Content>
        </Layout>
      </Layout>
    </ConfigProvider>
  );
};

export default AdminLayout;