import React, { useEffect, useState } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import { Card, Table, Button, Input, Space, Modal, Form, Select, Tag, message as AntMessage } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, SearchOutlined } from '@ant-design/icons';
import api from '../../api';

const { TextArea } = Input;
const { Option } = Select;

interface Knowledge {
  id: string;
  title: string;
  category: string;
  content: string;
  tags: string[];
  createdAt: string;
  updatedAt: string;
}

const KnowledgeBase: React.FC = () => {
  const [knowledgeList, setKnowledgeList] = useState<Knowledge[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchText, setSearchText] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [editingItem, setEditingItem] = useState<Knowledge | null>(null);
  const [form] = Form.useForm();

  const editor = useEditor({
    extensions: [
      StarterKit,
      Placeholder.configure({
        placeholder: '请输入知识库内容...',
      }),
    ],
    content: '',
    editorProps: {
      attributes: {
        class: 'prose prose-sm sm:prose lg:prose-lg xl:prose-xl focus:outline-none min-h-[300px] p-4 border rounded-md',
      },
    },
  });

  useEffect(() => {
    loadKnowledgeList();
  }, []);

  const loadKnowledgeList = async () => {
    setLoading(true);
    try {
      const res = await api.get('/knowledge');
      setKnowledgeList(res.data || []);
    } catch (error) {
      console.error('Failed to load knowledge list:', error);
      AntMessage.error('加载知识库失败');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingItem(null);
    form.resetFields();
    editor?.commands.setContent('');
    setModalVisible(true);
  };

  const handleEdit = (record: Knowledge) => {
    setEditingItem(record);
    form.setFieldsValue({
      title: record.title,
      category: record.category,
      tags: record.tags,
    });
    editor?.commands.setContent(record.content || '');
    setModalVisible(true);
  };

  const handleDelete = async (id: string) => {
    try {
      await api.delete(`/knowledge/${id}`);
      AntMessage.success('删除成功');
      loadKnowledgeList();
    } catch (error) {
      console.error('Failed to delete:', error);
      AntMessage.error('删除失败');
    }
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      const content = editor?.getHTML() || '';
      
      if (editingItem) {
        await api.put(`/knowledge/${editingItem.id}`, {
          ...values,
          content,
        });
        AntMessage.success('更新成功');
      } else {
        await api.post('/knowledge', {
          ...values,
          content,
        });
        AntMessage.success('创建成功');
      }
      
      setModalVisible(false);
      loadKnowledgeList();
    } catch (error) {
      console.error('Failed to save:', error);
    }
  };

  const columns = [
    {
      title: '标题',
      dataIndex: 'title',
      key: 'title',
      render: (text: string) => <strong>{text}</strong>,
    },
    {
      title: '分类',
      dataIndex: 'category',
      key: 'category',
      render: (category: string) => (
        <Tag color={category === '操作手册' ? 'blue' : category === '故障处理' ? 'red' : 'green'}>
          {category}
        </Tag>
      ),
    },
    {
      title: '标签',
      dataIndex: 'tags',
      key: 'tags',
      render: (tags: string[]) => (
        <>
          {tags?.slice(0, 3).map((tag) => (
            <Tag key={tag} color="default">{tag}</Tag>
          ))}
          {tags?.length > 3 && <Tag color="default">+{tags.length - 3}</Tag>}
        </>
      ),
    },
    {
      title: '更新时间',
      dataIndex: 'updatedAt',
      key: 'updatedAt',
      render: (date: string) => new Date(date).toLocaleString('zh-CN'),
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: Knowledge) => (
        <Space>
          <Button
            type="link"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          >
            编辑
          </Button>
          <Button
            type="link"
            danger
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.id)}
          >
            删除
          </Button>
        </Space>
      ),
    },
  ];

  const filteredData = knowledgeList.filter((item) =>
    item.title.toLowerCase().includes(searchText.toLowerCase())
  );

  // Toolbar component
  const MenuBar = () => (
    <div className="border-b p-2 bg-gray-50 rounded-t-md mb-2">
      <Space wrap>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleBold().run()}
          type={editor?.isActive('bold') ? 'primary' : 'default'}
        >
          粗体
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleItalic().run()}
          type={editor?.isActive('italic') ? 'primary' : 'default'}
        >
          斜体
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleStrike().run()}
          type={editor?.isActive('strike') ? 'primary' : 'default'}
        >
          删除线
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleHeading({ level: 1 }).run()}
          type={editor?.isActive('heading', { level: 1 }) ? 'primary' : 'default'}
        >
          H1
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleHeading({ level: 2 }).run()}
          type={editor?.isActive('heading', { level: 2 }) ? 'primary' : 'default'}
        >
          H2
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleBulletList().run()}
          type={editor?.isActive('bulletList') ? 'primary' : 'default'}
        >
          列表
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleOrderedList().run()}
          type={editor?.isActive('orderedList') ? 'primary' : 'default'}
        >
          编号
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().toggleBlockquote().run()}
          type={editor?.isActive('blockquote') ? 'primary' : 'default'}
        >
          引用
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().undo().run()}
          disabled={!editor?.can().undo()}
        >
          撤销
        </Button>
        <Button
          size="small"
          onClick={() => editor?.chain().focus().redo().run()}
          disabled={!editor?.can().redo()}
        >
          重做
        </Button>
      </Space>
    </div>
  );

  return (
    <div style={{ padding: '24px' }}>
      <Card>
        <div style={{ marginBottom: 16, display: 'flex', justifyContent: 'space-between' }}>
          <Space>
            <Input
              placeholder="搜索知识库"
              prefix={<SearchOutlined />}
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{ width: 300 }}
            />
          </Space>
          <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>
            新建知识
          </Button>
        </div>

        <Table
          columns={columns}
          dataSource={filteredData}
          rowKey="id"
          loading={loading}
          pagination={{ pageSize: 20 }}
        />
      </Card>

      {/* Create/Edit Modal */}
      <Modal
        title={editingItem ? '编辑知识' : '新建知识'}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={handleSubmit}
        width={800}
        okText="保存"
        cancelText="取消"
      >
        <Form form={form} layout="vertical">
          <Form.Item
            name="title"
            label="标题"
            rules={[{ required: true, message: '请输入标题' }]}
          >
            <Input placeholder="请输入标题" />
          </Form.Item>

          <Form.Item
            name="category"
            label="分类"
            rules={[{ required: true, message: '请选择分类' }]}
          >
            <Select placeholder="请选择分类">
              <Option value="操作手册">操作手册</Option>
              <Option value="故障处理">故障处理</Option>
              <Option value="技术规范">技术规范</Option>
              <Option value="安全指南">安全指南</Option>
              <Option value="其他">其他</Option>
            </Select>
          </Form.Item>

          <Form.Item
            name="tags"
            label="标签"
          >
            <Select
              mode="tags"
              placeholder="输入标签后按回车"
              maxTagCount="responsive"
            />
          </Form.Item>

          <Form.Item label="内容">
            <div style={{ border: '1px solid #d9d9d9', borderRadius: '4px' }}>
              <MenuBar />
              <EditorContent editor={editor} style={{ padding: '8px' }} />
            </div>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default KnowledgeBase;
