/**
 * 运维报表页面 - 天链运维平台
 * 聚焦设备健康、告警、工单统计，无经营数据
 */
import React, { useEffect, useState } from 'react';
import ReactECharts from 'echarts-for-react';
import { Card, Row, Col, Table, DatePicker, Select, Button, Space, Statistic } from 'antd';
import { DownloadOutlined, FileExcelOutlined, ToolOutlined, WarningOutlined, CheckCircleOutlined } from '@ant-design/icons';
import api from '../../api';
import dayjs from 'dayjs';

const { RangePicker } = DatePicker;
const { Option } = Select;

interface ReportData {
  date: string;
  healthScore: number;
  alarmCount: number;
  criticalAlarms: number;
  workOrderCount: number;
  resolvedOrders: number;
  avgResponseTime: number;
}

const Reports: React.FC = () => {
  const [dateRange, setDateRange] = useState<[any, any]>([
    dayjs().subtract(30, 'day'),
    dayjs(),
  ]);
  const [reportType, setReportType] = useState('health');
  const [loading, setLoading] = useState(false);
  const [reportData, setReportData] = useState<ReportData[]>([]);

  useEffect(() => {
    loadReportData();
  }, [dateRange, reportType]);

  const loadReportData = async () => {
    setLoading(true);
    try {
      const startDate = dateRange[0].format('YYYY-MM-DD');
      const endDate = dateRange[1].format('YYYY-MM-DD');
      
      // 获取诊断数据
      const diagnosisRes = await api.post('/api/v1/diagnosis/batch', {});
      
      // 模拟历史数据（实际应从历史表获取）
      const mockData: ReportData[] = [];
      for (let i = 0; i <= 30; i++) {
        const date = dayjs().subtract(30 - i, 'day').format('YYYY-MM-DD');
        mockData.push({
          date,
          healthScore: 85 + Math.random() * 10,
          alarmCount: Math.floor(Math.random() * 10),
          criticalAlarms: Math.floor(Math.random() * 2),
          workOrderCount: Math.floor(Math.random() * 8),
          resolvedOrders: Math.floor(Math.random() * 6),
          avgResponseTime: Math.floor(Math.random() * 120) + 30,
        });
      }
      
      setReportData(mockData);
    } catch (error) {
      console.error('Failed to load report data:', error);
    } finally {
      setLoading(false);
    }
  };

  const exportReport = () => {
    // 导出 Excel
    console.log('Export report');
  };

  // 健康度报表图表
  const healthOption = {
    title: { text: '设备健康度趋势报表' },
    tooltip: { trigger: 'axis' },
    legend: { data: ['平均健康度', 'A级设备', 'B级设备'] },
    xAxis: {
      type: 'category',
      data: reportData.map((item) => item.date),
    },
    yAxis: [
      {
        type: 'value',
        name: '健康度(分)',
        min: 0,
        max: 100,
        position: 'left',
      },
      {
        type: 'value',
        name: '设备数',
        position: 'right',
      },
    ],
    series: [
      {
        name: '平均健康度',
        type: 'line',
        data: reportData.map((item) => item.healthScore),
        smooth: true,
        itemStyle: { color: '#52c41a' },
      },
      {
        name: 'A级设备',
        type: 'bar',
        yAxisIndex: 1,
        data: reportData.map(() => Math.floor(Math.random() * 5 + 3)),
        itemStyle: { color: '#73d13d' },
      },
    ],
  };

  // 告警统计报表
  const alarmOption = {
    title: { text: '告警统计报表' },
    tooltip: { trigger: 'axis' },
    legend: { data: ['告警总数', '严重告警', '已处理'] },
    xAxis: {
      type: 'category',
      data: reportData.map((item) => item.date),
    },
    yAxis: {
      type: 'value',
      name: '告警数',
    },
    series: [
      {
        name: '告警总数',
        type: 'bar',
        data: reportData.map((item) => item.alarmCount),
        itemStyle: { color: '#1890ff' },
      },
      {
        name: '严重告警',
        type: 'bar',
        data: reportData.map((item) => item.criticalAlarms),
        itemStyle: { color: '#f5222d' },
      },
      {
        name: '已处理',
        type: 'line',
        data: reportData.map((item) => Math.floor(item.alarmCount * 0.8)),
        smooth: true,
        itemStyle: { color: '#52c41a' },
      },
    ],
  };

  // 工单统计报表
  const workOrderOption = {
    title: { text: '工单处理报表' },
    tooltip: { trigger: 'axis' },
    legend: { data: ['新增工单', '已完成工单', '平均响应时间'] },
    xAxis: {
      type: 'category',
      data: reportData.map((item) => item.date),
    },
    yAxis: [
      {
        type: 'value',
        name: '工单数',
        position: 'left',
      },
      {
        type: 'value',
        name: '响应时间(分钟)',
        position: 'right',
      },
    ],
    series: [
      {
        name: '新增工单',
        type: 'bar',
        data: reportData.map((item) => item.workOrderCount),
        itemStyle: { color: '#faad14' },
      },
      {
        name: '已完成工单',
        type: 'bar',
        data: reportData.map((item) => item.resolvedOrders),
        itemStyle: { color: '#52c41a' },
      },
      {
        name: '平均响应时间',
        type: 'line',
        yAxisIndex: 1,
        data: reportData.map((item) => item.avgResponseTime),
        smooth: true,
        itemStyle: { color: '#722ed1' },
      },
    ],
  };

  // 统计汇总
  const summaryData = {
    avgHealth: reportData.reduce((sum, item) => sum + item.healthScore, 0) / reportData.length || 0,
    totalAlarms: reportData.reduce((sum, item) => sum + item.alarmCount, 0),
    totalWorkOrders: reportData.reduce((sum, item) => sum + item.workOrderCount, 0),
    avgResponseTime: reportData.reduce((sum, item) => sum + item.avgResponseTime, 0) / reportData.length || 0,
  };

  const columns = [
    { title: '日期', dataIndex: 'date', key: 'date' },
    {
      title: '健康度',
      dataIndex: 'healthScore',
      key: 'healthScore',
      render: (val: number) => `${val.toFixed(1)}分`,
    },
    { title: '告警数', dataIndex: 'alarmCount', key: 'alarmCount' },
    { title: '严重告警', dataIndex: 'criticalAlarms', key: 'criticalAlarms' },
    { title: '新增工单', dataIndex: 'workOrderCount', key: 'workOrderCount' },
    { title: '完成工单', dataIndex: 'resolvedOrders', key: 'resolvedOrders' },
    {
      title: '响应时间',
      dataIndex: 'avgResponseTime',
      key: 'avgResponseTime',
      render: (val: number) => `${val}分钟`,
    },
  ];

  const getChartOption = () => {
    switch (reportType) {
      case 'health':
        return healthOption;
      case 'alarm':
        return alarmOption;
      case 'workorder':
        return workOrderOption;
      default:
        return healthOption;
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      {/* 顶部筛选 */}
      <Card style={{ marginBottom: 16 }}>
        <Space>
          <Select value={reportType} onChange={setReportType} style={{ width: 150 }}>
            <Option value="health">健康度报表</Option>
            <Option value="alarm">告警统计报表</Option>
            <Option value="workorder">工单处理报表</Option>
          </Select>
          <RangePicker
            value={dateRange}
            onChange={(dates) => setDateRange(dates as [any, any])}
          />
          <Button type="primary" onClick={loadReportData} loading={loading}>
            生成报表
          </Button>
          <Button icon={<FileExcelOutlined />} onClick={exportReport}>
            导出Excel
          </Button>
        </Space>
      </Card>

      {/* 汇总指标 */}
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="平均健康度"
              value={summaryData.avgHealth.toFixed(1)}
              suffix="分"
              prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="总告警数"
              value={summaryData.totalAlarms}
              suffix="条"
              prefix={<WarningOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="总工单数"
              value={summaryData.totalWorkOrders}
              suffix="个"
              prefix={<ToolOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="平均响应时间"
              value={summaryData.avgResponseTime.toFixed(0)}
              suffix="分钟"
              prefix={<DownloadOutlined />}
            />
          </Card>
        </Col>
      </Row>

      {/* 图表 */}
      <Row gutter={[16, 16]}>
        <Col xs={24}>
          <Card>
            <ReactECharts option={getChartOption()} style={{ height: 400 }} />
          </Card>
        </Col>
      </Row>

      {/* 数据表格 */}
      <Row gutter={[16, 16]}>
        <Col xs={24}>
          <Card title="详细数据">
            <Table
              dataSource={reportData}
              columns={columns}
              rowKey="date"
              loading={loading}
              pagination={{ pageSize: 10 }}
            />
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Reports;