/**
 * 二维码批量打印页面
 * 
 * 功能：
 * 1. 按站点批量生成二维码
 * 2. 选择单个设备生成
 * 3. 一页多张打印布局（节省纸张）
 * 4. 打印预览和导出
 */
import React, { useState, useEffect } from 'react';
import {
  Card,
  Row,
  Col,
  Button,
  Select,
  Table,
  Checkbox,
  Space,
  Typography,
  message,
  Modal,
  InputNumber,
  Divider,
  Tag,
  Image
} from 'antd';
import {
  PrinterOutlined,
  DownloadOutlined,
  QrcodeOutlined,
  SettingOutlined
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';

const { Title, Text } = Typography;

interface Device {
  id: number;
  code: string;
  name: string;
  type: string;
  status: string;
  station_id: number;
  station_name?: string;
}

interface QrCodePrint {
  device_id: number;
  device_code: string;
  device_name: string;
  qr_code: string;
  selected: boolean;
}

/**
 * 二维码打印页面组件
 */
const QrcodePrintPage: React.FC = () => {
  const [stations, setStations] = useState<any[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);
  const [qrcodes, setQrcodes] = useState<QrCodePrint[]>([]);
  const [selectedDevices, setSelectedDevices] = useState<number[]>([]);
  
  const [printLayout, setPrintLayout] = useState<'2x2' | '3x3' | '4x4'>('2x2');
  const [qrSize, setQrSize] = useState<number>(150);
  const [previewVisible, setPreviewVisible] = useState(false);
  
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchStations();
    fetchDevices();
  }, []);

  const fetchStations = async () => {
    try {
      const response = await fetch('/api/v1/stations');
      const data = await response.json();
      setStations(data.data || []);
    } catch (error) {
      message.error('获取站点失败');
    }
  };

  const fetchDevices = async () => {
    try {
      const response = await fetch('/api/v1/devices?limit=200');
      const data = await response.json();
      setDevices(data.data || []);
    } catch (error) {
      message.error('获取设备失败');
    }
  };

  // 生成单个设备二维码
  const generateSingleQrcode = async (deviceId: number) => {
    try {
      const response = await fetch(`/api/v1/scan/devices/${deviceId}/qrcode`);
      const data = await response.json();
      return data;
    } catch (error) {
      console.error('生成二维码失败', error);
      return null;
    }
  };

  // 按站点批量生成
  const generateByStation = async (stationId: number) => {
    setLoading(true);
    try {
      // 使用云端网关二维码API
      const response = await fetch(`/api/v1/gateway-qrcode/batch/${stationId}`);
      
      const data = await response.json();
      if (data.qrcodes) {
        // 适配字段名：gateway -> device
        const prints: QrCodePrint[] = data.qrcodes.map((qr: any) => ({
          device_id: qr.gateway_id,
          device_code: qr.sn || qr.gateway_name,
          device_name: qr.gateway_name,
          qr_code: `data:image/png;base64,${qr.qr_image}`,
          selected: true
        }));
        setQrcodes(prints);
        setSelectedDevices(prints.map(p => p.device_id));
        message.success(`已生成 ${prints.length} 个二维码`);
      }
    } catch (error) {
      message.error('批量生成失败');
    } finally {
      setLoading(false);
    }
  };

  // 选择设备变化
  const handleSelectChange = (deviceId: number, checked: boolean) => {
    const newQrcodes = qrcodes.map(q => 
      q.device_id === deviceId ? { ...q, selected: checked } : q
    );
    setQrcodes(newQrcodes);
    
    if (checked) {
      setSelectedDevices([...selectedDevices, deviceId]);
    } else {
      setSelectedDevices(selectedDevices.filter(id => id !== deviceId));
    }
  };

  // 打印预览
  const openPrintPreview = () => {
    if (selectedDevices.length === 0) {
      message.warning('请选择要打印的设备');
      return;
    }
    setPreviewVisible(true);
  };

  // 执行打印
  const handlePrint = () => {
    // 打开新窗口进行打印
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      message.error('无法打开打印窗口');
      return;
    }
    
    // 计算布局
    const layoutMap = {
      '2x2': { cols: 2, rows: 2 },
      '3x3': { cols: 3, rows: 3 },
      '4x4': { cols: 4, rows: 4 }
    };
    const layout = layoutMap[printLayout];
    const perPage = layout.cols * layout.rows;
    
    // 生成打印内容
    const selectedQrcodes = qrcodes.filter(q => q.selected);
    let html = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>设备二维码打印</title>
        <style>
          body {
            font-family: Arial, sans-serif;
            padding: 20px;
            background: white;
          }
          .page {
            width: 210mm;
            height: 297mm;
            page-break-after: always;
            display: grid;
            grid-template-columns: repeat(${layout.cols}, 1fr);
            grid-template-rows: repeat(${layout.rows}, 1fr);
            gap: 10px;
            padding: 10mm;
          }
          .qr-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            border: 1px solid #ddd;
            padding: 10px;
            text-align: center;
          }
          .qr-code {
            width: ${qrSize}px;
            height: ${qrSize}px;
            margin-bottom: 10px;
          }
          .device-code {
            font-size: 14px;
            font-weight: bold;
            color: #333;
          }
          .device-name {
            font-size: 12px;
            color: #666;
            margin-top: 5px;
          }
          @media print {
            .page {
              border: none;
              padding: 0;
            }
            .qr-item {
              border: 1px dashed #ccc;
            }
          }
        </style>
      </head>
      <body>
    `;
    
    // 分页生成
    for (let i = 0; i < selectedQrcodes.length; i += perPage) {
      html += '<div class="page">';
      for (let j = i; j < Math.min(i + perPage, selectedQrcodes.length); j++) {
        const qr = selectedQrcodes[j];
        html += `
          <div class="qr-item">
            <img class="qr-code" src="${qr.qr_code}" alt="QR Code" />
            <div class="device-code">${qr.device_code}</div>
            <div class="device-name">${qr.device_name}</div>
          </div>
        `;
      }
      html += '</div>';
    }
    
    html += `
      </body>
      </html>
    `;
    
    printWindow.document.write(html);
    printWindow.document.close();
    
    // 延迟打印（等待图片加载）
    setTimeout(() => {
      printWindow.print();
    }, 500);
    
    setPreviewVisible(false);
    message.success('打印窗口已打开');
  };

  // 导出为图片包
  const exportAsImages = () => {
    const selectedQrcodes = qrcodes.filter(q => q.selected);
    
    selectedQrcodes.forEach(qr => {
      const link = document.createElement('a');
      link.href = qr.qr_code;
      link.download = `${qr.device_code}_qrcode.png`;
      link.click();
    });
    
    message.success(`已导出 ${selectedQrcodes.length} 个二维码图片`);
  };

  // 表格列定义
  const columns: ColumnsType<QrCodePrint> = [
    {
      title: '选择',
      width: 60,
      render: (_, record) => (
        <Checkbox 
          checked={record.selected}
          onChange={(e) => handleSelectChange(record.device_id, e.target.checked)}
        />
      )
    },
    {
      title: '二维码',
      dataIndex: 'qr_code',
      width: 100,
      render: (qr_code: string) => (
        <Image 
          src={qr_code} 
          width={60} 
          height={60}
          alt="QR Code"
        />
      )
    },
    {
      title: '设备编码',
      dataIndex: 'device_code',
      width: 150
    },
    {
      title: '设备名称',
      dataIndex: 'device_name',
      width: 150
    },
    {
      title: '状态',
      dataIndex: 'status',
      width: 80,
      render: () => <Tag color="green">已生成</Tag>
    }
  ];

  return (
    <div style={{ padding: 24 }}>
      <Title level={2}>
        <PrinterOutlined /> 二维码批量打印
      </Title>
      
      {/* 操作区 */}
      <Card style={{ marginBottom: 24 }}>
        <Row gutter={16} align="middle">
          <Col span={6}>
            <Text>选择站点：</Text>
            <Select
              style={{ width: '100%', marginTop: 8 }}
              placeholder="选择站点批量生成"
              onChange={(value) => generateByStation(value)}
              loading={loading}
              options={stations.map(s => ({ 
                label: s.name, 
                value: s.id 
              }))}
            />
          </Col>
          
          <Col span={4}>
            <Text>布局：</Text>
            <Select
              style={{ width: '100%', marginTop: 8 }}
              value={printLayout}
              onChange={setPrintLayout}
              options={[
                { label: '2x2 (一页4张)', value: '2x2' },
                { label: '3x3 (一页9张)', value: '3x3' },
                { label: '4x4 (一页16张)', value: '4x4' }
              ]}
            />
          </Col>
          
          <Col span={3}>
            <Text>二维码尺寸：</Text>
            <InputNumber
              style={{ width: '100%', marginTop: 8 }}
              value={qrSize}
              onChange={(v) => setQrSize(v || 150)}
              min={100}
              max={300}
              step={10}
            />
          </Col>
          
          <Col span={6}>
            <Space>
              <Button
                type="primary"
                icon={<PrinterOutlined />}
                onClick={openPrintPreview}
                disabled={selectedDevices.length === 0}
              >
                打印预览
              </Button>
              <Button
                icon={<DownloadOutlined />}
                onClick={exportAsImages}
                disabled={selectedDevices.length === 0}
              >
                导出图片
              </Button>
            </Space>
          </Col>
          
          <Col span={5}>
            <Text type="secondary">
              已选择 {selectedDevices.length} 个设备
            </Text>
          </Col>
        </Row>
      </Card>
      
      {/* 二维码列表 */}
      <Card>
        <Table
          columns={columns}
          dataSource={qrcodes}
          rowKey="device_id"
          pagination={{
            pageSize: 20,
            showTotal: (total) => `共 ${total} 个二维码`
          }}
          loading={loading}
        />
      </Card>
      
      {/* 打印预览弹窗 */}
      <Modal
        title="打印预览"
        open={previewVisible}
        onCancel={() => setPreviewVisible(false)}
        width={800}
        footer={[
          <Button key="cancel" onClick={() => setPreviewVisible(false)}>
            取消
          </Button>,
          <Button key="print" type="primary" icon={<PrinterOutlined />} onClick={handlePrint}>
            打印
          </Button>
        ]}
      >
        <div style={{ marginBottom: 16 }}>
          <Text>布局：{printLayout}，每页 {printLayout === '2x2' ? 4 : printLayout === '3x3' ? 9 : 16} 张</Text>
          <Divider />
          <Text>将打印 {selectedDevices.length} 个二维码，需要 {Math.ceil(selectedDevices.length / (printLayout === '2x2' ? 4 : printLayout === '3x3' ? 9 : 16))} 页</Text>
        </div>
        
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: printLayout === '2x2' ? 'repeat(2, 1fr)' : printLayout === '3x3' ? 'repeat(3, 1fr)' : 'repeat(4, 1fr)',
          gap: 10,
          maxHeight: 400,
          overflow: 'auto',
          padding: 10
        }}>
          {qrcodes.filter(q => q.selected).slice(0, printLayout === '2x2' ? 4 : printLayout === '3x3' ? 9 : 16).map(qr => (
            <div key={qr.device_id} style={{ 
              textAlign: 'center', 
              border: '1px dashed #ccc', 
              padding: 10 
            }}>
              <Image src={qr.qr_code} width={qrSize * 0.6} height={qrSize * 0.6} />
              <div style={{ fontSize: 12, marginTop: 5 }}>{qr.device_code}</div>
            </div>
          ))}
        </div>
      </Modal>
    </div>
  );
};

export default QrcodePrintPage;