/**
 * 健康巡检页面
 */
import React, { useState } from 'react';
import { Card, Row, Col, Table, Button, Tag, Space, Progress, Statistic, Modal, Steps, Form, Select, DatePicker, message } from 'antd';
import { 
  CheckCircleOutlined, WarningOutlined, SyncOutlined, 
  PlayCircleOutlined, FileTextOutlined, CalendarOutlined 
} from '@ant-design/icons';

const { Option } = Select;

const HealthPage: React.FC = () => {
  const [detailVisible, setDetailVisible] = useState(false);
  const [selectedItem, setSelectedItem] = useState<any>(null);

  const stats = {
    totalTasks: 24,
    completed: 18,
    pending: 4,
    abnormal: 2,
  };

  const tasks = [
    { id: '1', name: '浦东站-日常巡检', type: 'routine', station: '浦东站', schedule: '2026-03-27', status: 'completed', score: 95, items: 28, passed: 27 },
    { id: '2', name: '浦西站-日常巡检', type: 'routine', station: '浦西站', schedule: '2026-03-27', status: 'in_progress', score: 0, items: 28, passed: 0 },
    { id: '3', name: '光伏设备专项', type: 'special', station: '浦东站', schedule: '2026-03-26', status: 'completed', score: 88, items: 15, passed: 13 },
    { id: '4', name: '储能系统检测', type: 'special', station: '浦西站', schedule: '2026-03-25', status: 'abnormal', score: 65, items: 20, passed: 13 },
    { id: '5', name: '充电桩月检', type: 'monthly', station: '浦东站', schedule: '2026-03-20', status: 'completed', score: 100, items: 30, passed: 30 },
  ];

  const checkItems = [
    { name: '设备外观检查', status: 'passed', remark: '正常' },
    { name: '接线端子检查', status: 'passed', remark: '正常' },
    { name: '绝缘电阻测试', status: 'warning', remark: '偏低' },
    { name: '接地电阻测试', status: 'passed', remark: '4.2Ω' },
    { name: '通讯测试', status: 'passed', remark: '正常' },
    { name: '保护功能测试', status: 'passed', remark: '正常' },
  ];

  const getStatusTag = (status: string) => {
    const map: Record<string, { color: string; text: string }> = {
      completed: { color: 'green', text: '已完成' },
      in_progress: { color: 'blue', text: '进行中' },
      pending: { color: 'default', text: '待执行' },
      abnormal: { color: 'red', text: '异常' },
    };
    return map[status] || { color: 'default', text: status };
  };

  const getTypeTag = (type: string) => {
    const map: Record<string, { color: string; text: string }> = {
      routine: { color: 'blue', text: '日常巡检' },
      special: { color: 'orange', text: '专项检查' },
      monthly: { color: 'purple', text: '月度检测' },
    };
    return map[type] || { color: 'default', text: type };
  };

  const columns = [
    { title: '任务名称', dataIndex: 'name', key: 'name' },
    { 
      title: '类型', 
      dataIndex: 'type', 
      key: 'type',
      render: (type: string) => <Tag color={getTypeTag(type).color}>{getTypeTag(type).text}</Tag>
    },
    { title: '站点', dataIndex: 'station', key: 'station' },
    { title: '计划日期', dataIndex: 'schedule', key: 'schedule' },
    { 
      title: '状态', 
      dataIndex: 'status', 
      key: 'status',
      render: (status: string) => <Tag color={getStatusTag(status).color}>{getStatusTag(status).text}</Tag>
    },
    { 
      title: '得分', 
      dataIndex: 'score', 
      key: 'score',
      render: (score: number, record: any) => (
        score > 0 ? (
          <Progress 
            type="circle" 
            percent={score} 
            width={40}
            strokeColor={score >= 90 ? '#52c41a' : score >= 60 ? '#faad14' : '#ff4d4f'} 
          />
        ) : '-'
      )
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: any) => (
        <Space>
          {record.status === 'pending' && (
            <Button type="primary" size="small" icon={<PlayCircleOutlined />}>
              开始
            </Button>
          )}
          <Button size="small" type="link" onClick={() => {
            setSelectedItem(record);
            setDetailVisible(true);
          }}>
            详情
          </Button>
        </Space>
      ),
    },
  ];

  return (
    <div>
      {/* 统计 */}
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="巡检任务" value={stats.totalTasks} prefix={<FileTextOutlined />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="已完成" value={stats.completed} prefix={<CheckCircleOutlined />} valueStyle={{ color: '#52c41a' }} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="待执行" value={stats.pending} prefix={<CalendarOutlined />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="异常" value={stats.abnormal} prefix={<WarningOutlined />} valueStyle={{ color: '#ff4d4f' }} />
          </Card>
        </Col>
      </Row>

      <Card>
        <div style={{ marginBottom: 16 }}>
          <Space>
            <Button type="primary" icon={<PlayCircleOutlined />}>
              新建巡检任务
            </Button>
            <Button icon={<SyncOutlined />}>刷新</Button>
          </Space>
        </div>

        <Table
          columns={columns}
          dataSource={tasks}
          rowKey="id"
        />
      </Card>

      {/* 巡检详情弹窗 */}
      <Modal
        title="巡检详情"
        open={detailVisible}
        onCancel={() => setDetailVisible(false)}
        footer={[
          <Button key="close" onClick={() => setDetailVisible(false)}>
            关闭
          </Button>,
        ]}
        width={700}
      >
        {selectedItem && (
          <div>
            <Progress percent={selectedItem.status === 'completed' ? 100 : selectedItem.status === 'in_progress' ? 50 : 0} status="active" />

            <Row gutter={16}>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>任务名称</div>
                  <div>{selectedItem.name}</div>
                </div>
              </Col>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>得分</div>
                  <Progress 
                    percent={selectedItem.score} 
                    strokeColor={selectedItem.score >= 90 ? '#52c41a' : '#faad14'} 
                  />
                </div>
              </Col>
            </Row>

            <h4>巡检项目</h4>
            <Table
              dataSource={checkItems}
              columns={[
                { title: '项目', dataIndex: 'name', key: 'name' },
                { 
                  title: '状态', 
                  dataIndex: 'status', 
                  key: 'status',
                  render: (s: string) => (
                    <Tag color={s === 'passed' ? 'green' : s === 'warning' ? 'orange' : 'red'}>
                      {s === 'passed' ? '通过' : s === 'warning' ? '警告' : '不通过'}
                    </Tag>
                  )
                },
                { title: '备注', dataIndex: 'remark', key: 'remark' },
              ]}
              rowKey="name"
              pagination={false}
              size="small"
            />
          </div>
        )}
      </Modal>
    </div>
  );
};

export default HealthPage;