/**
 * 工单管理页面 - 天链运维平台
 */
import React, { useState, useEffect } from 'react';
import { 
  Card, Table, Button, Space, Input, Tag, Modal, Form, Row, Col, 
  message, Descriptions, Progress, Select, Tabs, Timeline, Badge, Statistic
} from 'antd';
import { 
  PlusOutlined, SearchOutlined, EditOutlined, DeleteOutlined, 
  ToolOutlined, CheckCircleOutlined, ClockCircleOutlined,
  UserOutlined, EnvironmentOutlined 
} from '@ant-design/icons';
import api from '../../api';

interface WorkOrder {
  id: number;
  title: string;
  description: string;
  priority: string;
  type: string;
  device_id?: number;
  device_name?: string;
  station_id?: number;
  station_name?: string;
  assignee?: string;
  status: string;
  progress?: number;
  created_at: string;
  updated_at: string;
}

const WorkOrdersPage: React.FC = () => {
  const [workorders, setWorkorders] = useState<WorkOrder[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [detailVisible, setDetailVisible] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);
  const [form] = Form.useForm();
  const [searchText, setSearchText] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');

  useEffect(() => {
    loadWorkOrders();
  }, [statusFilter, priorityFilter]);

  const loadWorkOrders = async () => {
    setLoading(true);
    try {
      const params: any = { limit: 50 };
      if (statusFilter !== 'all') params.status = statusFilter;
      if (priorityFilter !== 'all') params.priority = priorityFilter;
      
      const res = await api.get('/api/v1/workorders', { params });
      setWorkorders(res.data?.data || []);
    } catch (error) {
      message.error('加载工单失败');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    form.resetFields();
    setSelectedOrder(null);
    setModalVisible(true);
  };

  const handleEdit = (order: WorkOrder) => {
    setSelectedOrder(order);
    form.setFieldsValue(order);
    setModalVisible(true);
  };

  const handleDelete = async (id: number) => {
    try {
      await api.delete(`/api/v1/workorders/${id}`);
      message.success('工单删除成功');
      loadWorkOrders();
    } catch (error) {
      message.error('删除失败');
    }
  };

  const handleViewDetail = async (id: number) => {
    try {
      const res = await api.get(`/api/v1/workorders/${id}`);
      setSelectedOrder(res.data);
      setDetailVisible(true);
    } catch (error) {
      message.error('加载详情失败');
    }
  };

  const handleComplete = async (id: number) => {
    try {
      await api.post(`/api/v1/workorders/${id}/complete`, { notes: '已完成维修' });
      message.success('工单已完成');
      loadWorkOrders();
    } catch (error) {
      message.error('操作失败');
    }
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      if (selectedOrder) {
        await api.put(`/api/v1/workorders/${selectedOrder.id}`, values);
        message.success('工单更新成功');
      } else {
        await api.post('/api/v1/workorders', values);
        message.success('工单创建成功');
      }
      setModalVisible(false);
      loadWorkOrders();
    } catch (error) {
      message.error('操作失败');
    }
  };

  const filteredOrders = workorders.filter(o => 
    o.title.includes(searchText) || o.device_name?.includes(searchText) || o.assignee?.includes(searchText)
  );

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'red';
      case 'medium': return 'orange';
      case 'low': return 'green';
      default: return 'default';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'default';
      case 'processing': return 'blue';
      case 'completed': return 'green';
      case 'closed': return 'gray';
      default: return 'default';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'pending': return '待处理';
      case 'processing': return '进行中';
      case 'completed': return '已完成';
      case 'closed': return '已关闭';
      default: return status;
    }
  };

  const getTypeText = (type: string) => {
    switch (type) {
      case 'repair': return '故障维修';
      case 'maintenance': return '定期巡检';
      case 'install': return '设备安装';
      case 'upgrade': return '系统升级';
      default: return type;
    }
  };

  const columns = [
    { title: '工单ID', dataIndex: 'id', key: 'id', width: 80 },
    { title: '标题', dataIndex: 'title', key: 'title', width: 200 },
    { title: '类型', dataIndex: 'type', key: 'type', width: 100,
      render: (type: string) => <Tag>{getTypeText(type)}</Tag> },
    { title: '优先级', dataIndex: 'priority', key: 'priority', width: 80,
      render: (priority: string) => <Tag color={getPriorityColor(priority)}>{priority}</Tag> },
    { title: '设备', dataIndex: 'device_name', key: 'device_name', width: 120,
      render: (text: string) => text || '-' },
    { title: '站点', dataIndex: 'station_name', key: 'station_name', width: 120,
      render: (text: string) => text ? <span><EnvironmentOutlined /> {text}</span> : '-' },
    { title: '负责人', dataIndex: 'assignee', key: 'assignee', width: 100,
      render: (text: string) => text ? <span><UserOutlined /> {text}</span> : '待分配' },
    { title: '进度', dataIndex: 'progress', key: 'progress', width: 100,
      render: (progress: number) => progress ? <Progress percent={progress} size="small" /> : '-' },
    { title: '状态', dataIndex: 'status', key: 'status', width: 100,
      render: (status: string) => <Tag color={getStatusColor(status)}>{getStatusText(status)}</Tag> },
    { title: '创建时间', dataIndex: 'created_at', key: 'created_at', width: 150,
      render: (text: string) => new Date(text).toLocaleString() },
    { title: '操作', key: 'action', width: 180, fixed: 'right' as const,
      render: (record: WorkOrder) => (
        <Space size="small">
          <Button type="link" size="small" onClick={() => handleViewDetail(record.id)}>详情</Button>
          {record.status === 'pending' && (
            <Button type="link" size="small" onClick={() => handleEdit(record)}>编辑</Button>
          )}
          {record.status === 'processing' && (
            <Button type="link" size="small" style={{ color: '#52c41a' }}
              onClick={() => handleComplete(record.id)}>完成</Button>
          )}
          {record.status === 'pending' && (
            <Button type="link" size="small" danger onClick={() => handleDelete(record.id)}>删除</Button>
          )}
        </Space>
      ) },
  ];

  const pendingOrders = filteredOrders.filter(o => o.status === 'pending');
  const processingOrders = filteredOrders.filter(o => o.status === 'processing');
  const completedOrders = filteredOrders.filter(o => o.status === 'completed' || o.status === 'closed');

  return (
    <div style={{ padding: '20px' }}>
      <Card>
        <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
          <Col span={6}>
            <Statistic title="工单总数" value={workorders.length} suffix="个" prefix={<ToolOutlined />} />
          </Col>
          <Col span={6}>
            <Statistic title="待处理" value={pendingOrders.length} suffix="个" 
              valueStyle={{ color: pendingOrders.length > 5 ? '#f5222d' : '#faad14' }} />
          </Col>
          <Col span={6}>
            <Statistic title="进行中" value={processingOrders.length} suffix="个" 
              prefix={<ClockCircleOutlined />} valueStyle={{ color: '#1890ff' }} />
          </Col>
          <Col span={6}>
            <Statistic title="已完成" value={completedOrders.length} suffix="个" 
              prefix={<CheckCircleOutlined />} valueStyle={{ color: '#52c41a' }} />
          </Col>
        </Row>

        <Space style={{ marginBottom: 16 }}>
          <Input.Search placeholder="搜索工单" value={searchText} onChange={e => setSearchText(e.target.value)}
            style={{ width: 200 }} allowClear />
          <Select value={statusFilter} onChange={setStatusFilter} style={{ width: 120 }}>
            <Select.Option value="all">全部状态</Select.Option>
            <Select.Option value="pending">待处理</Select.Option>
            <Select.Option value="processing">进行中</Select.Option>
            <Select.Option value="completed">已完成</Select.Option>
          </Select>
          <Select value={priorityFilter} onChange={setPriorityFilter} style={{ width: 120 }}>
            <Select.Option value="all">全部优先级</Select.Option>
            <Select.Option value="high">高</Select.Option>
            <Select.Option value="medium">中</Select.Option>
            <Select.Option value="low">低</Select.Option>
          </Select>
          <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>新建工单</Button>
          <Button icon={<SearchOutlined />} onClick={loadWorkOrders}>刷新</Button>
        </Space>

        <Table dataSource={filteredOrders} columns={columns} rowKey="id" 
          loading={loading} scroll={{ x: 1500 }} pagination={{ pageSize: 15 }} />
      </Card>

      {/* 创建/编辑模态框 */}
      <Modal title={selectedOrder ? '编辑工单' : '新建工单'} open={modalVisible} 
        onOk={handleSubmit} onCancel={() => setModalVisible(false)} width={700}>
        <Form form={form} layout="vertical">
          <Form.Item name="title" label="工单标题" rules={[{ required: true }]}>
            <Input placeholder="如 设备故障维修" />
          </Form.Item>
          <Form.Item name="description" label="描述">
            <Input.TextArea rows={3} placeholder="工单详细描述" />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="type" label="工单类型" rules={[{ required: true }]}>
                <Select placeholder="选择类型">
                  <Select.Option value="repair">故障维修</Select.Option>
                  <Select.Option value="maintenance">定期巡检</Select.Option>
                  <Select.Option value="install">设备安装</Select.Option>
                  <Select.Option value="upgrade">系统升级</Select.Option>
                </Select>
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="priority" label="优先级" rules={[{ required: true }]}>
                <Select placeholder="选择优先级">
                  <Select.Option value="high">高</Select.Option>
                  <Select.Option value="medium">中</Select.Option>
                  <Select.Option value="low">低</Select.Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="device_id" label="关联设备">
                <Input placeholder="设备ID" type="number" />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="station_id" label="站点">
                <Input placeholder="站点ID" type="number" />
              </Form.Item>
            </Col>
          </Row>
          <Form.Item name="assignee" label="负责人">
            <Input placeholder="负责人姓名" />
          </Form.Item>
        </Form>
      </Modal>

      {/* 详情模态框 */}
      <Modal title="工单详情" open={detailVisible} onCancel={() => setDetailVisible(false)}
        footer={null} width={800}>
        {selectedOrder && (
          <Tabs defaultActiveKey="1">
            <Tabs.TabPane tab="基本信息" key="1">
              <Descriptions bordered column={2}>
                <Descriptions.Item label="工单ID">{selectedOrder.id}</Descriptions.Item>
                <Descriptions.Item label="标题">{selectedOrder.title}</Descriptions.Item>
                <Descriptions.Item label="类型">{getTypeText(selectedOrder.type)}</Descriptions.Item>
                <Descriptions.Item label="优先级">
                  <Tag color={getPriorityColor(selectedOrder.priority)}>{selectedOrder.priority}</Tag>
                </Descriptions.Item>
                <Descriptions.Item label="设备">{selectedOrder.device_name || '-'}</Descriptions.Item>
                <Descriptions.Item label="站点">{selectedOrder.station_name || '-'}</Descriptions.Item>
                <Descriptions.Item label="负责人">{selectedOrder.assignee || '待分配'}</Descriptions.Item>
                <Descriptions.Item label="状态">
                  <Tag color={getStatusColor(selectedOrder.status)}>{getStatusText(selectedOrder.status)}</Tag>
                </Descriptions.Item>
                <Descriptions.Item label="进度">
                  <Progress percent={selectedOrder.progress || 0} />
                </Descriptions.Item>
                <Descriptions.Item label="创建时间">
                  {new Date(selectedOrder.created_at).toLocaleString()}
                </Descriptions.Item>
                <Descriptions.Item label="描述" span={2}>{selectedOrder.description || '-'}</Descriptions.Item>
              </Descriptions>
            </Tabs.TabPane>
            <Tabs.TabPane tab="处理进度" key="2">
              <Timeline>
                <Timeline.Item color="blue">工单创建 - {new Date(selectedOrder.created_at).toLocaleString()}</Timeline.Item>
                {selectedOrder.status !== 'pending' && (
                  <Timeline.Item color="blue">开始处理 - {new Date(selectedOrder.updated_at).toLocaleString()}</Timeline.Item>
                )}
                {selectedOrder.status === 'completed' && (
                  <Timeline.Item color="green">已完成 - {new Date(selectedOrder.updated_at).toLocaleString()}</Timeline.Item>
                )}
              </Timeline>
            </Tabs.TabPane>
          </Tabs>
        )}
      </Modal>
    </div>
  );
};

export default WorkOrdersPage;