/**
 * 角色权限管理页面
 */
import React, { useState } from 'react';
import { Card, Table, Button, Space, Tag, Modal, Form, Input, Select, Transfer, Tabs, Row, Col, message, Popconfirm, Badge, Avatar } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, UserOutlined, LockOutlined, KeyOutlined, TeamOutlined } from '@ant-design/icons';

const { Option } = Select;

// 角色数据
const roles = [
  { id: '1', name: '超级管理员', code: 'admin', users: 2, permissions: ['*'], desc: '拥有所有权限', status: 'active' },
  { id: '2', name: '运维管理员', code: 'operator', users: 5, permissions: ['devices', 'alarms', 'health', 'monitor'], desc: '设备运维管理', status: 'active' },
  { id: '3', name: '值班员', code: 'watcher', users: 8, permissions: ['monitor', 'alarms'], desc: '监控和告警查看', status: 'active' },
  { id: '4', name: '访客', code: 'guest', users: 15, permissions: ['dashboard'], desc: '只读访问', status: 'active' },
];

// 用户数据
const users = [
  { id: '1', username: 'admin', name: '系统管理员', role: '超级管理员', email: 'admin@tianlian.com', phone: '138****0001', status: 'active', lastLogin: '2026-03-27 10:30' },
  { id: '2', username: 'zhangsan', name: '张三', role: '运维管理员', email: 'zhangsan@tianlian.com', phone: '138****0002', status: 'active', lastLogin: '2026-03-27 09:15' },
  { id: '3', username: 'lisi', name: '李四', role: '运维管理员', email: 'lisi@tianlian.com', phone: '138****0003', status: 'active', lastLogin: '2026-03-27 08:45' },
  { id: '4', username: 'wangwu', name: '王五', role: '值班员', email: 'wangwu@tianlian.com', phone: '138****0004', status: 'active', lastLogin: '2026-03-26 22:30' },
  { id: '5', username: 'zhaoliu', name: '赵六', role: '值班员', email: 'zhaoliu@tianlian.com', phone: '138****0005', status: 'disabled', lastLogin: '2026-03-20 14:20' },
];

// 权限列表
const allPermissions = [
  { key: 'dashboard', name: '首页仪表盘', category: '通用' },
  { key: 'devices', name: '设备管理', category: '设备' },
  { key: 'remote-control', name: '远程控制', category: '设备' },
  { key: 'monitor', name: '动态监控', category: '监控' },
  { key: 'alarms', name: '告警概览', category: '告警' },
  { key: 'alarm-notices', name: '告警通知', category: '告警' },
  { key: 'health', name: '健康巡检', category: '运维' },
  { key: 'security', name: '安全增强', category: '运维' },
  { key: 'map', name: '站点地图', category: '运维' },
  { key: 'rbac', name: '角色权限', category: '系统' },
];

// 菜单权限
const menuPermissions = allPermissions.filter(p => !['rbac'].includes(p.key));

const RbacPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState('roles');
  const [roleModalVisible, setRoleModalVisible] = useState(false);
  const [userModalVisible, setUserModalVisible] = useState(false);
  const [editingRole, setEditingRole] = useState<any>(null);
  const [editingUser, setEditingUser] = useState<any>(null);
  const [form] = Form.useForm();

  // 角色表格列
  const roleColumns = [
    { title: '角色名称', dataIndex: 'name', key: 'name', render: (text: string) => <Space><LockOutlined />{text}</Space> },
    { title: '角色编码', dataIndex: 'code', key: 'code' },
    { title: '描述', dataIndex: 'desc', key: 'desc' },
    { title: '用户数', dataIndex: 'users', key: 'users', render: (num: number) => <Badge count={num} showZero style={{ backgroundColor: '#1890ff' }} /> },
    { 
      title: '状态', 
      dataIndex: 'status', 
      key: 'status',
      render: (status: string) => <Tag color={status === 'active' ? 'green' : 'default'}>{status === 'active' ? '启用' : '禁用'}</Tag>
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: any) => (
        <Space>
          <Button type="text" icon={<EditOutlined />} onClick={() => {
            setEditingRole(record);
            form.setFieldsValue(record);
            setRoleModalVisible(true);
          }} />
          <Popconfirm title="确认删除此角色?" onConfirm={() => message.success('删除成功')}>
            <Button type="text" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  // 用户表格列
  const userColumns = [
    { 
      title: '用户', 
      key: 'user',
      render: (_: any, record: any) => (
        <Space>
          <Avatar icon={<UserOutlined />} style={{ backgroundColor: record.status === 'active' ? '#1890ff' : '#d9d9d9' }} />
          <div>
            <div>{record.name}</div>
            <div style={{ fontSize: 12, color: '#8c8c8c' }}>@{record.username}</div>
          </div>
        </Space>
      )
    },
    { title: '角色', dataIndex: 'role', key: 'role', render: (role: string) => <Tag color="blue">{role}</Tag> },
    { title: '邮箱', dataIndex: 'email', key: 'email' },
    { title: '手机', dataIndex: 'phone', key: 'phone' },
    { title: '最后登录', dataIndex: 'lastLogin', key: 'lastLogin' },
    { 
      title: '状态', 
      dataIndex: 'status', 
      key: 'status',
      render: (status: string) => (
        <Tag color={status === 'active' ? 'green' : 'default'}>
          {status === 'active' ? '正常' : '禁用'}
        </Tag>
      )
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: any) => (
        <Space>
          <Button type="text" size="small" onClick={() => {
            setEditingUser(record);
            form.setFieldsValue(record);
            setUserModalVisible(true);
          }}>编辑</Button>
          <Button type="text" size="small" onClick={() => message.success('密码重置成功')}>重置密码</Button>
          <Popconfirm title="确认删除此用户?" onConfirm={() => message.success('删除成功')}>
            <Button type="text" danger size="small">删除</Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  const tabItems = [
    {
      key: 'roles',
      label: <span><LockOutlined /> 角色管理</span>,
      children: (
        <div>
          <div style={{ marginBottom: 16 }}>
            <Button type="primary" icon={<PlusOutlined />} onClick={() => {
              setEditingRole(null);
              form.resetFields();
              setRoleModalVisible(true);
            }}>
              新增角色
            </Button>
          </div>
          <Table
            columns={roleColumns}
            dataSource={roles}
            rowKey="id"
            pagination={false}
          />
        </div>
      ),
    },
    {
      key: 'users',
      label: <span><TeamOutlined /> 用户管理</span>,
      children: (
        <div>
          <div style={{ marginBottom: 16 }}>
            <Space>
              <Input.Search placeholder="搜索用户" style={{ width: 200 }} />
              <Select defaultValue="all" style={{ width: 120 }}>
                <Option value="all">全部角色</Option>
                <Option value="admin">超级管理员</Option>
                <Option value="operator">运维管理员</Option>
                <Option value="watcher">值班员</Option>
              </Select>
              <Button type="primary" icon={<PlusOutlined />} onClick={() => {
                setEditingUser(null);
                form.resetFields();
                setUserModalVisible(true);
              }}>
                新增用户
              </Button>
            </Space>
          </div>
          <Table
            columns={userColumns}
            dataSource={users}
            rowKey="id"
          />
        </div>
      ),
    },
    {
      key: 'permissions',
      label: <span><KeyOutlined /> 权限配置</span>,
      children: (
        <Card>
          <Row gutter={16}>
            {menuPermissions.map(p => (
              <Col xs={24} sm={12} md={8} key={p.key} style={{ marginBottom: 16 }}>
                <Card size="small" style={{ background: '#fafafa' }}>
                  <div style={{ fontWeight: 500 }}>{p.name}</div>
                  <div style={{ fontSize: 12, color: '#8c8c8c' }}>{p.category}</div>
                </Card>
              </Col>
            ))}
          </Row>
          <div style={{ marginTop: 16, color: '#8c8c8c' }}>
            <p>权限说明：</p>
            <ul>
              <li>超级管理员拥有所有权限</li>
              <li>运维管理员可管理设备、告警、巡检</li>
              <li>值班员只能查看监控和告警</li>
              <li>访客只能查看首页仪表盘</li>
            </ul>
          </div>
        </Card>
      ),
    },
  ];

  return (
    <div>
      <Tabs activeKey={activeTab} onChange={setActiveTab} items={tabItems} />

      {/* 角色弹窗 */}
      <Modal
        title={editingRole ? '编辑角色' : '新增角色'}
        open={roleModalVisible}
        onCancel={() => setRoleModalVisible(false)}
        onOk={() => {
          form.validateFields().then(() => {
            message.success(editingRole ? '编辑成功' : '新增成功');
            setRoleModalVisible(false);
          });
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="name" label="角色名称" rules={[{ required: true }]}>
            <Input placeholder="请输入角色名称" />
          </Form.Item>
          <Form.Item name="code" label="角色编码" rules={[{ required: true }]}>
            <Input placeholder="如: admin, operator" />
          </Form.Item>
          <Form.Item name="desc" label="描述">
            <Input.TextArea rows={2} placeholder="请输入描述" />
          </Form.Item>
          <Form.Item name="permissions" label="权限分配">
            <Select mode="multiple" placeholder="选择权限">
              {allPermissions.map(p => (
                <Option key={p.key} value={p.key}>{p.name}</Option>
              ))}
            </Select>
          </Form.Item>
        </Form>
      </Modal>

      {/* 用户弹窗 */}
      <Modal
        title={editingUser ? '编辑用户' : '新增用户'}
        open={userModalVisible}
        onCancel={() => setUserModalVisible(false)}
        onOk={() => {
          form.validateFields().then(() => {
            message.success(editingUser ? '编辑成功' : '新增成功');
            setUserModalVisible(false);
          });
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="username" label="用户名" rules={[{ required: true }]}>
            <Input placeholder="请输入用户名" />
          </Form.Item>
          <Form.Item name="name" label="姓名" rules={[{ required: true }]}>
            <Input placeholder="请输入姓名" />
          </Form.Item>
          <Form.Item name="role" label="角色" rules={[{ required: true }]}>
            <Select placeholder="选择角色">
              {roles.map(r => (
                <Option key={r.id} value={r.name}>{r.name}</Option>
              ))}
            </Select>
          </Form.Item>
          <Form.Item name="email" label="邮箱" rules={[{ required: true, type: 'email' }]}>
            <Input placeholder="请输入邮箱" />
          </Form.Item>
          <Form.Item name="phone" label="手机号" rules={[{ required: true }]}>
            <Input placeholder="请输入手机号" />
          </Form.Item>
          {!editingUser && (
            <Form.Item name="password" label="初始密码" rules={[{ required: true }]}>
              <Input.Password placeholder="请输入初始密码" />
            </Form.Item>
          )}
        </Form>
      </Modal>
    </div>
  );
};

export default RbacPage;