/**
 * 扫码报修页面 - Web端
 * 
 * 功能：
 * 1. 二维码生成（批量生成设备二维码）
 * 2. 二维码扫描（手动输入设备码）
 * 3. 一键报修（快速创建工单）
 */
import React, { useState, useEffect } from 'react';
import {
  Card,
  Row,
  Col,
  Button,
  Table,
  Modal,
  Form,
  Input,
  Select,
  message,
  Tabs,
  Statistic,
  Tag,
  Space,
  Divider,
  Image,
  Typography,
  Descriptions,
  Alert
} from 'antd';
import {
  QrcodeOutlined,
  ToolOutlined,
  HistoryOutlined,
  DownloadOutlined,
  PrinterOutlined,
  ScanOutlined,
  WarningOutlined
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';

const { Title } = Typography;
const { TextArea } = Input;

interface Device {
  id: number;
  code: string;
  name: string;
  type: string;
  status: string;
  station_id: number;
  station_name?: string;
}

interface QrCodeData {
  device_id: number;
  device_code: string;
  device_name: string;
  qr_code: string;
}

interface WorkOrder {
  id: string;
  title: string;
  device_id: number;
  device_name?: string;
  priority: string;
  status: string;
  created_at: string;
}

/**
 * 扫码报修页面组件
 */
const ScanRepairPage: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [qrcodes, setQrcodes] = useState<QrCodeData[]>([]);
  const [scannedDevice, setScannedDevice] = useState<any>(null);
  const [repairHistory, setRepairHistory] = useState<WorkOrder[]>([]);
  
  const [scanModalVisible, setScanModalVisible] = useState(false);
  const [repairModalVisible, setRepairModalVisible] = useState(false);
  const [historyModalVisible, setHistoryModalVisible] = useState(false);
  const [batchModalVisible, setBatchModalVisible] = useState(false);
  
  const [selectedStation, setSelectedStation] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  
  const [repairForm] = Form.useForm();
  const [scanForm] = Form.useForm();

  useEffect(() => {
    fetchDevices();
    fetchQrcodes();
  }, []);

  const fetchDevices = async () => {
    try {
      const response = await fetch('http://localhost:8000/api/v1/devices?limit=100');
      const data = await response.json();
      setDevices(data.items || data.devices || []);
    } catch (error) {
      message.error('加载设备列表失败');
    }
  };

  const fetchQrcodes = async () => {
    try {
      const response = await fetch('http://localhost:8000/api/v1/scan/qrcodes');
      const data = await response.json();
      setQrcodes((data.items || []).map((item: any) => ({
        device_id: item.device_id,
        device_code: item.qr_code,
        device_name: item.device_name,
        qr_code: `http://localhost:8000/api/v1/scan/qrcode/image/${item.qr_code}`
      })));
    } catch (error) {
      // 静默处理
    }
  };

  // 生成单个设备二维码
  const generateQrcode = async (deviceId: number) => {
    try {
      const response = await fetch('http://localhost:8000/api/v1/scan/qrcode/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ device_id: deviceId })
      });
      const data = await response.json();
      
      if (data.success) {
        message.success(`已生成 ${data.device_name} 的二维码: ${data.qr_code}`);
        fetchQrcodes();
      }
    } catch (error) {
      message.error('生成二维码失败');
    }
  };

  // 批量生成二维码
  const generateBatchQrcodes = async () => {
    setLoading(true);
    try {
      const devicesToProcess = selectedStation 
        ? devices.filter(d => d.station_id === selectedStation)
        : devices;
      
      let successCount = 0;
      for (const device of devicesToProcess) {
        const response = await fetch('http://localhost:8000/api/v1/scan/qrcode/generate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ device_id: device.id })
        });
        if (response.ok) successCount++;
      }
      
      message.success(`已批量生成 ${successCount} 个二维码`);
      setBatchModalVisible(false);
      fetchQrcodes();
    } catch (error) {
      message.error('批量生成失败');
    } finally {
      setLoading(false);
    }
  };

  // 扫描二维码（手动输入二维码）
  const handleScan = async (values: any) => {
    const qrCode = values.device_code;
    
    try {
      const response = await fetch('http://localhost:8000/api/v1/scan/device', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ qr_code: qrCode })
      });
      
      const data = await response.json();
      
      if (data.success) {
        setScannedDevice({
          device: {
            id: data.device_id,
            code: data.device_sn,
            name: data.device_name,
            type: data.device_type,
            status: data.device_status,
            station_name: data.station_name,
            location: data.station_address
          },
          health_score: data.health_score,
          alarms: [],
          repair_suggestions: data.device_status === 'fault' ? [{
            type: 'repair',
            title: '设备故障报修',
            priority: 'high'
          }] : []
        });
        setScanModalVisible(false);
        message.success('设备信息已识别');
      } else {
        message.error('未找到该设备');
      }
    } catch (error) {
      message.error('扫码识别失败');
    }
  };

  // 一键报修
  const handleQuickRepair = async (values: any) => {
    if (!scannedDevice) {
      message.error('请先扫描设备');
      return;
    }
    
    setLoading(true);
    try {
      const response = await fetch('http://localhost:8000/api/v1/scan/quick-repair', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          device_id: scannedDevice.device.id,
          fault_type: values.fault_type,
          fault_desc: values.fault_description || '设备故障需要检修',
          priority: values.priority
        })
      });
      
      const data = await response.json();
      if (data.success) {
        message.success(`报修成功！工单号：${data.workorder_id}`);
        setRepairModalVisible(false);
        repairForm.resetFields();
        setScannedDevice(null);
        fetchDevices();
      }
    } catch (error) {
      message.error('创建工单失败');
    } finally {
      setLoading(false);
    }
  };

  // 查看报修历史
  const viewRepairHistory = async (deviceId: number) => {
    try {
      const response = await fetch(`http://localhost:8000/api/v1/workorders?device_id=${deviceId}&limit=10`);
      const data = await response.json();
      setRepairHistory(data.items || []);
      setHistoryModalVisible(true);
    } catch (error) {
      message.error('获取历史失败');
    }
  };

  // 设备列表表格列定义
  const deviceColumns: ColumnsType<Device> = [
    {
      title: '设备编码',
      dataIndex: 'code',
      key: 'code',
      width: 150
    },
    {
      title: '设备名称',
      dataIndex: 'name',
      key: 'name',
      width: 150
    },
    {
      title: '设备类型',
      dataIndex: 'type',
      key: 'type',
      width: 100,
      render: (type: string) => {
        const typeMap: Record<string, { color: string; text: string }> = {
          pv_inverter: { color: 'green', text: '逆变器' },
          charger: { color: 'blue', text: '充电桩' },
          battery: { color: 'orange', text: '储能' },
          meter: { color: 'purple', text: '电表' }
        };
        const config = typeMap[type] || { color: 'default', text: type };
        return <Tag color={config.color}>{config.text}</Tag>;
      }
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      render: (status: string) => {
        const statusMap: Record<string, { color: string; text: string }> = {
          online: { color: 'success', text: '在线' },
          offline: { color: 'default', text: '离线' },
          charging: { color: 'processing', text: '充电中' },
          fault: { color: 'error', text: '故障' }
        };
        const config = statusMap[status] || { color: 'default', text: status };
        return <Tag color={config.color}>{config.text}</Tag>;
      }
    },
    {
      title: '站点',
      dataIndex: 'station_name',
      key: 'station_name',
      width: 150
    },
    {
      title: '操作',
      key: 'action',
      width: 200,
      render: (_, record) => (
        <Space size="small">
          <Button 
            size="small" 
            icon={<QrcodeOutlined />}
            onClick={() => generateQrcode(record.id)}
          >
            生成二维码
          </Button>
          <Button 
            size="small" 
            icon={<HistoryOutlined />}
            onClick={() => viewRepairHistory(record.id)}
          >
            历史
          </Button>
        </Space>
      )
    }
  ];

  // 二维码表格列定义
  const qrcodeColumns: ColumnsType<QrCodeData> = [
    {
      title: '二维码',
      dataIndex: 'device_code',
      key: 'device_code',
      width: 200
    },
    {
      title: '设备名称',
      dataIndex: 'device_name',
      key: 'device_name',
      width: 150
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      render: (_, record) => (
        <Space size="small">
          <Button 
            size="small" 
            icon={<DownloadOutlined />}
            onClick={() => {
              const link = document.createElement('a');
              link.href = record.qr_code;
              link.download = `${record.device_code}_qrcode.png`;
              link.click();
            }}
          >
            查看
          </Button>
          <Button 
            size="small" 
            icon={<PrinterOutlined />}
            onClick={() => message.info('请下载二维码后打印')}
          >
            打印
          </Button>
        </Space>
      )
    }
  ];

  return (
    <div style={{ padding: 24 }}>
      <Title level={2}>
        <QrcodeOutlined /> 扫码报修系统
      </Title>
      
      {/* 快速操作区 */}
      <Card style={{ marginBottom: 24 }}>
        <Row gutter={16}>
          <Col span={6}>
            <Statistic 
              title="设备总数" 
              value={devices.length} 
              suffix="台"
            />
          </Col>
          <Col span={6}>
            <Statistic 
              title="故障设备" 
              value={devices.filter(d => d.status === 'fault').length}
              valueStyle={{ color: '#cf1322' }}
            />
          </Col>
          <Col span={6}>
            <Statistic 
              title="已生成二维码" 
              value={qrcodes.length}
            />
          </Col>
          <Col span={6}>
            <Space direction="vertical">
              <Button 
                type="primary" 
                icon={<ScanOutlined />}
                onClick={() => setScanModalVisible(true)}
                block
              >
                扫码报修
              </Button>
              <Button 
                icon={<QrcodeOutlined />}
                onClick={() => setBatchModalVisible(true)}
                block
              >
                批量生成二维码
              </Button>
            </Space>
          </Col>
        </Row>
      </Card>

      {/* 扫码后的设备信息展示 */}
      {scannedDevice && (
        <Card 
          title={
            <Space>
              <WarningOutlined style={{ color: '#faad14' }} />
              <span>已识别设备</span>
            </Space>
          }
          style={{ marginBottom: 24 }}
          extra={
            <Button 
              type="primary" 
              icon={<ToolOutlined />}
              onClick={() => setRepairModalVisible(true)}
            >
              一键报修
            </Button>
          }
        >
          <Descriptions bordered column={2}>
            <Descriptions.Item label="设备编码">{scannedDevice.device.code}</Descriptions.Item>
            <Descriptions.Item label="设备名称">{scannedDevice.device.name}</Descriptions.Item>
            <Descriptions.Item label="设备类型">{scannedDevice.device.type}</Descriptions.Item>
            <Descriptions.Item label="设备状态">
              <Tag color={scannedDevice.device.status === 'fault' ? 'error' : 'success'}>
                {scannedDevice.device.status}
              </Tag>
            </Descriptions.Item>
            <Descriptions.Item label="所属站点">{scannedDevice.device.station_name}</Descriptions.Item>
            <Descriptions.Item label="位置">{scannedDevice.device.location}</Descriptions.Item>
            {scannedDevice.health_score && (
              <Descriptions.Item label="健康度">
                <Tag color={scannedDevice.health_score > 80 ? 'success' : 'warning'}>
                  {scannedDevice.health_score}%
                </Tag>
              </Descriptions.Item>
            )}
          </Descriptions>
          
          {scannedDevice.repair_suggestions && scannedDevice.repair_suggestions.length > 0 && (
            <>
              <Divider>报修建议</Divider>
              <Space direction="vertical">
                {scannedDevice.repair_suggestions.map((suggestion: any, index: number) => (
                  <Tag key={index} color={suggestion.priority === 'high' ? 'red' : 'blue'}>
                    {suggestion.title}
                  </Tag>
                ))}
              </Space>
            </>
          )}
        </Card>
      )}

      {/* 主内容区 - Tabs */}
      <Tabs defaultActiveKey="devices">
        <Tabs.TabPane tab="设备列表" key="devices">
          <Table
            columns={deviceColumns}
            dataSource={devices}
            rowKey="id"
            pagination={{ pageSize: 20 }}
          />
        </Tabs.TabPane>
        
        <Tabs.TabPane tab="二维码列表" key="qrcodes">
          <Table
            columns={qrcodeColumns}
            dataSource={qrcodes}
            rowKey="device_id"
            pagination={{ pageSize: 20 }}
          />
        </Tabs.TabPane>
      </Tabs>

      {/* 扫码弹窗 */}
      <Modal
        title="扫码报修"
        open={scanModalVisible}
        onCancel={() => setScanModalVisible(false)}
        footer={null}
      >
        <Alert
          type="info"
          message="输入二维码进行设备识别"
          description="请输入设备二维码（如：TL-INV001-xxxx）"
          style={{ marginBottom: 16 }}
        />
        
        <Form form={scanForm} onFinish={handleScan}>
          <Form.Item
            name="device_code"
            label="二维码"
            rules={[{ required: true, message: '请输入二维码' }]}
          >
            <Input 
              placeholder="请输入二维码（如 TL-INV001-e3e25639）"
              prefix={<ScanOutlined />}
            />
          </Form.Item>
          
          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                识别设备
              </Button>
              <Button onClick={() => setScanModalVisible(false)}>
                取消
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* 一键报修弹窗 */}
      <Modal
        title="一键报修"
        open={repairModalVisible}
        onCancel={() => setRepairModalVisible(false)}
        footer={null}
      >
        {scannedDevice && (
          <Alert
            type="info"
            message={`设备：${scannedDevice.device.name}`}
            style={{ marginBottom: 16 }}
          />
        )}
        
        <Form 
          form={repairForm}
          onFinish={handleQuickRepair}
          initialValues={{
            fault_type: 'unknown',
            priority: 'medium'
          }}
        >
          <Form.Item
            name="fault_type"
            label="故障类型"
            rules={[{ required: true }]}
          >
            <Select>
              <Select.Option value="unknown">故障（未分类）</Select.Option>
              <Select.Option value="over_temp">过温</Select.Option>
              <Select.Option value="communication">通信故障</Select.Option>
              <Select.Option value="power">电源故障</Select.Option>
              <Select.Option value="mechanical">机械故障</Select.Option>
              <Select.Option value="other">其他故障</Select.Option>
            </Select>
          </Form.Item>
          
          <Form.Item
            name="priority"
            label="优先级"
            rules={[{ required: true }]}
          >
            <Select>
              <Select.Option value="critical">
                <Tag color="error">紧急</Tag>
              </Select.Option>
              <Select.Option value="high">
                <Tag color="warning">高</Tag>
              </Select.Option>
              <Select.Option value="medium">
                <Tag color="processing">中</Tag>
              </Select.Option>
              <Select.Option value="low">
                <Tag color="default">低</Tag>
              </Select.Option>
            </Select>
          </Form.Item>
          
          <Form.Item
            name="fault_description"
            label="故障描述"
          >
            <TextArea 
              rows={4}
              placeholder="请描述故障现象..."
            />
          </Form.Item>
          
          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit" loading={loading}>
                创建工单
              </Button>
              <Button onClick={() => setRepairModalVisible(false)}>
                取消
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* 报修历史弹窗 */}
      <Modal
        title="报修历史"
        open={historyModalVisible}
        onCancel={() => setHistoryModalVisible(false)}
        footer={<Button onClick={() => setHistoryModalVisible(false)}>关闭</Button>}
        width={800}
      >
        <Table
          columns={[
            {
              title: '工单编号',
              dataIndex: 'id',
              key: 'id',
              width: 150
            },
            {
              title: '标题',
              dataIndex: 'title',
              key: 'title'
            },
            {
              title: '优先级',
              dataIndex: 'priority',
              key: 'priority',
              render: (p: string) => <Tag color={p === 'critical' ? 'error' : 'processing'}>{p}</Tag>
            },
            {
              title: '状态',
              dataIndex: 'status',
              key: 'status',
              render: (s: string) => <Tag color={s === 'resolved' ? 'success' : 'warning'}>{s}</Tag>
            },
            {
              title: '创建时间',
              dataIndex: 'created_at',
              key: 'created_at',
              render: (t: string) => new Date(t).toLocaleString()
            }
          ]}
          dataSource={repairHistory}
          rowKey="id"
          pagination={false}
        />
      </Modal>

      {/* 批量生成二维码弹窗 */}
      <Modal
        title="批量生成二维码"
        open={batchModalVisible}
        onCancel={() => setBatchModalVisible(false)}
        footer={null}
      >
        <Alert
          type="info"
          message="按站点批量生成所有设备的二维码"
          style={{ marginBottom: 16 }}
        />
        
        <Form>
          <Form.Item label="选择站点">
            <Select
              placeholder="全部站点"
              allowClear
              onChange={(value) => setSelectedStation(value)}
            >
              {Array.from(new Set(devices.map(d => d.station_id))).map(stationId => {
                const stationName = devices.find(d => d.station_id === stationId)?.station_name;
                return (
                  <Select.Option key={stationId} value={stationId}>
                    {stationName || `站点 ${stationId}`}
                  </Select.Option>
                );
              })}
            </Select>
          </Form.Item>
          
          <Form.Item>
            <Space>
              <Button type="primary" onClick={generateBatchQrcodes} loading={loading}>
                批量生成
              </Button>
              <Button onClick={() => setBatchModalVisible(false)}>
                取消
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default ScanRepairPage;