/**
 * 站点管理页面 - 天链运维平台
 */
import React, { useState, useEffect } from 'react';
import { 
  Card, Table, Button, Space, Input, Tag, Modal, Form, Row, Col, 
  message, Descriptions, Statistic, Progress, Badge 
} from 'antd';
import { 
  PlusOutlined, SearchOutlined, EditOutlined, DeleteOutlined, 
  EnvironmentOutlined, PhoneOutlined, UserOutlined 
} from '@ant-design/icons';
import api from '../../api';

interface Station {
  id: number;
  name: string;
  code: string;
  location: string;
  address?: string;
  capacity?: string;
  operator?: string;
  phone?: string;
  device_count: number;
  online_rate: number;
  status: string;
  created_at: string;
}

const StationsPage: React.FC = () => {
  const [stations, setStations] = useState<Station[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [detailVisible, setDetailVisible] = useState(false);
  const [selectedStation, setSelectedStation] = useState<Station | null>(null);
  const [form] = Form.useForm();
  const [searchText, setSearchText] = useState('');

  useEffect(() => {
    loadStations();
  }, []);

  const loadStations = async () => {
    setLoading(true);
    try {
      const res = await api.get('/api/v1/stations');
      setStations(res.data?.data || []);
    } catch (error) {
      message.error('加载站点失败');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (station: Station) => {
    setSelectedStation(station);
    form.setFieldsValue(station);
    setModalVisible(true);
  };

  const handleDelete = async (id: number) => {
    try {
      await api.delete(`/api/v1/stations/${id}`);
      message.success('站点删除成功');
      loadStations();
    } catch (error) {
      message.error('删除失败');
    }
  };

  const handleViewDetail = async (id: number) => {
    try {
      const res = await api.get(`/api/v1/stations/${id}`);
      setSelectedStation(res.data);
      setDetailVisible(true);
    } catch (error) {
      message.error('加载详情失败');
    }
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      if (selectedStation) {
        await api.put(`/api/v1/stations/${selectedStation.id}`, values);
        message.success('站点更新成功');
      } else {
        await api.post('/api/v1/stations', values);
        message.success('站点创建成功');
      }
      setModalVisible(false);
      loadStations();
    } catch (error) {
      message.error('操作失败');
    }
  };

  const filteredStations = stations.filter(s => 
    s.name.includes(searchText) || s.code.includes(searchText) || s.location.includes(searchText)
  );

  const columns = [
    { title: '站点编码', dataIndex: 'code', key: 'code', width: 120 },
    { title: '站点名称', dataIndex: 'name', key: 'name', width: 150 },
    { title: '位置', dataIndex: 'location', key: 'location', width: 200,
      render: (text: string) => <span><EnvironmentOutlined /> {text}</span> },
    { title: '设备数', dataIndex: 'device_count', key: 'device_count', width: 80,
      render: (count: number) => <Badge count={count} showZero color="blue" /> },
    { title: '在线率', dataIndex: 'online_rate', key: 'online_rate', width: 100,
      render: (rate: number) => (
        <Progress percent={rate} size="small" 
          strokeColor={rate >= 90 ? '#52c41a' : rate >= 70 ? '#faad14' : '#f5222d'} />
      ) },
    { title: '运维员', dataIndex: 'operator', key: 'operator', width: 100,
      render: (text: string) => text ? <span><UserOutlined /> {text}</span> : '-' },
    { title: '状态', dataIndex: 'status', key: 'status', width: 80,
      render: (status: string) => <Tag color={status === 'active' ? 'green' : 'red'}>{status}</Tag> },
    { title: '创建时间', dataIndex: 'created_at', key: 'created_at', width: 120 },
    { title: '操作', key: 'action', width: 150, fixed: 'right' as const,
      render: (record: Station) => (
        <Space size="small">
          <Button type="link" size="small" onClick={() => handleViewDetail(record.id)}>详情</Button>
          <Button type="link" size="small" onClick={() => handleEdit(record)}>编辑</Button>
          <Button type="link" size="small" danger onClick={() => handleDelete(record.id)}>删除</Button>
        </Space>
      ) },
  ];

  return (
    <div style={{ padding: '20px' }}>
      <Card>
        <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
          <Col span={6}>
            <Statistic title="站点总数" value={stations.length} suffix="个" />
          </Col>
          <Col span={6}>
            <Statistic title="活跃站点" value={stations.filter(s => s.status === 'active').length} suffix="个" />
          </Col>
          <Col span={6}>
            <Statistic title="设备总数" value={stations.reduce((sum, s) => sum + s.device_count, 0)} suffix="台" />
          </Col>
          <Col span={6}>
            <Statistic title="平均在线率" 
              value={stations.length > 0 ? stations.reduce((sum, s) => sum + s.online_rate, 0) / stations.length : 0}
              suffix="%" precision={1} />
          </Col>
        </Row>

        <Space style={{ marginBottom: 16 }}>
          <Input.Search placeholder="搜索站点" value={searchText} onChange={e => setSearchText(e.target.value)}
            style={{ width: 200 }} />
          <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>新增站点</Button>
          <Button icon={<SearchOutlined />} onClick={loadStations}>刷新</Button>
        </Space>

        <Table dataSource={filteredStations} columns={columns} rowKey="id" 
          loading={loading} scroll={{ x: 1200 }} pagination={{ pageSize: 10 }} />
      </Card>

      {/* 创建/编辑模态框 */}
      <Modal title={selectedStation ? '编辑站点' : '新增站点'} open={modalVisible} 
        onOk={handleSubmit} onCancel={() => setModalVisible(false)} width={600}>
        <Form form={form} layout="vertical">
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="code" label="站点编码" rules={[{ required: true }]}>
                <Input placeholder="如 SH-PD-01" />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="name" label="站点名称" rules={[{ required: true }]}>
                <Input placeholder="如 浦东示范站" />
              </Form.Item>
            </Col>
          </Row>
          <Form.Item name="location" label="位置" rules={[{ required: true }]}>
            <Input placeholder="如 上海市浦东新区" />
          </Form.Item>
          <Form.Item name="address" label="详细地址">
            <Input placeholder="详细地址" />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="capacity" label="容量">
                <Input placeholder="如 120kW" />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="operator" label="运维员">
                <Input placeholder="运维员姓名" />
              </Form.Item>
            </Col>
          </Row>
          <Form.Item name="phone" label="联系电话">
            <Input placeholder="联系电话" />
          </Form.Item>
        </Form>
      </Modal>

      {/* 详情模态框 */}
      <Modal title="站点详情" open={detailVisible} onCancel={() => setDetailVisible(false)}
        footer={null} width={700}>
        {selectedStation && (
          <Descriptions bordered column={2}>
            <Descriptions.Item label="站点编码">{selectedStation.code}</Descriptions.Item>
            <Descriptions.Item label="站点名称">{selectedStation.name}</Descriptions.Item>
            <Descriptions.Item label="位置">{selectedStation.location}</Descriptions.Item>
            <Descriptions.Item label="详细地址">{selectedStation.address || '-'}</Descriptions.Item>
            <Descriptions.Item label="容量">{selectedStation.capacity || '-'}</Descriptions.Item>
            <Descriptions.Item label="设备数">{selectedStation.device_count} 台</Descriptions.Item>
            <Descriptions.Item label="运维员">{selectedStation.operator || '-'}</Descriptions.Item>
            <Descriptions.Item label="联系电话">{selectedStation.phone || '-'}</Descriptions.Item>
            <Descriptions.Item label="在线率">
              <Progress percent={selectedStation.online_rate} size="small" />
            </Descriptions.Item>
            <Descriptions.Item label="状态">
              <Tag color={selectedStation.status === 'active' ? 'green' : 'red'}>
                {selectedStation.status}
              </Tag>
            </Descriptions.Item>
          </Descriptions>
        )}
      </Modal>
    </div>
  );
};

export default StationsPage;