/**
 * 用户管理页面
 */
import React, { useState, useEffect } from 'react';
import {
  Card,
  Table,
  Button,
  Modal,
  Form,
  Input,
  Space,
  Tag,
  Select,
  Switch,
  message,
  Popconfirm,
  Avatar,
} from 'antd';
import {
  UserOutlined,
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  KeyOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';

interface User {
  id: number;
  username: string;
  email: string;
  role: string;
  station: string;
  status: 'active' | 'inactive';
  lastLogin: string;
  createdAt: string;
}

const ROLES = [
  { value: 'admin', label: '平台管理员', color: 'red' },
  { value: 'station_master', label: '站点站长', color: 'blue' },
  { value: 'maintenance', label: '运维工程师', color: 'green' },
  { value: 'operator', label: '操作员', color: 'default' },
];

const STATIONS = [
  { value: 1, label: '上海浦东站' },
  { value: 2, label: '北京朝阳站' },
  { value: 3, label: '深圳南山站' },
  { value: 4, label: '杭州西湖站' },
];

const UsersPage: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [searchText, setSearchText] = useState('');
  const [form] = Form.useForm();

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      // Mock data - 对接真实 API 后替换
      setUsers([
        { id: 1, username: 'admin', email: 'admin@tianlian.com', role: 'admin', station: '全部', status: 'active', lastLogin: '2026-04-26 17:00', createdAt: '2026-01-01' },
        { id: 2, username: 'zhangsan', email: 'zhangsan@tianlian.com', role: 'station_master', station: '上海浦东站', status: 'active', lastLogin: '2026-04-26 16:30', createdAt: '2026-01-15' },
        { id: 3, username: 'lisi', email: 'lisi@tianlian.com', role: 'maintenance', station: '北京朝阳站', status: 'active', lastLogin: '2026-04-25 14:20', createdAt: '2026-02-20' },
        { id: 4, username: 'wangwu', email: 'wangwu@tianlian.com', role: 'operator', station: '深圳南山站', status: 'inactive', lastLogin: '2026-04-20 09:15', createdAt: '2026-03-10' },
        { id: 5, username: 'zhaoliu', email: 'zhaoliu@tianlian.com', role: 'maintenance', station: '杭州西湖站', status: 'active', lastLogin: '2026-04-26 10:45', createdAt: '2026-03-25' },
      ]);
    } catch (error) {
      message.error('获取用户列表失败');
    } finally {
      setLoading(false);
    }
  };

  const getRoleLabel = (role: string) => {
    return ROLES.find(r => r.value === role)?.label || role;
  };

  const getRoleColor = (role: string) => {
    return ROLES.find(r => r.value === role)?.color || 'default';
  };

  const filteredUsers = users.filter(u =>
    u.username.toLowerCase().includes(searchText.toLowerCase()) ||
    u.email.toLowerCase().includes(searchText.toLowerCase())
  );

  const handleCreate = () => {
    setEditingUser(null);
    form.resetFields();
    form.setFieldsValue({ role: 'operator', status: 'active' });
    setModalVisible(true);
  };

  const handleEdit = (user: User) => {
    setEditingUser(user);
    form.setFieldsValue(user);
    setModalVisible(true);
  };

  const handleDelete = (id: number) => {
    Modal.confirm({
      title: '确认删除用户',
      content: '删除后无法恢复，确定要删除该用户吗？',
      okType: 'danger',
      onOk: () => {
        setUsers(users.filter(u => u.id !== id));
        message.success('删除成功');
      }
    });
  };

  const handleResetPassword = (user: User) => {
    Modal.confirm({
      title: '重置密码',
      content: `确定要重置用户 "${user.username}" 的密码吗？`,
      onOk: () => {
        message.success(`用户 ${user.username} 密码已重置为默认密码`);
      }
    });
  };

  const handleToggleStatus = (user: User) => {
    setUsers(users.map(u =>
      u.id === user.id ? { ...u, status: u.status === 'active' ? 'inactive' : 'active' } : u
    ));
    message.success(`用户 ${user.username} 状态已${user.status === 'active' ? '停用' : '启用'}`);
  };

  const handleSave = async (values: any) => {
    if (editingUser) {
      setUsers(users.map(u => u.id === editingUser.id ? { ...u, ...values } : u));
      message.success('更新成功');
    } else {
      const newUser: User = {
        id: users.length + 1,
        ...values,
        station: STATIONS.find(s => s.value === values.station)?.label || '',
        lastLogin: '-',
        createdAt: new Date().toISOString().split('T')[0]
      };
      setUsers([...users, newUser]);
      message.success('创建成功');
    }
    setModalVisible(false);
  };

  const columns: ColumnsType<User> = [
    {
      title: '用户',
      key: 'user',
      render: (_, record) => (
        <Space>
          <Avatar style={{ backgroundColor: record.status === 'active' ? '#1890ff' : '#d9d9d9' }}>
            <UserOutlined />
          </Avatar>
          <div>
            <div style={{ fontWeight: 500 }}>{record.username}</div>
            <div style={{ fontSize: 12, color: '#888' }}>{record.email}</div>
          </div>
        </Space>
      ),
    },
    {
      title: '角色',
      dataIndex: 'role',
      key: 'role',
      render: (role: string) => (
        <Tag color={getRoleColor(role)}>{getRoleLabel(role)}</Tag>
      ),
    },
    { title: '所属站点', dataIndex: 'station', key: 'station' },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: string, record: User) => (
        <Space>
          <Tag color={status === 'active' ? 'green' : 'red'}>
            {status === 'active' ? '正常' : '停用'}
          </Tag>
          <Switch
            size="small"
            checked={status === 'active'}
            onChange={() => handleToggleStatus(record)}
          />
        </Space>
      ),
    },
    { title: '最后登录', dataIndex: 'lastLogin', key: 'lastLogin' },
    { title: '创建日期', dataIndex: 'createdAt', key: 'createdAt' },
    {
      title: '操作',
      key: 'action',
      fixed: 'right' as const,
      width: 200,
      render: (_, record) => (
        <Space>
          <Button size="small" icon={<EditOutlined />} onClick={() => handleEdit(record)}>
            编辑
          </Button>
          <Button size="small" icon={<KeyOutlined />} onClick={() => handleResetPassword(record)}>
            重置密码
          </Button>
          <Popconfirm
            title="确定删除此用户？"
            onConfirm={() => handleDelete(record.id)}
            okText="确定"
            cancelText="取消"
          >
            <Button size="small" danger icon={<DeleteOutlined />}>删除</Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div style={{ padding: 24 }}>
      <Card
        title={<span><UserOutlined /> 用户管理</span>}
        extra={
          <Space>
            <Input
              placeholder="搜索用户名或邮箱"
              prefix={<SearchOutlined />}
              value={searchText}
              onChange={e => setSearchText(e.target.value)}
              style={{ width: 220 }}
              allowClear
            />
            <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>
              新建用户
            </Button>
          </Space>
        }
      >
        <Table
          columns={columns}
          dataSource={filteredUsers}
          rowKey="id"
          loading={loading}
          scroll={{ x: 1200 }}
          pagination={{ pageSize: 10, showTotal: total => `共 ${total} 个用户` }}
        />
      </Card>

      <Modal
        title={editingUser ? '编辑用户' : '新建用户'}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={() => form.submit()}
        width={520}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={handleSave}
        >
          <Form.Item label="用户名" name="username" rules={[{ required: true, message: '请输入用户名' }]}>
            <Input placeholder="请输入用户名" />
          </Form.Item>
          <Form.Item label="邮箱" name="email" rules={[
            { required: true, message: '请输入邮箱' },
            { type: 'email', message: '请输入有效邮箱' }
          ]}>
            <Input placeholder="请输入邮箱" />
          </Form.Item>
          {!editingUser && (
            <Form.Item label="密码" name="password" rules={[{ required: true, message: '请输入密码' }]}>
              <Input.Password placeholder="请输入密码" />
            </Form.Item>
          )}
          <Form.Item label="角色" name="role" rules={[{ required: true, message: '请选择角色' }]}>
            <Select placeholder="请选择角色">
              {ROLES.map(r => (
                <Select.Option key={r.value} value={r.value}>{r.label}</Select.Option>
              ))}
            </Select>
          </Form.Item>
          <Form.Item label="所属站点" name="station">
            <Select placeholder="请选择站点" allowClear>
              {STATIONS.map(s => (
                <Select.Option key={s.value} value={s.value}>{s.label}</Select.Option>
              ))}
            </Select>
          </Form.Item>
          <Form.Item label="状态" name="status" valuePropName="checked"
            getValueFromEvent={checked => checked ? 'active' : 'inactive'}
            getValueProps={(value: string) => ({ checked: value === 'active' })}
          >
            <Switch checkedChildren="正常" unCheckedChildren="停用" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default UsersPage;
