/**
 * 告警通知设置页面
 */
import React, { useState } from 'react';
import { Card, Table, Button, Switch, Select, Tag, Space, Modal, Form, Input, message, Divider, Row, Col, Checkbox } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, BellOutlined, MailOutlined, MessageOutlined, PhoneOutlined } from '@ant-design/icons';

const { Option } = Select;

const AlarmNoticePage: React.FC = () => {
  const [visible, setVisible] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [form] = Form.useForm();

  const notices = [
    { id: '1', name: '紧急告警通知', level: 'critical', channels: ['sms', 'im-b'], receivers: ['张三', '李四'], enabled: true },
    { id: '2', name: '一般告警通知', level: 'warning', channels: ['im-b'], receivers: ['王五'], enabled: true },
    { id: '3', name: '设备离线通知', level: 'info', channels: ['email'], receivers: ['运维人员'], enabled: false },
    { id: '4', name: '每日汇总报告', level: 'daily', channels: ['email'], receivers: ['管理员'], enabled: true },
  ];

  const handleAdd = () => {
    setEditingItem(null);
    form.resetFields();
    setVisible(true);
  };

  const handleEdit = (record: any) => {
    setEditingItem(record);
    form.setFieldsValue(record);
    setVisible(true);
  };

  const handleDelete = (id: string) => {
    message.success('删除成功');
  };

  const handleToggle = (record: any) => {
    message.success(`${record.enabled ? '禁用' : '启用'}成功`);
  };

  const columns = [
    { title: '规则名称', dataIndex: 'name', key: 'name' },
    { 
      title: '告警级别', 
      dataIndex: 'level', 
      key: 'level',
      render: (level: string) => {
        const map: Record<string, { color: string; text: string }> = {
          critical: { color: 'red', text: '紧急' },
          warning: { color: 'orange', text: '警告' },
          info: { color: 'blue', text: '提示' },
          daily: { color: 'purple', text: '日报' },
        };
        return <Tag color={map[level]?.color}>{map[level]?.text || level}</Tag>;
      }
    },
    { 
      title: '通知渠道', 
      dataIndex: 'channels', 
      key: 'channels',
      render: (channels: string[]) => (
        <Space>
          {channels.includes('sms') && <Tag icon={<PhoneOutlined />}>短信</Tag>}
          {channels.includes('im-b') && <Tag icon={<MessageOutlined />}>IM-B</Tag>}
          {channels.includes('email') && <Tag icon={<MailOutlined />}>邮件</Tag>}
        </Space>
      )
    },
    { title: '接收人', dataIndex: 'receivers', key: 'receivers', render: (r: string[]) => r.join(', ') },
    { 
      title: '状态', 
      dataIndex: 'enabled', 
      key: 'enabled',
      render: (enabled: boolean, record: any) => (
        <Switch 
          checked={enabled} 
          onChange={() => handleToggle(record)}
          checkedChildren="启用"
          unCheckedChildren="禁用"
        />
      )
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: any) => (
        <Space>
          <Button type="text" icon={<EditOutlined />} onClick={() => handleEdit(record)} />
          <Button type="text" danger icon={<DeleteOutlined />} onClick={() => handleDelete(record.id)} />
        </Space>
      ),
    },
  ];

  return (
    <div>
      <Card>
        <div style={{ marginBottom: 16 }}>
          <Space>
            <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd}>
              添加规则
            </Button>
          </Space>
        </div>

        <Table
          columns={columns}
          dataSource={notices}
          rowKey="id"
          pagination={false}
        />
      </Card>

      <Row gutter={16} style={{ marginTop: 16 }}>
        <Col span={12}>
          <Card title="通知渠道配置">
            <Form layout="vertical">
              <Form.Item label="短信通知">
                <Switch checkedChildren="开启" unCheckedChildren="关闭" defaultChecked />
              </Form.Item>
              <Form.Item label="企业IM-B">
                <Switch checkedChildren="开启" unCheckedChildren="关闭" defaultChecked />
              </Form.Item>
              <Form.Item label="邮件通知">
                <Switch checkedChildren="开启" unCheckedChildren="关闭" defaultChecked />
              </Form.Item>
              <Form.Item label="电话通知">
                <Switch checkedChildren="开启" unCheckedChildren="关闭" />
              </Form.Item>
              <Button type="primary">保存配置</Button>
            </Form>
          </Card>
        </Col>
        <Col span={12}>
          <Card title="测试通知">
            <Form layout="vertical">
              <Form.Item label="测试类型">
                <Select defaultValue="im-b">
                  <Option value="sms">短信</Option>
                  <Option value="im-b">IM-B</Option>
                  <Option value="email">邮件</Option>
                </Select>
              </Form.Item>
              <Form.Item label="接收手机/邮箱">
                <Input placeholder="请输入测试接收者" />
              </Form.Item>
              <Button type="primary" danger>发送测试</Button>
            </Form>
          </Card>
        </Col>
      </Row>

      <Modal
        title={editingItem ? '编辑规则' : '添加规则'}
        open={visible}
        onCancel={() => setVisible(false)}
        onOk={() => {
          form.validateFields().then(() => {
            message.success(editingItem ? '编辑成功' : '添加成功');
            setVisible(false);
          });
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="name" label="规则名称" rules={[{ required: true }]}>
            <Input placeholder="请输入规则名称" />
          </Form.Item>
          <Form.Item name="level" label="告警级别" rules={[{ required: true }]}>
            <Select>
              <Option value="critical">紧急</Option>
              <Option value="warning">警告</Option>
              <Option value="info">提示</Option>
              <Option value="daily">日报</Option>
            </Select>
          </Form.Item>
          <Form.Item name="channels" label="通知渠道" rules={[{ required: true }]}>
            <Checkbox.Group>
              <Checkbox value="sms">短信</Checkbox>
              <Checkbox value="im-b">IM-B</Checkbox>
              <Checkbox value="email">邮件</Checkbox>
            </Checkbox.Group>
          </Form.Item>
          <Form.Item name="receivers" label="接收人">
            <Select mode="tags" placeholder="输入接收人">
              <Option value="张三">张三</Option>
              <Option value="李四">李四</Option>
              <Option value="王五">王五</Option>
            </Select>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default AlarmNoticePage;