/**
 * 运维仪表盘 - 天链运维平台
 * 聚焦设备健康、告警、工单，无经营数据
 */
import React, { useEffect, useState } from 'react';
import ReactECharts from 'echarts-for-react';
import { Card, Row, Col, Statistic, Alert, List, Tag, Spin, Button } from 'antd';
import { 
  WarningOutlined, CheckCircleOutlined, ToolOutlined, 
  ThunderboltOutlined, ClockCircleOutlined, DashboardOutlined,
  MedicineBoxOutlined, CameraOutlined
} from '@ant-design/icons';
import api from '../../api';

interface DashboardStats {
  totalDevices: number;
  onlineDevices: number;
  healthyDevices: number;
  warningDevices: number;
  faultDevices: number;
  avgHealthScore: number;
  pendingAlarms: number;
  criticalAlarms: number;
  pendingWorkOrders: number;
  todayWorkOrders: number;
}

interface AlarmItem {
  id: number;
  title: string;
  level: string;
  device_name: string;
  created_at: string;
}

interface WorkOrderItem {
  id: number;
  title: string;
  priority: string;
  device_name: string;
  status: string;
}

const Dashboard: React.FC = () => {
  const [stats, setStats] = useState<DashboardStats>({
    totalDevices: 0,
    onlineDevices: 0,
    healthyDevices: 0,
    warningDevices: 0,
    faultDevices: 0,
    avgHealthScore: 0,
    pendingAlarms: 0,
    criticalAlarms: 0,
    pendingWorkOrders: 0,
    todayWorkOrders: 0,
  });
  const [alarms, setAlarms] = useState<AlarmItem[]>([]);
  const [workOrders, setWorkOrders] = useState<WorkOrderItem[]>([]);
  const [healthDistribution, setHealthDistribution] = useState({ A: 0, B: 0, C: 0, D: 0, E: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadDashboardData();
    // 每30秒刷新一次
    const interval = setInterval(loadDashboardData, 30000);
    return () => clearInterval(interval);
  }, []);

  const loadDashboardData = async () => {
    try {
      // 获取诊断统计（健康度数据）
      const diagnosisRes = await api.get('/api/v1/diagnosis/batch', { 
        method: 'POST',
        data: {} 
      });
      
      // 获取告警列表
      const alarmsRes = await api.get('/api/v1/alarms?status=pending&limit=5');
      
      // 获取工单列表
      const workOrdersRes = await api.get('/api/v1/workorders?status=pending&limit=5');
      
      // 获取设备列表
      const devicesRes = await api.get('/api/v1/devices?limit=100');

      // 计算统计数据
      const devices = devicesRes.data?.data || devicesRes.data?.devices || [];
      const diagnosisData = diagnosisRes.data || {};
      
      const newStats: DashboardStats = {
        totalDevices: devices.length || diagnosisData.total_devices || 0,
        onlineDevices: devices.filter((d: any) => d.status === 'online' || d.status === 'charging').length,
        healthyDevices: diagnosisData.healthy_devices || 0,
        warningDevices: diagnosisData.warning_devices || 0,
        faultDevices: diagnosisData.fault_devices || 0,
        avgHealthScore: diagnosisData.avg_health_score || 0,
        pendingAlarms: alarmsRes.data?.total || 0,
        criticalAlarms: alarmsRes.data?.data?.filter((a: any) => a.level === 'critical').length || 0,
        pendingWorkOrders: workOrdersRes.data?.total || 0,
        todayWorkOrders: workOrdersRes.data?.data?.filter((w: any) => 
          new Date(w.created_at).toDateString() === new Date().toDateString()
        ).length || 0,
      };

      setStats(newStats);
      setAlarms(alarmsRes.data?.data || alarmsRes.data?.alarms || []);
      setWorkOrders(workOrdersRes.data?.data || workOrdersRes.data?.workorders || []);

      // 健康度分布
      const healthGrades = { A: 0, B: 0, C: 0, D: 0, E: 0 };
      (diagnosisData.devices || []).forEach((d: any) => {
        if (d.health_grade) {
          healthGrades[d.health_grade as keyof typeof healthGrades]++;
        }
      });
      setHealthDistribution(healthGrades);

      setLoading(false);
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
      // 使用模拟数据
      setStats({
        totalDevices: 9,
        onlineDevices: 7,
        healthyDevices: 5,
        warningDevices: 4,
        faultDevices: 0,
        avgHealthScore: 88.6,
        pendingAlarms: 3,
        criticalAlarms: 1,
        pendingWorkOrders: 5,
        todayWorkOrders: 2,
      });
      setLoading(false);
    }
  };

  // 健康度分布图
  const healthDistributionOption = {
    title: { text: '设备健康度分布', left: 'center' },
    tooltip: { trigger: 'item', formatter: '{b}: {c}台 ({d}%)' },
    legend: { orient: 'vertical', left: 'left' },
    series: [{
      type: 'pie',
      radius: '50%',
      data: [
        { value: healthDistribution.A, name: 'A级(优秀)', itemStyle: { color: '#52c41a' } },
        { value: healthDistribution.B, name: 'B级(良好)', itemStyle: { color: '#73d13d' } },
        { value: healthDistribution.C, name: 'C级(一般)', itemStyle: { color: '#faad14' } },
        { value: healthDistribution.D, name: 'D级(较差)', itemStyle: { color: '#fa8c16' } },
        { value: healthDistribution.E, name: 'E级(危险)', itemStyle: { color: '#f5222d' } },
      ],
      emphasis: {
        itemStyle: {
          shadowBlur: 10,
          shadowOffsetX: 0,
          shadowColor: 'rgba(0, 0, 0, 0.5)'
        }
      }
    }]
  };

  // 设备状态分布
  const deviceStatusOption = {
    title: { text: '设备状态分布', left: 'center' },
    tooltip: { trigger: 'axis' },
    xAxis: { type: 'category', data: ['在线', '充电', '故障', '离线', '维护'] },
    yAxis: { type: 'value', name: '设备数' },
    series: [{
      data: [
        stats.onlineDevices,
        Math.floor(stats.totalDevices * 0.3),
        stats.faultDevices,
        stats.totalDevices - stats.onlineDevices - stats.faultDevices,
        0,
      ],
      type: 'bar',
      itemStyle: {
        color: (params: any) => {
          const colors = ['#52c41a', '#1890ff', '#f5222d', '#8c8c8c', '#faad14'];
          return colors[params.dataIndex];
        }
      }
    }]
  };

  // 告警级别分布
  const alarmDistributionOption = {
    title: { text: '告警级别分布', left: 'center' },
    tooltip: { trigger: 'axis' },
    xAxis: { type: 'category', data: ['严重', '高', '中', '低'] },
    yAxis: { type: 'value', name: '告警数' },
    series: [{
      data: [stats.criticalAlarms, Math.floor(stats.pendingAlarms * 0.3), Math.floor(stats.pendingAlarms * 0.4), Math.floor(stats.pendingAlarms * 0.2)],
      type: 'bar',
      itemStyle: {
        color: (params: any) => {
          const colors = ['#f5222d', '#fa8c16', '#faad14', '#52c41a'];
          return colors[params.dataIndex];
        }
      }
    }]
  };

  const getAlarmTagColor = (level: string) => {
    switch (level) {
      case 'critical': return 'red';
      case 'high': return 'orange';
      case 'medium': return 'yellow';
      case 'low': return 'green';
      default: return 'default';
    }
  };

  const getWorkOrderTagColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'red';
      case 'medium': return 'orange';
      case 'low': return 'green';
      default: return 'default';
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '50px' }}><Spin size="large" /></div>;
  }

  return (
    <div style={{ padding: '20px' }}>
      {/* 紧急提示 */}
      {stats.criticalAlarms > 0 && (
        <Alert
          message={`有 ${stats.criticalAlarms} 条严重告警需要立即处理！`}
          type="error"
          showIcon
          style={{ marginBottom: '20px' }}
          action={
            <Button size="small" type="primary" danger onClick={() => window.location.href = '/alarms'}>
              立即查看
            </Button>
          }
        />
      )}

      {/* 核心指标 */}
      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="设备总数"
              value={stats.totalDevices}
              suffix="台"
              prefix={<ThunderboltOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="在线设备"
              value={stats.onlineDevices}
              suffix="台"
              prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />}
              valueStyle={{ color: '#52c41a' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="平均健康度"
              value={stats.avgHealthScore}
              suffix="分"
              prefix={<MedicineBoxOutlined />}
              valueStyle={{ color: stats.avgHealthScore >= 80 ? '#52c41a' : '#faad14' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="待处理告警"
              value={stats.pendingAlarms}
              suffix="条"
              prefix={<WarningOutlined style={{ color: stats.pendingAlarms > 0 ? '#f5222d' : '#52c41a' }} />}
              valueStyle={{ color: stats.pendingAlarms > 0 ? '#f5222d' : '#52c41a' }}
            />
          </Card>
        </Col>
      </Row>

      {/* 第二行指标 */}
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="健康设备"
              value={stats.healthyDevices}
              suffix="台"
              prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="亚健康设备"
              value={stats.warningDevices}
              suffix="台"
              prefix={<ClockCircleOutlined style={{ color: '#faad14' }} />}
              valueStyle={{ color: '#faad14' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="故障设备"
              value={stats.faultDevices}
              suffix="台"
              prefix={<WarningOutlined style={{ color: '#f5222d' }} />}
              valueStyle={{ color: '#f5222d' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="待处理工单"
              value={stats.pendingWorkOrders}
              suffix="个"
              prefix={<ToolOutlined />}
              valueStyle={{ color: stats.pendingWorkOrders > 5 ? '#faad14' : '#52c41a' }}
            />
          </Card>
        </Col>
      </Row>

      {/* 快速入口 */}
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col xs={24} sm={12}>
          <Card 
            hoverable
            onClick={() => window.location.href = '/diagnosis'}
            style={{ textAlign: 'center', padding: '20px' }}
          >
            <MedicineBoxOutlined style={{ fontSize: '40px', color: '#1890ff' }} />
            <h3 style={{ marginTop: '10px' }}>智能诊断</h3>
            <p>设备健康度评估与故障预测</p>
          </Card>
        </Col>
        <Col xs={24} sm={12}>
          <Card 
            hoverable
            onClick={() => window.location.href = '/scan'}
            style={{ textAlign: 'center', padding: '20px' }}
          >
            <CameraOutlined style={{ fontSize: '40px', color: '#1890ff' }} />
            <h3 style={{ marginTop: '10px' }}>扫码报修</h3>
            <p>快速扫码识别设备并报修</p>
          </Card>
        </Col>
      </Row>

      {/* 图表区 */}
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col xs={24} lg={8}>
          <Card>
            <ReactECharts option={healthDistributionOption} style={{ height: 300 }} />
          </Card>
        </Col>
        <Col xs={24} lg={8}>
          <Card>
            <ReactECharts option={deviceStatusOption} style={{ height: 300 }} />
          </Card>
        </Col>
        <Col xs={24} lg={8}>
          <Card>
            <ReactECharts option={alarmDistributionOption} style={{ height: 300 }} />
          </Card>
        </Col>
      </Row>

      {/* 告警和工单列表 */}
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col xs={24} lg={12}>
          <Card title="待处理告警" extra={<a href="/alarms">查看全部</a>}>
            <List
              dataSource={alarms}
              renderItem={(item) => (
                <List.Item>
                  <List.Item.Meta
                    title={<span><Tag color={getAlarmTagColor(item.level)}>{item.level}</Tag> {item.title}</span>}
                    description={`${item.device_name} - ${new Date(item.created_at).toLocaleString()}`}
                  />
                </List.Item>
              )}
              locale={{ emptyText: '暂无待处理告警' }}
            />
          </Card>
        </Col>
        <Col xs={24} lg={12}>
          <Card title="待处理工单" extra={<a href="/workorders">查看全部</a>}>
            <List
              dataSource={workOrders}
              renderItem={(item) => (
                <List.Item>
                  <List.Item.Meta
                    title={<span><Tag color={getWorkOrderTagColor(item.priority)}>{item.priority}</Tag> {item.title}</span>}
                    description={`${item.device_name || '未知设备'} - 状态: ${item.status}`}
                  />
                </List.Item>
              )}
              locale={{ emptyText: '暂无待处理工单' }}
            />
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Dashboard;