/**
 * 告警概览页面
 */
import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Table, Tag, Button, Select, Space, Statistic, Progress, Modal, Form, Input, DatePicker } from 'antd';
import { 
  AlertOutlined, WarningOutlined, 
  ExclamationCircleOutlined, CheckCircleOutlined, SyncOutlined, FilterOutlined, InfoCircleOutlined 
} from '@ant-design/icons';
import { alarmAPI } from '../../api';

const { RangePicker } = DatePicker;
const { TextArea } = Input;

const AlarmListPage: React.FC = () => {
  const [status, setStatus] = useState('all');
  const [level, setLevel] = useState('all');
  const [handleModalVisible, setHandleModalVisible] = useState(false);
  const [selectedAlarm, setSelectedAlarm] = useState<any>(null);
  const [alarms, setAlarms] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, critical: 0, warning: 0, handled: 0 });

  // 获取告警数据
  useEffect(() => {
    const fetchAlarms = async () => {
      setLoading(true);
      try {
        const params: any = {};
        if (status !== 'all') params.status = status;
        if (level !== 'all') params.level = level;
        
        const res: any = await alarmAPI.list(params);
        const alarmList = res.alarms || [];
        
        setAlarms(alarmList.map((a: any) => ({
          ...a,
          id: String(a.id),
          device: a.device_name || `设备 ${a.device_id}`,
          station: `站点 ${a.station_id}`,
          time: a.created_at || new Date().toISOString(),
        })));
        
        // 统计
        setStats({
          total: res.total || alarmList.length,
          critical: alarmList.filter((a: any) => a.level === 'critical').length,
          warning: alarmList.filter((a: any) => a.level === 'warning').length,
          handled: alarmList.filter((a: any) => a.status === 'resolved').length,
        });
      } catch (error) {
        console.error('获取告警失败:', error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchAlarms();
  }, [status, level]);

  const getLevelTag = (lvl: string) => {
    const tags: Record<string, { color: string; text: string }> = {
      critical: { color: 'red', text: '紧急' },
      warning: { color: 'orange', text: '警告' },
      info: { color: 'blue', text: '提示' },
    };
    return tags[lvl] || { color: 'default', text: lvl };
  };

  const getStatusTag = (st: string) => {
    const tags: Record<string, { color: string; text: string }> = {
      pending: { color: 'red', text: '待处理' },
      handling: { color: 'orange', text: '处理中' },
      resolved: { color: 'green', text: '已解决' },
    };
    return tags[st] || { color: 'default', text: st };
  };

  const handleAlarm = (record: any) => {
    setSelectedAlarm(record);
    setHandleModalVisible(true);
  };

  const columns = [
    { 
      title: '级别', 
      dataIndex: 'level', 
      key: 'level',
      width: 100,
      render: (lvl: string) => {
        const tag = getLevelTag(lvl);
        return (
          <Space>
            {lvl === 'critical' && <ExclamationCircleOutlined style={{ color: '#ff4d4f' }} />}
            {lvl === 'warning' && <WarningOutlined style={{ color: '#faad14' }} />}
            {lvl === 'info' && <InfoCircleOutlined style={{ color: '#1890ff' }} />}
            <Tag color={tag.color}>{tag.text}</Tag>
          </Space>
        );
      }
    },
    { title: '设备', dataIndex: 'device', key: 'device' },
    { title: '告警类型', dataIndex: 'type', key: 'type' },
    { title: '站点', dataIndex: 'station', key: 'station' },
    { title: '时间', dataIndex: 'time', key: 'time', width: 180 },
    { title: '描述', dataIndex: 'desc', key: 'desc', ellipsis: true },
    { 
      title: '状态', 
      dataIndex: 'status', 
      key: 'status',
      render: (st: string) => {
        const tag = getStatusTag(st);
        return <Tag color={tag.color}>{tag.text}</Tag>;
      }
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: any) => (
        <Space>
          <Button size="small" type="link" onClick={() => handleAlarm(record)}>
            {record.status === 'resolved' ? '查看' : '处理'}
          </Button>
          <Button size="small" icon={<SyncOutlined />}>
            详情
          </Button>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="告警总数" value={stats.total} prefix={<AlertOutlined />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="紧急告警" value={stats.critical} prefix={<ExclamationCircleOutlined style={{ color: '#ff4d4f' }} />} valueStyle={{ color: '#ff4d4f' }} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="警告告警" value={stats.warning} prefix={<WarningOutlined style={{ color: '#faad14' }} />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="已处理" value={stats.handled} prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />} />
            <Progress percent={Math.round((stats.handled / stats.total) * 100)} showInfo={false} strokeColor="#52c41a" />
          </Card>
        </Col>
      </Row>

      <Card>
        <div style={{ marginBottom: 16 }}>
          <Space>
            <Select value={status} onChange={setStatus} style={{ width: 120 }}>
              <Select.Option value="all">全部状态</Select.Option>
              <Select.Option value="pending">待处理</Select.Option>
              <Select.Option value="handling">处理中</Select.Option>
              <Select.Option value="resolved">已解决</Select.Option>
            </Select>
            <Select value={level} onChange={setLevel} style={{ width: 120 }}>
              <Select.Option value="all">全部级别</Select.Option>
              <Select.Option value="critical">紧急</Select.Option>
              <Select.Option value="warning">警告</Select.Option>
              <Select.Option value="info">提示</Select.Option>
            </Select>
            <RangePicker />
            <Button icon={<FilterOutlined />}>筛选</Button>
            <Button icon={<SyncOutlined />}>刷新</Button>
          </Space>
        </div>

        <Table
          columns={columns}
          dataSource={alarms}
          rowKey="id"
          pagination={{ total: alarms.length, pageSize: 10 }}
        />
      </Card>

      <Modal
        title="处理告警"
        open={handleModalVisible}
        onCancel={() => setHandleModalVisible(false)}
        footer={[
          <Button key="submit" type="primary" onClick={() => setHandleModalVisible(false)}>确认处理</Button>,
          <Button key="back" onClick={() => setHandleModalVisible(false)}>取消</Button>,
        ]}
      >
        {selectedAlarm && (
          <Form layout="vertical">
            <Form.Item label="设备">
              <Input value={selectedAlarm.device} disabled />
            </Form.Item>
            <Form.Item label="告警类型">
              <Input value={selectedAlarm.type} disabled />
            </Form.Item>
            <Form.Item label="处理状态">
              <Select defaultValue="resolved">
                <Select.Option value="resolved">已解决</Select.Option>
                <Select.Option value="pending">无法处理</Select.Option>
              </Select>
            </Form.Item>
            <Form.Item label="处理备注">
              <TextArea rows={4} placeholder="请输入处理说明..." />
            </Form.Item>
          </Form>
        )}
      </Modal>
    </div>
  );
};

export default AlarmListPage;