/**
 * 网关SN码管理页面 - 天链运维平台
 */
import React, { useState, useEffect } from 'react';
import { 
  Card, Table, Button, Space, Input, Tag, Modal, Form, Row, Col, 
  message, Statistic, Progress, Select, Tabs, Badge, Descriptions 
} from 'antd';
import { 
  PlusOutlined, SearchOutlined, LockOutlined, UnlockOutlined,
  CheckCircleOutlined, StopOutlined, RollbackOutlined,
  BarcodeOutlined, DownloadOutlined, UploadOutlined 
} from '@ant-design/icons';
import api from '../../api';

interface GatewaySN {
  id: number;
  sn: string;
  batch: string;
  status: string;
  device_id?: number;
  device_name?: string;
  generated_at: string;
  assigned_at?: string;
  activated_at?: string;
  notes?: string;
}

const GatewaySNPage: React.FC = () => {
  const [snList, setSNList] = useState<GatewaySN[]>([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<any>({});
  const [modalVisible, setModalVisible] = useState(false);
  const [assignModalVisible, setAssignModalVisible] = useState(false);
  const [selectedSN, setSelectedSN] = useState<GatewaySN | null>(null);
  const [form] = Form.useForm();
  const [assignForm] = Form.useForm();
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [searchText, setSearchText] = useState('');

  useEffect(() => {
    loadSNList();
    loadStats();
  }, [statusFilter]);

  const loadSNList = async () => {
    setLoading(true);
    try {
      const params: any = { limit: 50 };
      if (statusFilter !== 'all') params.status = statusFilter;
      const res = await api.get('/api/v1/gateway-sn', { params });
      setSNList(res.data?.data || []);
    } catch (error) {
      message.error('加载SN码失败');
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const res = await api.get('/api/v1/gateway-sn/stats');
      setStats(res.data || {});
    } catch (error) {
      console.error('加载统计失败');
    }
  };

  const handleGenerate = () => {
    form.resetFields();
    setModalVisible(true);
  };

  const handleAssign = (sn: GatewaySN) => {
    setSelectedSN(sn);
    assignForm.resetFields();
    setAssignModalVisible(true);
  };

  const handleActivate = async (sn: GatewaySN) => {
    try {
      await api.post(`/api/v1/gateway-sn/${sn.id}/activate`);
      message.success('SN码激活成功');
      loadSNList();
      loadStats();
    } catch (error) {
      message.error('激活失败');
    }
  };

  const handleLock = async (sn: GatewaySN) => {
    try {
      await api.post(`/api/v1/gateway-sn/${sn.id}/lock`, { reason: '安全锁定' });
      message.success('SN码锁定成功');
      loadSNList();
      loadStats();
    } catch (error) {
      message.error('锁定失败');
    }
  };

  const handleRecall = async (sn: GatewaySN) => {
    try {
      await api.post(`/api/v1/gateway-sn/${sn.id}/recall`, { reason: '设备召回' });
      message.success('SN码召回成功');
      loadSNList();
      loadStats();
    } catch (error) {
      message.error('召回失败');
    }
  };

  const handleGenerateSubmit = async () => {
    try {
      const values = await form.validateFields();
      const res = await api.post('/api/v1/gateway-sn/generate', values);
      message.success(`成功生成 ${res.data?.count} 个SN码`);
      setModalVisible(false);
      loadSNList();
      loadStats();
    } catch (error) {
      message.error('生成失败');
    }
  };

  const handleAssignSubmit = async () => {
    try {
      const values = await assignForm.validateFields();
      await api.post(`/api/v1/gateway-sn/${selectedSN?.id}/assign`, values);
      message.success('SN码分配成功');
      setAssignModalVisible(false);
      loadSNList();
      loadStats();
    } catch (error) {
      message.error('分配失败');
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'available': return 'green';
      case 'assigned': return 'blue';
      case 'activated': return 'purple';
      case 'locked': return 'red';
      case 'recalled': return 'orange';
      default: return 'default';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'available': return '可用';
      case 'assigned': return '已分配';
      case 'activated': return '已激活';
      case 'locked': return '已锁定';
      case 'recalled': return '已召回';
      default: return status;
    }
  };

  const filteredList = snList.filter(sn => 
    sn.sn.includes(searchText) || sn.batch.includes(searchText) || sn.device_name?.includes(searchText)
  );

  const columns = [
    { title: 'ID', dataIndex: 'id', key: 'id', width: 60 },
    { title: 'SN码', dataIndex: 'sn', key: 'sn', width: 150,
      render: (text: string) => <span><BarcodeOutlined /> {text}</span> },
    { title: '批次', dataIndex: 'batch', key: 'batch', width: 120 },
    { title: '状态', dataIndex: 'status', key: 'status', width: 80,
      render: (status: string) => <Tag color={getStatusColor(status)}>{getStatusText(status)}</Tag> },
    { title: '关联设备', dataIndex: 'device_name', key: 'device_name', width: 150,
      render: (text: string) => text || '-' },
    { title: '生成时间', dataIndex: 'generated_at', key: 'generated_at', width: 120 },
    { title: '分配时间', dataIndex: 'assigned_at', key: 'assigned_at', width: 120,
      render: (text: string) => text || '-' },
    { title: '激活时间', dataIndex: 'activated_at', key: 'activated_at', width: 120,
      render: (text: string) => text || '-' },
    { title: '操作', key: 'action', width: 180, fixed: 'right' as const,
      render: (record: GatewaySN) => (
        <Space size="small">
          {record.status === 'available' && (
            <Button type="link" size="small" icon={<CheckCircleOutlined />}
              onClick={() => handleAssign(record)}>分配</Button>
          )}
          {record.status === 'assigned' && (
            <Button type="link" size="small" style={{ color: '#722ed1' }}
              onClick={() => handleActivate(record)}>激活</Button>
          )}
          {record.status !== 'locked' && record.status !== 'recalled' && (
            <Button type="link" size="small" danger icon={<LockOutlined />}
              onClick={() => handleLock(record)}>锁定</Button>
          )}
          {record.status === 'locked' && (
            <Button type="link" size="small" icon={<RollbackOutlined />}
              onClick={() => handleRecall(record)}>召回</Button>
          )}
        </Space>
      ) },
  ];

  return (
    <div style={{ padding: '20px' }}>
      <Card>
        <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
          <Col span={4}>
            <Statistic title="SN码总数" value={stats.total || 0} suffix="个" prefix={<BarcodeOutlined />} />
          </Col>
          <Col span={4}>
            <Statistic title="可用" value={stats.available || 0} suffix="个" valueStyle={{ color: '#52c41a' }} />
          </Col>
          <Col span={4}>
            <Statistic title="已分配" value={stats.assigned || 0} suffix="个" valueStyle={{ color: '#1890ff' }} />
          </Col>
          <Col span={4}>
            <Statistic title="已激活" value={stats.activated || 0} suffix="个" valueStyle={{ color: '#722ed1' }} />
          </Col>
          <Col span={4}>
            <Statistic title="已锁定" value={stats.locked || 0} suffix="个" valueStyle={{ color: '#f5222d' }} />
          </Col>
          <Col span={4}>
            <Statistic title="已召回" value={stats.recalled || 0} suffix="个" valueStyle={{ color: '#faad14' }} />
          </Col>
        </Row>

        <Space style={{ marginBottom: 16 }}>
          <Input.Search placeholder="搜索SN码" value={searchText} onChange={e => setSearchText(e.target.value)}
            style={{ width: 200 }} allowClear />
          <Select value={statusFilter} onChange={setStatusFilter} style={{ width: 120 }}>
            <Select.Option value="all">全部状态</Select.Option>
            <Select.Option value="available">可用</Select.Option>
            <Select.Option value="assigned">已分配</Select.Option>
            <Select.Option value="activated">已激活</Select.Option>
            <Select.Option value="locked">已锁定</Select.Option>
            <Select.Option value="recalled">已召回</Select.Option>
          </Select>
          <Button type="primary" icon={<PlusOutlined />} onClick={handleGenerate}>批量生成</Button>
          <Button icon={<SearchOutlined />} onClick={loadSNList}>刷新</Button>
        </Space>

        <Table dataSource={filteredList} columns={columns} rowKey="id" 
          loading={loading} scroll={{ x: 1300 }} pagination={{ pageSize: 15 }} />
      </Card>

      {/* 生成SN码模态框 */}
      <Modal title="批量生成SN码" open={modalVisible} onOk={handleGenerateSubmit} onCancel={() => setModalVisible(false)}>
        <Form form={form} layout="vertical">
          <Form.Item name="count" label="生成数量" rules={[{ required: true }]}>
            <Input type="number" placeholder="如 10" min={1} max={1000} />
          </Form.Item>
          <Form.Item name="batch" label="批次号" rules={[{ required: true }]}>
            <Input placeholder="如 BATCH-2026-001" />
          </Form.Item>
        </Form>
      </Modal>

      {/* 分配SN码模态框 */}
      <Modal title="分配SN码给设备" open={assignModalVisible} onOk={handleAssignSubmit} onCancel={() => setAssignModalVisible(false)}>
        {selectedSN && (
          <Descriptions bordered column={1} style={{ marginBottom: 16 }}>
            <Descriptions.Item label="SN码">{selectedSN.sn}</Descriptions.Item>
            <Descriptions.Item label="批次">{selectedSN.batch}</Descriptions.Item>
          </Descriptions>
        )}
        <Form form={assignForm} layout="vertical">
          <Form.Item name="device_id" label="设备ID" rules={[{ required: true }]}>
            <Input type="number" placeholder="设备ID" />
          </Form.Item>
          <Form.Item name="device_name" label="设备名称">
            <Input placeholder="设备名称" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default GatewaySNPage;