/**
 * 设备管理页面
 */
import React, { useState, useEffect } from 'react';
import { 
  Card, Table, Button, Space, Input, Select, Tag, Modal, 
  Form, Row, Col, message, Popconfirm, Badge, Avatar, Tooltip 
} from 'antd';
import { 
  PlusOutlined, SearchOutlined, EditOutlined, DeleteOutlined, 
  ReloadOutlined, ExportOutlined, DesktopOutlined, FilterOutlined 
} from '@ant-design/icons';
import { deviceAPI } from '../../api';

const { Option } = Select;

interface Device {
  id: string;
  name: string;
  type: string;
  station: string;
  status: 'online' | 'offline' | 'fault';
  power?: number;
  voltage?: number;
  current?: number;
  temperature?: number;
  lastUpdate: string;
}

// 模拟数据
const mockDevices: Device[] = [
  { id: '1', name: '光伏逆变器-01', type: 'inverter', station: '浦东站', status: 'online', power: 125, voltage: 380, current: 32.5, temperature: 45, lastUpdate: '2026-03-27 10:30:00' },
  { id: '2', name: '光伏逆变器-02', type: 'inverter', station: '浦东站', status: 'online', power: 118, voltage: 375, current: 31.2, temperature: 43, lastUpdate: '2026-03-27 10:30:00' },
  { id: '3', name: '储能电池-01', type: 'battery', station: '浦东站', status: 'online', power: -50, voltage: 400, current: -12.5, temperature: 28, lastUpdate: '2026-03-27 10:30:00' },
  { id: '4', name: '储能电池-02', type: 'battery', station: '浦西站', status: 'offline', power: 0, voltage: 0, current: 0, temperature: 25, lastUpdate: '2026-03-27 09:15:00' },
  { id: '5', name: '充电桩-001', type: 'charger', station: '浦东站', status: 'online', power: 60, voltage: 220, current: 27.3, temperature: 38, lastUpdate: '2026-03-27 10:30:00' },
  { id: '6', name: '充电桩-002', type: 'charger', station: '浦东站', status: 'online', power: 0, voltage: 220, current: 0, temperature: 32, lastUpdate: '2026-03-27 10:25:00' },
  { id: '7', name: '充电桩-003', type: 'charger', station: '浦西站', status: 'fault', power: 0, voltage: 0, current: 0, temperature: 0, lastUpdate: '2026-03-27 10:10:00' },
  { id: '8', name: '配电柜-01', type: 'cabinet', station: '浦东站', status: 'online', power: 180, voltage: 380, current: 47.3, temperature: 35, lastUpdate: '2026-03-27 10:30:00' },
];

const DeviceListPage: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [detailVisible, setDetailVisible] = useState(false);
  const [selectedDevice, setSelectedDevice] = useState<Device | null>(null);
  const [form] = Form.useForm();
  
  // 筛选条件
  const [filters, setFilters] = useState({
    search: '',
    type: 'all',
    status: 'all',
    station: 'all',
  });

  useEffect(() => {
    fetchDevices();
  }, [filters]);

  const fetchDevices = async () => {
    setLoading(true);
    try {
      // 调用真实 API
      const params: any = {};
      if (filters.type !== 'all') params.type = filters.type;
      if (filters.status !== 'all') params.status = filters.status;
      
      const response: any = await deviceAPI.list(params);
      
      // 转换后端数据格式
      const apiDevices = (response.devices || []).map((d: any) => ({
        id: String(d.id),
        name: d.name,
        type: d.type,
        station: `站点 ${d.station_id}`,
        status: d.status || 'offline',
        power: d.power || 0,
        voltage: d.model?.voltage || 380,
        current: d.model?.current || 0,
        temperature: 35,
        lastUpdate: d.updated_at || new Date().toISOString(),
      }));
      
      // 本地筛选
      let filtered = apiDevices;
      if (filters.search) {
        filtered = filtered.filter((d: Device) => d.name.includes(filters.search));
      }
      if (filters.station !== 'all') {
        filtered = filtered.filter((d: Device) => d.station.includes(filters.station));
      }
      
      setDevices(filtered);
    } catch (error) {
      console.error('获取设备列表失败:', error);
      message.error('获取设备列表失败');
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = () => {
    setSelectedDevice(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (record: Device) => {
    setSelectedDevice(record);
    form.setFieldsValue(record);
    setModalVisible(true);
  };

  const handleDelete = async (id: string) => {
    try {
      // await deviceAPI.delete(id);
      message.success('删除成功');
      fetchDevices();
    } catch (error) {
      message.error('删除失败');
    }
  };

  const handleView = (record: Device) => {
    setSelectedDevice(record);
    setDetailVisible(true);
  };

  const handleExport = () => {
    message.success('导出功能开发中');
  };

  const getTypeTag = (type: string) => {
    const types: Record<string, { color: string; text: string }> = {
      inverter: { color: 'gold', text: '光伏逆变器' },
      battery: { color: 'blue', text: '储能电池' },
      charger: { color: 'green', text: '充电桩' },
      cabinet: { color: 'purple', text: '配电柜' },
    };
    return types[type] || { color: 'default', text: type };
  };

  const getStatusBadge = (status: string) => {
    const statusMap: Record<string, { status: 'success' | 'error' | 'warning'; text: string }> = {
      online: { status: 'success', text: '在线' },
      offline: { status: 'error', text: '离线' },
      fault: { status: 'error', text: '故障' },
    };
    return statusMap[status] || { status: 'default', text: status };
  };

  const columns = [
    {
      title: '设备名称',
      dataIndex: 'name',
      key: 'name',
      render: (text: string, record: Device) => (
        <Space>
          <Avatar 
            icon={<DesktopOutlined />} 
            style={{ 
              backgroundColor: record.status === 'online' ? '#52c41a' : '#d9d9d9' 
            }} 
          />
          <a onClick={() => handleView(record)}>{text}</a>
        </Space>
      ),
    },
    {
      title: '设备类型',
      dataIndex: 'type',
      key: 'type',
      render: (type: string) => {
        const tag = getTypeTag(type);
        return <Tag color={tag.color}>{tag.text}</Tag>;
      },
    },
    {
      title: '所属站点',
      dataIndex: 'station',
      key: 'station',
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => {
        const badge = getStatusBadge(status);
        return <Badge status={badge.status} text={badge.text} />;
      },
    },
    {
      title: '功率(kW)',
      dataIndex: 'power',
      key: 'power',
      render: (power: number) => (
        <span style={{ color: power && power > 0 ? '#52c41a' : '#ff4d4f' }}>
          {power?.toFixed(1) || '-'}
        </span>
      ),
    },
    {
      title: '电压(V)',
      dataIndex: 'voltage',
      key: 'voltage',
    },
    {
      title: '电流(A)',
      dataIndex: 'current',
      key: 'current',
      render: (current: number) => current?.toFixed(1) || '-',
    },
    {
      title: '温度(°C)',
      dataIndex: 'temperature',
      key: 'temperature',
      render: (temp: number) => {
        let color = '';
        if (temp > 60) color = '#ff4d4f';
        else if (temp > 50) color = '#faad14';
        return <span style={{ color }}>{temp || '-'}</span>;
      },
    },
    {
      title: '更新时间',
      dataIndex: 'lastUpdate',
      key: 'lastUpdate',
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      render: (_: any, record: Device) => (
        <Space>
          <Tooltip title="编辑">
            <Button 
              type="text" 
              icon={<EditOutlined />} 
              onClick={() => handleEdit(record)} 
            />
          </Tooltip>
          <Tooltip title="远程控制">
            <Button 
              type="text" 
              onClick={() => window.location.href = '/remote-control'}
            >
              控制
            </Button>
          </Tooltip>
          <Popconfirm
            title="确认删除此设备？"
            onConfirm={() => handleDelete(record.id)}
            okText="确认"
            cancelText="取消"
          >
            <Tooltip title="删除">
              <Button type="text" danger icon={<DeleteOutlined />} />
            </Tooltip>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <Card>
        {/* 筛选区域 */}
        <div style={{ marginBottom: 16 }}>
          <Row gutter={[16, 16]} align="middle">
            <Col>
              <Input
                placeholder="搜索设备名称"
                prefix={<SearchOutlined />}
                style={{ width: 200 }}
                value={filters.search}
                onChange={e => setFilters({ ...filters, search: e.target.value })}
                allowClear
              />
            </Col>
            <Col>
              <Select
                style={{ width: 140 }}
                value={filters.type}
                onChange={val => setFilters({ ...filters, type: val })}
                suffixIcon={<FilterOutlined />}
              >
                <Option value="all">全部类型</Option>
                <Option value="inverter">光伏逆变器</Option>
                <Option value="battery">储能电池</Option>
                <Option value="charger">充电桩</Option>
                <Option value="cabinet">配电柜</Option>
              </Select>
            </Col>
            <Col>
              <Select
                style={{ width: 120 }}
                value={filters.status}
                onChange={val => setFilters({ ...filters, status: val })}
              >
                <Option value="all">全部状态</Option>
                <Option value="online">在线</Option>
                <Option value="offline">离线</Option>
                <Option value="fault">故障</Option>
              </Select>
            </Col>
            <Col>
              <Select
                style={{ width: 140 }}
                value={filters.station}
                onChange={val => setFilters({ ...filters, station: val })}
              >
                <Option value="all">全部站点</Option>
                <Option value="浦东站">浦东站</Option>
                <Option value="浦西站">浦西站</Option>
              </Select>
            </Col>
            <Col flex="auto">
              <Space style={{ float: 'right' }}>
                <Button icon={<ReloadOutlined />} onClick={fetchDevices}>
                  刷新
                </Button>
                <Button icon={<ExportOutlined />} onClick={handleExport}>
                  导出
                </Button>
                <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd}>
                  添加设备
                </Button>
              </Space>
            </Col>
          </Row>
        </div>

        {/* 统计卡片 */}
        <Row gutter={16} style={{ marginBottom: 16 }}>
          <Col>
            <Tag color="gold">光伏逆变器 {devices.filter(d => d.type === 'inverter').length}</Tag>
          </Col>
          <Col>
            <Tag color="blue">储能电池 {devices.filter(d => d.type === 'battery').length}</Tag>
          </Col>
          <Col>
            <Tag color="green">充电桩 {devices.filter(d => d.type === 'charger').length}</Tag>
          </Col>
          <Col>
            <Tag color="purple">配电柜 {devices.filter(d => d.type === 'cabinet').length}</Tag>
          </Col>
          <Col>
            <Badge count={devices.filter(d => d.status === 'offline').length} style={{ backgroundColor: '#ff4d4f' }}>
              <Tag>离线设备</Tag>
            </Badge>
          </Col>
        </Row>

        {/* 设备表格 */}
        <Table
          columns={columns}
          dataSource={devices}
          rowKey="id"
          loading={loading}
          pagination={{
            total: devices.length,
            pageSize: 10,
            showSizeChanger: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          scroll={{ x: 1200 }}
        />
      </Card>

      {/* 添加/编辑设备弹窗 */}
      <Modal
        title={selectedDevice ? '编辑设备' : '添加设备'}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={() => {
          form.validateFields().then(values => {
            message.success(selectedDevice ? '编辑成功' : '添加成功');
            setModalVisible(false);
            fetchDevices();
          });
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="name" label="设备名称" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="type" label="设备类型" rules={[{ required: true }]}>
            <Select>
              <Option value="inverter">光伏逆变器</Option>
              <Option value="battery">储能电池</Option>
              <Option value="charger">充电桩</Option>
              <Option value="cabinet">配电柜</Option>
            </Select>
          </Form.Item>
          <Form.Item name="station" label="所属站点" rules={[{ required: true }]}>
            <Select>
              <Option value="浦东站">浦东站</Option>
              <Option value="浦西站">浦西站</Option>
            </Select>
          </Form.Item>
        </Form>
      </Modal>

      {/* 设备详情弹窗 */}
      <Modal
        title="设备详情"
        open={detailVisible}
        onCancel={() => setDetailVisible(false)}
        footer={[
          <Button key="control" type="primary" onClick={() => window.location.href = '/remote-control'}>
            远程控制
          </Button>,
          <Button key="close" onClick={() => setDetailVisible(false)}>
            关闭
          </Button>,
        ]}
      >
        {selectedDevice && (
          <div>
            <Row gutter={16}>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>设备名称</div>
                  <div style={{ fontSize: 16, fontWeight: 500 }}>{selectedDevice.name}</div>
                </div>
              </Col>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>设备状态</div>
                  <Badge status={getStatusBadge(selectedDevice.status).status as any} text={getStatusBadge(selectedDevice.status).text} />
                </div>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>功率</div>
                  <div style={{ fontSize: 24, color: '#52c41a' }}>{selectedDevice.power?.toFixed(1) || 0} kW</div>
                </div>
              </Col>
              <Col span={12}>
                <div style={{ marginBottom: 16 }}>
                  <div style={{ color: '#8c8c8c' }}>温度</div>
                  <div style={{ fontSize: 24 }}>{selectedDevice.temperature || 0} °C</div>
                </div>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <div>电压: {selectedDevice.voltage} V</div>
              </Col>
              <Col span={8}>
                <div>电流: {selectedDevice.current?.toFixed(1)} A</div>
              </Col>
              <Col span={8}>
                <div>更新时间: {selectedDevice.lastUpdate}</div>
              </Col>
            </Row>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default DeviceListPage;