/**
 * 网关管理页面 - 天链运维平台
 */
import React, { useState, useEffect } from 'react';
import { 
  Card, Table, Button, Space, Input, Tag, Modal, Form, Row, Col, 
  message, Statistic, Progress, Select, Tabs, Descriptions, Badge 
} from 'antd';
import { 
  SearchOutlined, ReloadOutlined, SettingOutlined, CloudUploadOutlined,
  PoweroffOutlined, DeleteOutlined, GlobalOutlined 
} from '@ant-design/icons';
import api from '../../api';

interface Gateway {
  id: number;
  sn: string;
  name: string;
  model: string;
  station_id: number;
  station_name: string;
  status: string;
  firmware_version: string;
  ip_address: string;
  uptime: number;
  last_heartbeat: string;
}

const GatewaysPage: React.FC = () => {
  const [gateways, setGateways] = useState<Gateway[]>([]);
  const [loading, setLoading] = useState(false);
  const [detailVisible, setDetailVisible] = useState(false);
  const [upgradeModalVisible, setUpgradeModalVisible] = useState(false);
  const [selectedGateway, setSelectedGateway] = useState<Gateway | null>(null);
  const [upgradeForm] = Form.useForm();
  const [firmwareList, setFirmwareList] = useState<any[]>([]);
  const [searchText, setSearchText] = useState('');
  const [stationFilter, setStationFilter] = useState<string>('all');

  useEffect(() => {
    loadGateways();
    loadFirmwareList();
  }, [stationFilter]);

  const loadGateways = async () => {
    setLoading(true);
    try {
      const params: any = { limit: 20 };
      if (stationFilter !== 'all') params.station_id = parseInt(stationFilter);
      const res = await api.get('/api/v1/gateways', { params });
      setGateways(res.data?.data || []);
    } catch (error) {
      message.error('加载网关失败');
    } finally {
      setLoading(false);
    }
  };

  const loadFirmwareList = async () => {
    try {
      const res = await api.get('/api/v1/firmware/list');
      setFirmwareList(res.data?.data || []);
    } catch (error) {
      console.error('加载固件列表失败');
    }
  };

  const handleViewDetail = async (id: number) => {
    try {
      const res = await api.get(`/api/v1/gateways/${id}`);
      setSelectedGateway(res.data);
      setDetailVisible(true);
    } catch (error) {
      message.error('加载详情失败');
    }
  };

  const handleUpgrade = (gateway: Gateway) => {
    setSelectedGateway(gateway);
    upgradeForm.resetFields();
    upgradeForm.setFieldsValue({ firmware_version: firmwareList[0]?.version || '' });
    setUpgradeModalVisible(true);
  };

  const handleUpgradeSubmit = async () => {
    try {
      const values = await upgradeForm.validateFields();
      await api.post(`/api/v1/gateways/${selectedGateway?.id}/upgrade`, values);
      message.success('固件升级任务已创建');
      setUpgradeModalVisible(false);
      loadGateways();
    } catch (error) {
      message.error('升级失败');
    }
  };

  const handleReboot = async (id: number) => {
    try {
      await api.post(`/api/v1/gateways/${id}/reboot`);
      message.success('重启指令已发送');
      loadGateways();
    } catch (error) {
      message.error('重启失败');
    }
  };

  const handleReset = async (id: number) => {
    try {
      await api.post(`/api/v1/gateways/${id}/reset`);
      message.success('重置指令已发送');
      loadGateways();
    } catch (error) {
      message.error('重置失败');
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'online': return 'green';
      case 'offline': return 'red';
      case 'fault': return 'orange';
      default: return 'default';
    }
  };

  const formatUptime = (seconds: number) => {
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    return `${days}天${hours}小时`;
  };

  const filteredList = gateways.filter(gw => 
    gw.sn.includes(searchText) || gw.name.includes(searchText) || gw.ip_address.includes(searchText)
  );

  const columns = [
    { title: 'SN码', dataIndex: 'sn', key: 'sn', width: 150 },
    { title: '网关名称', dataIndex: 'name', key: 'name', width: 120 },
    { title: '型号', dataIndex: 'model', key: 'model', width: 100 },
    { title: '站点', dataIndex: 'station_name', key: 'station_name', width: 120,
      render: (text: string) => <span><GlobalOutlined /> {text}</span> },
    { title: '状态', dataIndex: 'status', key: 'status', width: 80,
      render: (status: string) => <Tag color={getStatusColor(status)}>{status}</Tag> },
    { title: '固件版本', dataIndex: 'firmware_version', key: 'firmware_version', width: 100 },
    { title: 'IP地址', dataIndex: 'ip_address', key: 'ip_address', width: 120 },
    { title: '运行时间', dataIndex: 'uptime', key: 'uptime', width: 100,
      render: (uptime: number) => formatUptime(uptime) },
    { title: '最后心跳', dataIndex: 'last_heartbeat', key: 'last_heartbeat', width: 150,
      render: (text: string) => new Date(text).toLocaleString() },
    { title: '操作', key: 'action', width: 180, fixed: 'right' as const,
      render: (record: Gateway) => (
        <Space size="small">
          <Button type="link" size="small" onClick={() => handleViewDetail(record.id)}>详情</Button>
          <Button type="link" size="small" icon={<CloudUploadOutlined />}
            onClick={() => handleUpgrade(record)}>升级</Button>
          <Button type="link" size="small" icon={<PoweroffOutlined />}
            onClick={() => handleReboot(record.id)}>重启</Button>
          <Button type="link" size="small" danger icon={<SettingOutlined />}
            onClick={() => handleReset(record.id)}>重置</Button>
        </Space>
      ) },
  ];

  return (
    <div style={{ padding: '20px' }}>
      <Card>
        <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
          <Col span={6}>
            <Statistic title="网关总数" value={gateways.length} suffix="台" />
          </Col>
          <Col span={6}>
            <Statistic title="在线网关" value={gateways.filter(g => g.status === 'online').length} suffix="台"
              valueStyle={{ color: '#52c41a' }} />
          </Col>
          <Col span={6}>
            <Statistic title="离线网关" value={gateways.filter(g => g.status === 'offline').length} suffix="台"
              valueStyle={{ color: '#f5222d' }} />
          </Col>
          <Col span={6}>
            <Statistic title="故障网关" value={gateways.filter(g => g.status === 'fault').length} suffix="台"
              valueStyle={{ color: '#faad14' }} />
          </Col>
        </Row>

        <Space style={{ marginBottom: 16 }}>
          <Input.Search placeholder="搜索网关" value={searchText} onChange={e => setSearchText(e.target.value)}
            style={{ width: 200 }} allowClear />
          <Select value={stationFilter} onChange={setStationFilter} style={{ width: 120 }}>
            <Select.Option value="all">全部站点</Select.Option>
            <Select.Option value="1">浦东示范站</Select.Option>
            <Select.Option value="2">浦西中心站</Select.Option>
            <Select.Option value="3">虹桥机场站</Select.Option>
          </Select>
          <Button icon={<SearchOutlined />} onClick={loadGateways}>刷新</Button>
        </Space>

        <Table dataSource={filteredList} columns={columns} rowKey="id" 
          loading={loading} scroll={{ x: 1400 }} pagination={{ pageSize: 10 }} />
      </Card>

      {/* 详情模态框 */}
      <Modal title="网关详情" open={detailVisible} onCancel={() => setDetailVisible(false)}
        footer={null} width={700}>
        {selectedGateway && (
          <Descriptions bordered column={2}>
            <Descriptions.Item label="SN码">{selectedGateway.sn}</Descriptions.Item>
            <Descriptions.Item label="网关名称">{selectedGateway.name}</Descriptions.Item>
            <Descriptions.Item label="型号">{selectedGateway.model}</Descriptions.Item>
            <Descriptions.Item label="固件版本">{selectedGateway.firmware_version}</Descriptions.Item>
            <Descriptions.Item label="站点">{selectedGateway.station_name}</Descriptions.Item>
            <Descriptions.Item label="IP地址">{selectedGateway.ip_address}</Descriptions.Item>
            <Descriptions.Item label="状态">
              <Tag color={getStatusColor(selectedGateway.status)}>{selectedGateway.status}</Tag>
            </Descriptions.Item>
            <Descriptions.Item label="运行时间">{formatUptime(selectedGateway.uptime)}</Descriptions.Item>
            <Descriptions.Item label="最后心跳">
              {new Date(selectedGateway.last_heartbeat).toLocaleString()}
            </Descriptions.Item>
            <Descriptions.Item label="支持协议">
              {['STAR_CHARGE_3_0', 'OCPP_1_6', 'MODBUS_TCP'].map(p => <Tag key={p}>{p}</Tag>)}
            </Descriptions.Item>
          </Descriptions>
        )}
      </Modal>

      {/* 升级模态框 */}
      <Modal title="固件升级" open={upgradeModalVisible} onOk={handleUpgradeSubmit} onCancel={() => setUpgradeModalVisible(false)}>
        {selectedGateway && (
          <Descriptions bordered column={1} style={{ marginBottom: 16 }}>
            <Descriptions.Item label="网关">{selectedGateway.name} ({selectedGateway.sn})</Descriptions.Item>
            <Descriptions.Item label="当前版本">{selectedGateway.firmware_version}</Descriptions.Item>
          </Descriptions>
        )}
        <Form form={upgradeForm} layout="vertical">
          <Form.Item name="firmware_version" label="目标版本" rules={[{ required: true }]}>
            <Select placeholder="选择固件版本">
              {firmwareList.map(fw => (
                <Select.Option key={fw.id} value={fw.version}>
                  {fw.version} - {fw.description} ({fw.release_date})
                </Select.Option>
              ))}
            </Select>
          </Form.Item>
          <Form.Item name="firmware_url" label="固件URL">
            <Input placeholder="可选，自动从服务器获取" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default GatewaysPage;