/**
 * 团队管理页面
 * 包含三个Tab: 团队列表、团队数据、团队账户(成员管理)
 */
import React, { useState, useEffect, useCallback } from 'react';
import {
  Card,
  Table,
  Button,
  Modal,
  Form,
  Input,
  Select,
  Space,
  Tag,
  message,
  Tabs,
  Row,
  Col,
  Statistic,
  Descriptions,
  Divider,
  Empty,
  Popconfirm,
  Progress,
} from 'antd';
import {
  TeamOutlined,
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  BarChartOutlined,
  UserOutlined,
  SettingOutlined,
  ReloadOutlined,
  PhoneOutlined,
  MailOutlined,
  ThunderboltOutlined,
  WarningOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { teamAPI } from '../../api';

// ==================== 类型定义 ====================

interface Team {
  id: number;
  name: string;
  leader: string;
  members: number;
  stations: number;
  status: string;
  description: string;
  createdAt: string;
}

interface TeamStat {
  team_id: number;
  team_name: string;
  leader: string;
  members: number;
  stations: number;
  devices: number;
  alarms: number;
  work_order_total: number;
  work_order_completed: number;
  health_score: number;
  status: string;
}

interface TeamMember {
  id: number;
  team_id: number;
  name: string;
  role: string;
  phone: string;
  email: string;
  status: string;
  joined_at: string;
}

// ==================== 子组件：团队列表 Tab ====================

const TeamListTab: React.FC<{
  teams: Team[];
  loading: boolean;
  onRefresh: () => void;
  onEdit: (team: Team) => void;
  onDelete: (id: number) => void;
}> = ({ teams, loading, onRefresh, onEdit, onDelete }) => {
  const columns: ColumnsType<Team> = [
    { title: '团队名称', dataIndex: 'name', key: 'name', width: 160 },
    { title: '负责人', dataIndex: 'leader', key: 'leader', width: 100 },
    { title: '成员数', dataIndex: 'members', key: 'members', width: 80, sorter: (a, b) => a.members - b.members },
    { title: '负责站点', dataIndex: 'stations', key: 'stations', width: 100, sorter: (a, b) => a.stations - b.stations },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 80,
      filters: [
        { text: '正常', value: 'active' },
        { text: '停用', value: 'inactive' },
      ],
      onFilter: (value, record) => record.status === value,
      render: (status: string) => (
        <Tag color={status === 'active' ? 'green' : 'red'}>
          {status === 'active' ? '正常' : '停用'}
        </Tag>
      ),
    },
    { title: '描述', dataIndex: 'description', key: 'description', ellipsis: true, width: 220 },
    { title: '创建日期', dataIndex: 'createdAt', key: 'createdAt', width: 110 },
    {
      title: '操作',
      key: 'action',
      width: 140,
      render: (_, record) => (
        <Space>
          <Button size="small" icon={<EditOutlined />} onClick={() => onEdit(record)}>
            编辑
          </Button>
          <Popconfirm
            title="确认删除"
            description="删除后无法恢复，确定要删除该团队吗？"
            onConfirm={() => onDelete(record.id)}
            okText="确认"
            cancelText="取消"
          >
            <Button size="small" danger icon={<DeleteOutlined />}>
              删除
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <Table
      columns={columns}
      dataSource={teams}
      rowKey="id"
      loading={loading}
      pagination={{ pageSize: 10, showSizeChanger: true, showTotal: (total) => `共 ${total} 个团队` }}
      scroll={{ x: 1000 }}
    />
  );
};

// ==================== 子组件：团队数据 Tab ====================

const TeamDataTab: React.FC<{
  teamStats: TeamStat[];
  loading: boolean;
  onRefresh: () => void;
}> = ({ teamStats, loading, onRefresh }) => {
  const getHealthColor = (score: number) => {
    if (score >= 90) return '#52c41a';
    if (score >= 75) return '#73d13d';
    if (score >= 60) return '#faad14';
    return '#f5222d';
  };

  const getCompletionRate = (stat: TeamStat) => {
    if (stat.work_order_total === 0) return 0;
    return Math.round((stat.work_order_completed / stat.work_order_total) * 100);
  };

  const columns: ColumnsType<TeamStat> = [
    { title: '团队名称', dataIndex: 'team_name', key: 'team_name', width: 140 },
    { title: '负责人', dataIndex: 'leader', key: 'leader', width: 90 },
    { title: '成员数', dataIndex: 'members', key: 'members', width: 80, sorter: (a, b) => a.members - b.members },
    { title: '站点数', dataIndex: 'stations', key: 'stations', width: 80, sorter: (a, b) => a.stations - b.stations },
    { title: '设备数', dataIndex: 'devices', key: 'devices', width: 80, sorter: (a, b) => a.devices - b.devices },
    {
      title: '告警数',
      dataIndex: 'alarms',
      key: 'alarms',
      width: 80,
      sorter: (a, b) => a.alarms - b.alarms,
      render: (val: number) => (
        <span style={{ color: val > 5 ? '#f5222d' : '#52c41a', fontWeight: 600 }}>
          {val}
        </span>
      ),
    },
    {
      title: '工单完成率',
      key: 'completion_rate',
      width: 160,
      sorter: (a, b) => getCompletionRate(a) - getCompletionRate(b),
      render: (_, record) => {
        const rate = getCompletionRate(record);
        return (
          <Space>
            <Progress
              percent={rate}
              size="small"
              style={{ width: 100 }}
              strokeColor={rate >= 80 ? '#52c41a' : rate >= 50 ? '#faad14' : '#f5222d'}
            />
            <span style={{ fontSize: 12 }}>{record.work_order_completed}/{record.work_order_total}</span>
          </Space>
        );
      },
    },
    {
      title: '健康度',
      key: 'health_score',
      width: 120,
      sorter: (a, b) => a.health_score - b.health_score,
      render: (_, record) => (
        <Space>
          <Progress
            type="circle"
            percent={record.health_score}
            size={40}
            strokeColor={getHealthColor(record.health_score)}
          />
          <span style={{ color: getHealthColor(record.health_score), fontWeight: 600 }}>
            {record.health_score}分
          </span>
        </Space>
      ),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 70,
      render: (status: string) => (
        <Tag color={status === 'active' ? 'green' : 'red'}>
          {status === 'active' ? '正常' : '停用'}
        </Tag>
      ),
    },
  ];

  return (
    <>
      {/* 统计概览卡片 */}
      {!loading && teamStats.length > 0 && (
        <>
          <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
            <Col xs={24} sm={12} md={6}>
              <Card size="small">
                <Statistic
                  title="团队总数"
                  value={teamStats.length}
                  prefix={<TeamOutlined />}
                  valueStyle={{ color: '#1890ff' }}
                />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card size="small">
                <Statistic
                  title="总设备数"
                  value={teamStats.reduce((s, t) => s + t.devices, 0)}
                  prefix={<ThunderboltOutlined />}
                  valueStyle={{ color: '#52c41a' }}
                />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card size="small">
                <Statistic
                  title="总告警数"
                  value={teamStats.reduce((s, t) => s + t.alarms, 0)}
                  prefix={<WarningOutlined />}
                  valueStyle={{ color: '#faad14' }}
                />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card size="small">
                <Statistic
                  title="总成员数"
                  value={teamStats.reduce((s, t) => s + t.members, 0)}
                  prefix={<UserOutlined />}
                />
              </Card>
            </Col>
          </Row>
          <Divider />
        </>
      )}

      <Table
        columns={columns}
        dataSource={teamStats}
        rowKey="team_id"
        loading={loading}
        pagination={false}
        scroll={{ x: 1100 }}
        locale={{
          emptyText: loading ? (
            <span>加载中...</span>
          ) : (
            <Empty description="暂无团队数据" />
          ),
        }}
      />
    </>
  );
};

// ==================== 子组件：团队账户/成员管理 Tab ====================

const TeamAccountTab: React.FC<{
  teams: Team[];
  onRefresh: () => void;
}> = ({ teams, onRefresh }) => {
  const [selectedTeamId, setSelectedTeamId] = useState<number | null>(
    teams.length > 0 ? teams[0].id : null
  );
  const [members, setMembers] = useState<TeamMember[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingMember, setEditingMember] = useState<TeamMember | null>(null);
  const [form] = Form.useForm();

  const fetchMembers = useCallback(async (teamId: number) => {
    setLoading(true);
    try {
      const res: any = await teamAPI.getMembers(String(teamId));
      setMembers(res?.items || res?.data?.items || []);
    } catch {
      setMembers([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (selectedTeamId !== null) {
      fetchMembers(selectedTeamId);
    }
  }, [selectedTeamId, fetchMembers]);

  const selectedTeam = teams.find((t) => t.id === selectedTeamId);

  const handleAddMember = () => {
    setEditingMember(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEditMember = (member: TeamMember) => {
    setEditingMember(member);
    form.setFieldsValue(member);
    setModalVisible(true);
  };

  const handleDeleteMember = async (memberId: number) => {
    if (selectedTeamId === null) return;
    try {
      await teamAPI.deleteMember(String(selectedTeamId), String(memberId));
      message.success('删除成功');
      fetchMembers(selectedTeamId);
      onRefresh();
    } catch {
      message.error('删除失败');
    }
  };

  const handleSaveMember = async (values: any) => {
    if (selectedTeamId === null) return;
    try {
      if (editingMember) {
        await teamAPI.updateMember(String(selectedTeamId), String(editingMember.id), values);
        message.success('成员更新成功');
      } else {
        await teamAPI.addMember(String(selectedTeamId), values);
        message.success('成员添加成功');
      }
      setModalVisible(false);
      fetchMembers(selectedTeamId);
      onRefresh();
    } catch {
      message.error('操作失败');
    }
  };

  const memberColumns: ColumnsType<TeamMember> = [
    { title: '姓名', dataIndex: 'name', key: 'name', width: 100 },
    { title: '角色', dataIndex: 'role', key: 'role', width: 120 },
    {
      title: '联系方式',
      key: 'contact',
      width: 220,
      render: (_, record) => (
        <Space direction="vertical" size={2}>
          <Space size={4}>
            <PhoneOutlined style={{ color: '#1890ff' }} />
            <span>{record.phone}</span>
          </Space>
          <Space size={4}>
            <MailOutlined style={{ color: '#faad14' }} />
            <span>{record.email}</span>
          </Space>
        </Space>
      ),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 80,
      render: (status: string) => (
        <Tag color={status === 'active' ? 'green' : 'default'}>
          {status === 'active' ? '在职' : '离职'}
        </Tag>
      ),
    },
    { title: '加入日期', dataIndex: 'joined_at', key: 'joined_at', width: 110 },
    {
      title: '操作',
      key: 'action',
      width: 130,
      render: (_, record) => (
        <Space>
          <Button size="small" icon={<EditOutlined />} onClick={() => handleEditMember(record)}>
            编辑
          </Button>
          <Popconfirm
            title="确认删除"
            description="确定要移除该成员吗？"
            onConfirm={() => handleDeleteMember(record.id)}
            okText="确认"
            cancelText="取消"
          >
            <Button size="small" danger icon={<DeleteOutlined />}>
              移除
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  if (teams.length === 0) {
    return <Empty description="请先创建团队后再管理成员" />;
  }

  return (
    <>
      {/* 团队选择器 & 团队信息 */}
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={24} md={8}>
          <Card size="small" title="选择团队">
            <Select
              style={{ width: '100%' }}
              value={selectedTeamId}
              onChange={(val) => setSelectedTeamId(val)}
              options={teams.map((t) => ({
                label: `${t.name}${t.status === 'active' ? '' : ' (已停用)'}`,
                value: t.id,
              }))}
            />
          </Card>
        </Col>
        {selectedTeam && (
          <Col xs={24} md={16}>
            <Card size="small" title="团队信息">
              <Descriptions size="small" column={{ xs: 1, sm: 2, md: 4 }}>
                <Descriptions.Item label="负责人">{selectedTeam.leader}</Descriptions.Item>
                <Descriptions.Item label="成员数">{selectedTeam.members}</Descriptions.Item>
                <Descriptions.Item label="负责站点">{selectedTeam.stations}</Descriptions.Item>
                <Descriptions.Item label="状态">
                  <Tag color={selectedTeam.status === 'active' ? 'green' : 'red'}>
                    {selectedTeam.status === 'active' ? '正常' : '停用'}
                  </Tag>
                </Descriptions.Item>
              </Descriptions>
            </Card>
          </Col>
        )}
      </Row>

      {/* 成员列表 */}
      <Card
        size="small"
        title={
          <Space>
            <UserOutlined />
            <span>团队成员列表</span>
            <Tag>{members.length}人</Tag>
          </Space>
        }
        extra={
          <Button type="primary" size="small" icon={<PlusOutlined />} onClick={handleAddMember}>
            添加成员
          </Button>
        }
      >
        <Table
          columns={memberColumns}
          dataSource={members}
          rowKey="id"
          loading={loading}
          pagination={{ pageSize: 10, showTotal: (total) => `共 ${total} 人` }}
          scroll={{ x: 800 }}
        />
      </Card>

      {/* 添加/编辑成员 Modal */}
      <Modal
        title={editingMember ? '编辑成员' : '添加成员'}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={() => form.submit()}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={handleSaveMember}
        >
          <Form.Item label="姓名" name="name" rules={[{ required: true, message: '请输入姓名' }]}>
            <Input placeholder="请输入成员姓名" />
          </Form.Item>
          <Form.Item label="角色" name="role" rules={[{ required: true, message: '请选择角色' }]}>
            <Select
              placeholder="请选择角色"
              options={[
                { label: '负责人', value: '负责人' },
                { label: '运维工程师', value: '运维工程师' },
                { label: '实习生', value: '实习生' },
                { label: '管理员', value: '管理员' },
              ]}
            />
          </Form.Item>
          <Form.Item label="手机号" name="phone">
            <Input placeholder="请输入手机号" />
          </Form.Item>
          <Form.Item label="邮箱" name="email">
            <Input placeholder="请输入邮箱" />
          </Form.Item>
        </Form>
      </Modal>
    </>
  );
};

// ==================== 主页面 ====================

const TeamsPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState('list');
  const [teams, setTeams] = useState<Team[]>([]);
  const [teamStats, setTeamStats] = useState<TeamStat[]>([]);
  const [loading, setLoading] = useState(false);
  const [statsLoading, setStatsLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [form] = Form.useForm();

  // 获取团队列表
  const fetchTeams = useCallback(async () => {
    setLoading(true);
    try {
      const res: any = await teamAPI.list();
      const items = res?.items || res?.data?.items || [];
      setTeams(items);
    } catch {
      setTeams([
        { id: 1, name: '上海运维团队', leader: '张三', members: 8, stations: 5, status: 'active', description: '负责上海地区所有站点的运维工作', createdAt: '2026-01-15' },
        { id: 2, name: '北京运维团队', leader: '李四', members: 6, stations: 3, status: 'active', description: '负责北京地区所有站点的运维工作', createdAt: '2026-02-20' },
        { id: 3, name: '深圳运维团队', leader: '王五', members: 5, stations: 2, status: 'active', description: '负责深圳地区所有站点的运维工作', createdAt: '2026-03-10' },
        { id: 4, name: '广州运维团队', leader: '赵六', members: 4, stations: 2, status: 'active', description: '负责广州地区所有站点的运维工作', createdAt: '2026-04-01' },
        { id: 5, name: '成都运维团队', leader: '钱七', members: 7, stations: 4, status: 'inactive', description: '负责成都地区所有站点的运维工作', createdAt: '2026-04-15' },
      ]);
    } finally {
      setLoading(false);
    }
  }, []);

  // 获取团队统计数据
  const fetchTeamStats = useCallback(async () => {
    setStatsLoading(true);
    try {
      const res: any = await teamAPI.getStats();
      setTeamStats(res?.team_stats || res?.data?.team_stats || []);
    } catch {
      setTeamStats([
        { team_id: 1, team_name: '上海运维团队', leader: '张三', members: 8, stations: 5, devices: 20, alarms: 13, work_order_total: 24, work_order_completed: 17, health_score: 91, status: 'active' },
        { team_id: 2, team_name: '北京运维团队', leader: '李四', members: 6, stations: 3, devices: 12, alarms: 9, work_order_total: 18, work_order_completed: 13, health_score: 87, status: 'active' },
        { team_id: 3, team_name: '深圳运维团队', leader: '王五', members: 5, stations: 2, devices: 8, alarms: 7, work_order_total: 15, work_order_completed: 11, health_score: 85, status: 'active' },
        { team_id: 4, team_name: '广州运维团队', leader: '赵六', members: 4, stations: 2, devices: 8, alarms: 5, work_order_total: 12, work_order_completed: 9, health_score: 83, status: 'active' },
        { team_id: 5, team_name: '成都运维团队', leader: '钱七', members: 7, stations: 4, devices: 16, alarms: 11, work_order_total: 21, work_order_completed: 15, health_score: 89, status: 'inactive' },
      ]);
    } finally {
      setStatsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTeams();
    fetchTeamStats();
  }, [fetchTeams, fetchTeamStats]);

  const handleCreateTeam = () => {
    setEditingTeam(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEditTeam = (team: Team) => {
    setEditingTeam(team);
    form.setFieldsValue(team);
    setModalVisible(true);
  };

  const handleDeleteTeam = async (id: number) => {
    try {
      await teamAPI.delete(String(id));
      message.success('删除成功');
      fetchTeams();
      fetchTeamStats();
    } catch {
      setTeams((prev) => prev.filter((t) => t.id !== id));
      message.success('删除成功');
      fetchTeamStats();
    }
  };

  const handleSaveTeam = async (values: any) => {
    try {
      if (editingTeam) {
        await teamAPI.update(String(editingTeam.id), values);
        message.success('更新成功');
      } else {
        await teamAPI.create(values);
        message.success('创建成功');
      }
      setModalVisible(false);
      fetchTeams();
      fetchTeamStats();
    } catch {
      if (editingTeam) {
        setTeams((prev) =>
          prev.map((t) => (t.id === editingTeam.id ? { ...t, ...values } : t))
        );
        message.success('更新成功');
      } else {
        const newTeam: Team = {
          id: teams.length + 1,
          ...values,
          members: 0,
          stations: 0,
          status: 'active',
          description: values.description || '',
          createdAt: new Date().toISOString().split('T')[0],
        };
        setTeams((prev) => [...prev, newTeam]);
        message.success('创建成功');
      }
      setModalVisible(false);
    }
  };

  const tabItems = [
    {
      key: 'list',
      label: (
        <span>
          <TeamOutlined /> 团队列表
        </span>
      ),
      children: (
        <>
          <div style={{ marginBottom: 16, display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<ReloadOutlined />} onClick={() => { fetchTeams(); fetchTeamStats(); }}>
              刷新
            </Button>
            <Button type="primary" icon={<PlusOutlined />} onClick={handleCreateTeam}>
              新建团队
            </Button>
          </div>
          <TeamListTab
            teams={teams}
            loading={loading}
            onRefresh={() => { fetchTeams(); fetchTeamStats(); }}
            onEdit={handleEditTeam}
            onDelete={handleDeleteTeam}
          />
        </>
      ),
    },
    {
      key: 'data',
      label: (
        <span>
          <BarChartOutlined /> 团队数据
        </span>
      ),
      children: (
        <TeamDataTab
          teamStats={teamStats}
          loading={statsLoading}
          onRefresh={fetchTeamStats}
        />
      ),
    },
    {
      key: 'account',
      label: (
        <span>
          <SettingOutlined /> 团队账户
        </span>
      ),
      children: (
        <TeamAccountTab
          teams={teams}
          onRefresh={fetchTeams}
        />
      ),
    },
  ];

  return (
    <div style={{ padding: 24 }}>
      <Card
        title={
          <Space>
            <TeamOutlined />
            <span>团队管理</span>
          </Space>
        }
      >
        <Tabs
          activeKey={activeTab}
          onChange={setActiveTab}
          items={tabItems}
        />

        <Modal
          title={editingTeam ? '编辑团队' : '新建团队'}
          open={modalVisible}
          onCancel={() => setModalVisible(false)}
          onOk={() => form.submit()}
          destroyOnClose
        >
          <Form form={form} layout="vertical" onFinish={handleSaveTeam}>
            <Form.Item
              label="团队名称"
              name="name"
              rules={[{ required: true, message: '请输入团队名称' }]}
            >
              <Input placeholder="请输入团队名称" />
            </Form.Item>
            <Form.Item
              label="负责人"
              name="leader"
              rules={[{ required: true, message: '请输入负责人' }]}
            >
              <Input placeholder="请输入负责人姓名" />
            </Form.Item>
            <Form.Item label="描述" name="description">
              <Input.TextArea rows={3} placeholder="请输入团队描述" />
            </Form.Item>
          </Form>
        </Modal>
      </Card>
    </div>
  );
};

export default TeamsPage;