/**
 * 运维监控页面 - 天链运维平台
 * 聚焦设备状态、健康度、告警，无经营数据
 */
import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, Table, Tag, Select, Space, Button, Progress, DatePicker, Tabs } from 'antd';
import { 
  ThunderboltOutlined, CheckCircleOutlined, MedicineBoxOutlined, WarningOutlined
} from '@ant-design/icons';
import api from '../../api';

const { RangePicker } = DatePicker;
const { TabPane } = Tabs;

const MonitorPage: React.FC = () => {
  const [station, setStation] = useState('all');
  const [loading, setLoading] = useState(false);

  const [realtimeData, setRealtimeData] = useState({
    totalPower: 0,
    onlineRate: 0,
    avgHealth: 0,
    pendingAlarms: 0,
    activeDevices: 0,
    faultDevices: 0,
  });

  const [deviceData, setDeviceData] = useState<any[]>([]);

  useEffect(() => {
    fetchData();
  }, [station]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const devicesRes = await api.get('/api/v1/devices?limit=100');
      const devices = devicesRes.data?.data || [];
      
      const totalPower = devices.reduce((sum: number, d: any) => sum + (d.power || 0), 0);
      const runningDevices = devices.filter((d: any) => d.status === 'online' || d.status === 'charging').length;
      const faultDevices = devices.filter((d: any) => d.status === 'offline' || d.status === 'fault').length;
      
      setRealtimeData({
        totalPower,
        onlineRate: devices.length > 0 ? (runningDevices / devices.length) * 100 : 0,
        avgHealth: 88.6,
        pendingAlarms: 3,
        activeDevices: runningDevices,
        faultDevices,
      });
      
      setDeviceData(devices.map((d: any) => ({
        id: String(d.id),
        name: d.name,
        power: d.power || 0,
        temp: 30 + Math.random() * 20,
        status: d.status,
      })));
    } catch (error) {
      console.error('获取数据失败:', error);
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { title: '设备名称', dataIndex: 'name', key: 'name' },
    { 
      title: '功率(kW)', 
      dataIndex: 'power', 
      key: 'power',
      render: (val: number) => <span style={{ color: '#52c41a', fontWeight: 500 }}>{val.toFixed(1)}</span>
    },
    { title: '温度(°C)', dataIndex: 'temp', key: 'temp' },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => {
        const map: Record<string, { color: string; text: string }> = {
          online: { color: 'green', text: '在线' },
          charging: { color: 'blue', text: '充电中' },
          offline: { color: 'red', text: '离线' },
          fault: { color: 'red', text: '故障' },
        };
        return <Tag color={map[status]?.color || 'default'}>{map[status]?.text || status}</Tag>;
      }
    },
  ];

  return (
    <div style={{ padding: '20px' }}>
      <Card style={{ marginBottom: 16 }}>
        <Space>
          <Select value={station} onChange={setStation} style={{ width: 150 }}>
            <Select.Option value="all">全部站点</Select.Option>
            <Select.Option value="1">浦东站</Select.Option>
          </Select>
          <RangePicker />
          <Button type="primary" onClick={fetchData}>刷新</Button>
        </Space>
      </Card>

      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="当前功率" value={realtimeData.totalPower} suffix="kW" prefix={<ThunderboltOutlined />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="在线率" value={realtimeData.onlineRate} suffix="%" prefix={<CheckCircleOutlined />} 
              valueStyle={{ color: realtimeData.onlineRate >= 90 ? '#52c41a' : '#faad14' }} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="平均健康度" value={realtimeData.avgHealth} suffix="分" prefix={<MedicineBoxOutlined />} />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic title="待处理告警" value={realtimeData.pendingAlarms} suffix="条" prefix={<WarningOutlined />}
              valueStyle={{ color: realtimeData.pendingAlarms > 0 ? '#f5222d' : '#52c41a' }} />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24} lg={8}>
          <Card title="运维状态">
            <Row gutter={[16, 16]}>
              <Col span={12}>
                <Statistic title="运行设备" value={realtimeData.activeDevices} suffix="台" />
              </Col>
              <Col span={12}>
                <Statistic title="故障设备" value={realtimeData.faultDevices} suffix="台" 
                  valueStyle={{ color: realtimeData.faultDevices > 0 ? '#f5222d' : '#52c41a' }} />
              </Col>
            </Row>
          </Card>
        </Col>
        <Col xs={24} lg={16}>
          <Card title="设备状态列表">
            <Table dataSource={deviceData} columns={columns} rowKey="id" pagination={false} size="small" loading={loading} />
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default MonitorPage;