/**
 * 站点地图页面
 */
import React, { useState } from 'react';
import { Card, Row, Col, Input, List, Tag, Button, Space, Badge, Statistic, Modal, Descriptions, Divider } from 'antd';
import { SearchOutlined, EnvironmentOutlined, ThunderboltOutlined, DesktopOutlined, WarningOutlined } from '@ant-design/icons';

const { Search } = Input;

const stations = [
  { id: '1', name: '浦东站', address: '上海市浦东新区世纪大道100号', lat: 31.2304, lng: 121.4737, devices: 45, online: 43, status: 'normal', power: 856 },
  { id: '2', name: '浦西站', address: '上海市静安区南京西路100号', lat: 31.2304, lng: 121.4737, devices: 38, online: 35, status: 'normal', power: 620 },
  { id: '3', name: '嘉定站', address: '上海市嘉定区安亭镇', lat: 31.3906, lng: 121.1909, devices: 52, online: 48, status: 'warning', power: 420 },
  { id: '4', name: '青浦站', address: '上海市青浦区朱家角镇', lat: 31.0142, lng: 121.0528, devices: 30, online: 28, status: 'normal', power: 380 },
  { id: '5', name: '松江站', address: '上海市松江区泰晤士小镇', lat: 31.0763, lng: 121.2102, devices: 25, online: 22, status: 'offline', power: 0 },
];

const MapPage: React.FC = () => {
  const [searchText, setSearchText] = useState('');
  const [selectedStation, setSelectedStation] = useState<any>(null);
  const [detailVisible, setDetailVisible] = useState(false);

  const filteredStations = stations.filter(s => 
    s.name.includes(searchText) || s.address.includes(searchText)
  );

  const handleStationClick = (station: any) => {
    setSelectedStation(station);
  };

  const getStatusTag = (status: string) => {
    const map: Record<string, { color: string; text: string }> = {
      normal: { color: 'green', text: '正常' },
      warning: { color: 'orange', text: '告警' },
      offline: { color: 'red', text: '离线' },
    };
    return map[status] || { color: 'default', text: status };
  };

  return (
    <div>
      <Row gutter={16}>
        {/* 左侧站点列表 */}
        <Col xs={24} lg={6}>
          <Card 
            title={
              <Space>
                <EnvironmentOutlined />
                站点列表
              </Space>
            }
            extra={<Badge count={stations.length} />}
          >
            <Search
              placeholder="搜索站点"
              prefix={<SearchOutlined />}
              onChange={e => setSearchText(e.target.value)}
              style={{ marginBottom: 16 }}
            />
            
            <List
              dataSource={filteredStations}
              renderItem={item => (
                <List.Item
                  style={{ 
                    cursor: 'pointer', 
                    background: selectedStation?.id === item.id ? '#f0f5ff' : 'transparent',
                    borderRadius: 4,
                    padding: '8px 12px',
                    marginBottom: 8,
                  }}
                  onClick={() => handleStationClick(item)}
                >
                  <List.Item.Meta
                    avatar={<EnvironmentOutlined style={{ fontSize: 20, color: '#1890ff' }} />}
                    title={
                      <Space>
                        {item.name}
                        <Tag color={getStatusTag(item.status).color}>
                          {getStatusTag(item.status).text}
                        </Tag>
                      </Space>
                    }
                    description={
                      <Space direction="vertical" size={0}>
                        <span style={{ fontSize: 12, color: '#8c8c8c' }}>{item.address}</span>
                        <Space size={8}>
                          <Tag icon={<DesktopOutlined />}>{item.devices} 设备</Tag>
                          <Tag color="green">{item.online} 在线</Tag>
                        </Space>
                      </Space>
                    }
                  />
                </List.Item>
              )}
            />
          </Card>
        </Col>

        {/* 中间地图区域 */}
        <Col xs={24} lg={12}>
          <Card 
            title="地图视图"
            extra={<Button type="link">全屏</Button>}
            style={{ height: '100%', minHeight: 600 }}
          >
            <div style={{ 
              height: 500, 
              background: 'linear-gradient(135deg, #e6f7ff 0%, #f0f5ff 100%)',
              borderRadius: 8,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              position: 'relative',
              border: '1px solid #d9d9d9',
            }}>
              {/* 模拟地图网格 */}
              <div style={{ 
                position: 'absolute', 
                inset: 20, 
                backgroundImage: 'radial-gradient(#1890ff 1px, transparent 1px)',
                backgroundSize: '20px 20px',
                opacity: 0.3,
              }} />
              
              {/* 模拟地图上的站点标记 */}
              {stations.map((station, index) => {
                const top = 50 + Math.sin(index * 1.2) * 150;
                const left = 50 + Math.cos(index * 1.2) * 180;
                return (
                  <div
                    key={station.id}
                    style={{
                      position: 'absolute',
                      top: `${top}px`,
                      left: `${left}px`,
                      cursor: 'pointer',
                      transform: 'translate(-50%, -50%)',
                    }}
                    onClick={() => handleStationClick(station)}
                  >
                    <div style={{
                      width: 40,
                      height: 40,
                      borderRadius: '50%',
                      background: station.status === 'normal' ? '#52c41a' : station.status === 'warning' ? '#faad14' : '#ff4d4f',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: '#fff',
                      fontSize: 18,
                      boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                      border: selectedStation?.id === station.id ? '3px solid #1890ff' : '3px solid transparent',
                    }}>
                      <EnvironmentOutlined />
                    </div>
                    <div style={{
                      position: 'absolute',
                      top: 45,
                      left: '50%',
                      transform: 'translateX(-50%)',
                      whiteSpace: 'nowrap',
                      fontSize: 12,
                      fontWeight: 500,
                      background: '#fff',
                      padding: '2px 6px',
                      borderRadius: 4,
                      boxShadow: '0 1px 4px rgba(0,0,0,0.1)',
                    }}>
                      {station.name}
                    </div>
                  </div>
                );
              })}
              
              <div style={{ position: 'absolute', bottom: 20, left: 20, color: '#8c8c8c', fontSize: 12 }}>
                <Space>
                  <span>🟢 正常</span>
                  <span>🟡 告警</span>
                  <span>🔴 离线</span>
                </Space>
              </div>
            </div>
          </Card>
        </Col>

        {/* 右侧统计 */}
        <Col xs={24} lg={6}>
          <Card title="站点统计">
            <Statistic
              title="站点总数"
              value={stations.length}
              prefix={<EnvironmentOutlined />}
            />
            <Divider />
            <Statistic
              title="设备总数"
              value={stations.reduce((sum, s) => sum + s.devices, 0)}
              prefix={<DesktopOutlined />}
            />
            <Divider />
            <Statistic
              title="在线设备"
              value={stations.reduce((sum, s) => sum + s.online, 0)}
              valueStyle={{ color: '#52c41a' }}
            />
            <Divider />
            <Statistic
              title="总功率"
              value={stations.reduce((sum, s) => sum + s.power, 0)}
              prefix={<ThunderboltOutlined />}
              suffix="kW"
            />
          </Card>

          <Card title="站点告警" style={{ marginTop: 16 }}>
            {stations.filter(s => s.status !== 'normal').map(s => (
              <div key={s.id} style={{ marginBottom: 8 }}>
                <Space>
                  <WarningOutlined style={{ color: '#faad14' }} />
                  <span>{s.name}</span>
                  <Tag color={getStatusTag(s.status).color}>
                    {getStatusTag(s.status).text}
                  </Tag>
                </Space>
              </div>
            ))}
            {stations.every(s => s.status === 'normal') && (
              <div style={{ color: '#52c41a' }}>所有站点运行正常</div>
            )}
          </Card>
        </Col>
      </Row>

      {/* 站点详情弹窗 */}
      <Modal
        title="站点详情"
        open={detailVisible}
        onCancel={() => setDetailVisible(false)}
        footer={[
          <Button key="control" type="primary">
            远程控制
          </Button>,
          <Button key="close" onClick={() => setDetailVisible(false)}>
            关闭
          </Button>,
        ]}
      >
        {selectedStation && (
          <Descriptions column={1}>
            <Descriptions.Item label="站点名称">{selectedStation.name}</Descriptions.Item>
            <Descriptions.Item label="地址">{selectedStation.address}</Descriptions.Item>
            <Descriptions.Item label="状态">
              <Tag color={getStatusTag(selectedStation.status).color}>
                {getStatusTag(selectedStation.status).text}
              </Tag>
            </Descriptions.Item>
            <Descriptions.Item label="设备数量">{selectedStation.devices}</Descriptions.Item>
            <Descriptions.Item label="在线设备">{selectedStation.online}</Descriptions.Item>
            <Descriptions.Item label="当前功率">{selectedStation.power} kW</Descriptions.Item>
            <Descriptions.Item label="坐标">
              {selectedStation.lat}, {selectedStation.lng}
            </Descriptions.Item>
          </Descriptions>
        )}
      </Modal>
    </div>
  );
};

export default MapPage;