/**
 * 系统配置页面
 */
import React, { useState } from 'react';
import {
  Card,
  Tabs,
  Form,
  Input,
  InputNumber,
  Select,
  Switch,
  Button,
  message,
  Row,
  Col,
  Divider
} from 'antd';
import {
  SettingOutlined,
  BellOutlined,
  SafetyOutlined,
  ApiOutlined
} from '@ant-design/icons';

const { TabPane } = Tabs;

const ConfigPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [basicForm] = Form.useForm();
  const [alarmForm] = Form.useForm();
  const [securityForm] = Form.useForm();
  const [apiForm] = Form.useForm();

  const handleSaveBasic = async (values: any) => {
    setLoading(true);
    message.success('基础配置已保存');
    setLoading(false);
  };

  const handleSaveAlarm = async (values: any) => {
    setLoading(true);
    message.success('告警配置已保存');
    setLoading(false);
  };

  const handleSaveSecurity = async (values: any) => {
    setLoading(true);
    message.success('安全配置已保存');
    setLoading(false);
  };

  const handleSaveApi = async (values: any) => {
    setLoading(true);
    message.success('API配置已保存');
    setLoading(false);
  };

  return (
    <div style={{ padding: 24 }}>
      <Card>
        <Tabs defaultActiveKey="basic">
          <TabPane tab={<span><SettingOutlined /> 基础配置</span>} key="basic">
            <Form
              form={basicForm}
              layout="vertical"
              onFinish={handleSaveBasic}
              initialValues={{
                systemName: '天链运维系统',
                language: 'zh-CN',
                timezone: 'Asia/Shanghai',
                dateFormat: 'YYYY-MM-DD'
              }}
            >
              <Row gutter={24}>
                <Col span={12}>
                  <Form.Item label="系统名称" name="systemName">
                    <Input />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  <Form.Item label="系统语言" name="language">
                    <Select options={[
                      { label: '简体中文', value: 'zh-CN' },
                      { label: 'English', value: 'en-US' }
                    ]} />
                  </Form.Item>
                </Col>
              </Row>
              <Row gutter={24}>
                <Col span={12}>
                  <Form.Item label="时区设置" name="timezone">
                    <Select options={[
                      { label: '北京时间 (GMT+8)', value: 'Asia/Shanghai' },
                      { label: 'UTC', value: 'UTC' }
                    ]} />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  <Form.Item label="日期格式" name="dateFormat">
                    <Select options={[
                      { label: 'YYYY-MM-DD', value: 'YYYY-MM-DD' },
                      { label: 'DD/MM/YYYY', value: 'DD/MM/YYYY' }
                    ]} />
                  </Form.Item>
                </Col>
              </Row>
              <Button type="primary" htmlType="submit" loading={loading}>
                保存基础配置
              </Button>
            </Form>
          </TabPane>

          <TabPane tab={<span><BellOutlined /> 告警配置</span>} key="alarm">
            <Form
              form={alarmForm}
              layout="vertical"
              onFinish={handleSaveAlarm}
              initialValues={{
                alarmLevel: 'high',
                autoNotify: true,
                notifyChannel: ['email', 'sms'],
                retentionDays: 30
              }}
            >
              <Form.Item label="默认告警级别" name="alarmLevel">
                <Select options={[
                  { label: '紧急', value: 'critical' },
                  { label: '高', value: 'high' },
                  { label: '中', value: 'medium' },
                  { label: '低', value: 'low' }
                ]} />
              </Form.Item>
              <Form.Item label="自动通知" name="autoNotify" valuePropName="checked">
                <Switch />
              </Form.Item>
              <Form.Item label="通知渠道" name="notifyChannel">
                <Select mode="multiple" options={[
                  { label: '邮件', value: 'email' },
                  { label: '短信', value: 'sms' },
                  { label: 'IM', value: 'im' },
                  { label: 'IM-B', value: 'im-b' }
                ]} />
              </Form.Item>
              <Form.Item label="告警保留天数" name="retentionDays">
                <InputNumber min={7} max={365} />
              </Form.Item>
              <Button type="primary" htmlType="submit" loading={loading}>
                保存告警配置
              </Button>
            </Form>
          </TabPane>

          <TabPane tab={<span><SafetyOutlined /> 安全配置</span>} key="security">
            <Form
              form={securityForm}
              layout="vertical"
              onFinish={handleSaveSecurity}
              initialValues={{
                sessionTimeout: 30,
                passwordPolicy: 'medium',
                twoFactor: false,
                ipWhitelist: ''
              }}
            >
              <Form.Item label="会话超时(分钟)" name="sessionTimeout">
                <InputNumber min={5} max={120} />
              </Form.Item>
              <Form.Item label="密码策略" name="passwordPolicy">
                <Select options={[
                  { label: '简单 (6位)', value: 'simple' },
                  { label: '中等 (8位+数字)', value: 'medium' },
                  { label: '复杂 (12位+数字+符号)', value: 'complex' }
                ]} />
              </Form.Item>
              <Form.Item label="双因素认证" name="twoFactor" valuePropName="checked">
                <Switch />
              </Form.Item>
              <Form.Item label="IP白名单" name="ipWhitelist">
                <Input.TextArea rows={3} placeholder="输入允许的IP地址，逗号分隔" />
              </Form.Item>
              <Button type="primary" htmlType="submit" loading={loading}>
                保存安全配置
              </Button>
            </Form>
          </TabPane>

          <TabPane tab={<span><ApiOutlined /> API配置</span>} key="api">
            <Form
              form={apiForm}
              layout="vertical"
              onFinish={handleSaveApi}
              initialValues={{
                apiVersion: 'v1',
                rateLimit: 100,
                enableCors: true,
                corsOrigins: '*'
              }}
            >
              <Form.Item label="API版本" name="apiVersion">
                <Select options={[
                  { label: 'v1', value: 'v1' },
                  { label: 'v2', value: 'v2' }
                ]} />
              </Form.Item>
              <Form.Item label="请求频率限制(次/分钟)" name="rateLimit">
                <InputNumber min={10} max={1000} />
              </Form.Item>
              <Form.Item label="启用CORS" name="enableCors" valuePropName="checked">
                <Switch />
              </Form.Item>
              <Form.Item label="允许的来源" name="corsOrigins">
                <Input placeholder="输入允许的域名，逗号分隔，* 表示全部" />
              </Form.Item>
              <Button type="primary" htmlType="submit" loading={loading}>
                保存API配置
              </Button>
            </Form>
          </TabPane>
        </Tabs>
      </Card>
    </div>
  );
};

export default ConfigPage;