/**
 * 登录页面 - 天链光储充运维系统
 */
import React, { useState } from 'react';
import { Form, Input, Button, Card, message, Typography, Divider } from 'antd';
import { UserOutlined, LockOutlined, ThunderboltOutlined, SunOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../../api';

const { Title, Text } = Typography;

const LoginPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [accountType, setAccountType] = useState<'team' | 'platform'>('team');
  const navigate = useNavigate();

  const onFinish = async (values: { username: string; password: string }) => {
    setLoading(true);
    try {
      const response: any = await authAPI.login(values);
      localStorage.setItem('admin_token', response.access_token);
      localStorage.setItem('admin_user', JSON.stringify(response.user));
      localStorage.setItem('admin_account_type', accountType === 'team' ? 'operator' : 'platform');
      message.success('登录成功');
      navigate('/dashboard');
    } catch (error: any) {
      message.error(error.response?.data?.detail || '登录失败');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 50%, #334155 100%)',
      position: 'relative',
    }}>
      {/* 背景装饰 */}
      <div style={{
        position: 'absolute',
        top: 0, left: 0, right: 0, bottom: 0,
        background: 'radial-gradient(circle at 30% 20%, rgba(59, 130, 246, 0.08) 0%, transparent 40%), radial-gradient(circle at 70% 80%, rgba(34, 197, 94, 0.06) 0%, transparent 40%)',
      }} />
      
      <Card
        style={{ 
          width: 480, 
          boxShadow: '0 24px 80px rgba(0,0,0,0.5), 0 0 60px rgba(59, 130, 246, 0.08)',
          borderRadius: 20,
          border: '1px solid rgba(59, 130, 246, 0.15)',
          background: 'rgba(15, 23, 42, 0.98)',
        }}
        bodyStyle={{ padding: '48px 40px' }}
      >
        {/* 标题区域 */}
        <div style={{ textAlign: 'center', marginBottom: 40 }}>
          <Title level={2} style={{ 
            marginBottom: 8, 
            color: '#F8FAFC',
            fontWeight: 700,
            letterSpacing: 3,
          }}>
            天链运维系统
          </Title>
          <Text style={{ color: '#94A3B8', fontSize: 15 }}>
            光储充智能运维管理平台
          </Text>
        </div>

        {/* 账户类型选择 */}
        <div style={{ marginBottom: 32 }}>
          <div style={{ display: 'flex', gap: 16 }}>
            <Card 
              hoverable
              onClick={() => setAccountType('team')}
              style={{ 
                flex: 1,
                background: accountType === 'team' 
                  ? 'linear-gradient(135deg, #3B82F6 0%, #1D4ED8 100%)'
                  : 'rgba(30, 41, 59, 0.6)',
                border: accountType === 'team' 
                  ? '2px solid #60A5FA'
                  : '1px solid rgba(148, 163, 184, 0.2)',
                borderRadius: 16,
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                boxShadow: accountType === 'team' ? '0 8px 24px rgba(59, 130, 246, 0.25)' : 'none',
              }}
              bodyStyle={{ padding: 20, textAlign: 'center' }}
            >
              <ThunderboltOutlined style={{ 
                fontSize: 28, 
                color: accountType === 'team' ? '#FFFFFF' : '#94A3B8',
                marginBottom: 12,
              }} />
              <div style={{ 
                fontWeight: 600, 
                fontSize: 15,
                color: accountType === 'team' ? '#FFFFFF' : '#E2E8F0',
                marginBottom: 6,
              }}>
                运维团队
              </div>
              <div style={{ 
                fontSize: 13,
                color: accountType === 'team' ? '#DBEAFE' : '#64748B',
              }}>
                管理承接的站点和设备
              </div>
            </Card>
            
            <Card 
              hoverable
              onClick={() => setAccountType('platform')}
              style={{ 
                flex: 1,
                background: accountType === 'platform' 
                  ? 'linear-gradient(135deg, #22C55E 0%, #15803D 100%)'
                  : 'rgba(30, 41, 59, 0.6)',
                border: accountType === 'platform' 
                  ? '2px solid #4ADE80'
                  : '1px solid rgba(148, 163, 184, 0.2)',
                borderRadius: 16,
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                boxShadow: accountType === 'platform' ? '0 8px 24px rgba(34, 197, 94, 0.25)' : 'none',
              }}
              bodyStyle={{ padding: 20, textAlign: 'center' }}
            >
              <SunOutlined style={{ 
                fontSize: 28, 
                color: accountType === 'platform' ? '#FFFFFF' : '#94A3B8',
                marginBottom: 12,
              }} />
              <div style={{ 
                fontWeight: 600, 
                fontSize: 15,
                color: accountType === 'platform' ? '#FFFFFF' : '#E2E8F0',
                marginBottom: 6,
              }}>
                平台运维
              </div>
              <div style={{ 
                fontSize: 13,
                color: accountType === 'platform' ? '#BBF7D0' : '#64748B',
              }}>
                服务商平台管理
              </div>
            </Card>
          </div>
        </div>

        <Divider style={{ margin: '32px 0', borderColor: 'rgba(148, 163, 184, 0.15)' }} />

        {/* 登录表单 */}
        <Form
          name="login"
          onFinish={onFinish}
          autoComplete="off"
          size="large"
        >
          <Form.Item
            name="username"
            rules={[{ required: true, message: '请输入账号' }]}
          >
            <Input 
              prefix={<UserOutlined style={{ color: '#64748B' }} />} 
              placeholder="请输入账号"
              style={{
                background: 'rgba(30, 41, 59, 0.8)',
                border: '1px solid rgba(148, 163, 184, 0.25)',
                borderRadius: 12,
                color: '#F8FAFC',
                height: 48,
              }}
            />
          </Form.Item>

          <Form.Item
            name="password"
            rules={[{ required: true, message: '请输入密码' }]}
          >
            <Input.Password 
              prefix={<LockOutlined style={{ color: '#64748B' }} />} 
              placeholder="请输入密码"
              style={{
                background: 'rgba(30, 41, 59, 0.8)',
                border: '1px solid rgba(148, 163, 184, 0.25)',
                borderRadius: 12,
                color: '#F8FAFC',
                height: 48,
              }}
            />
          </Form.Item>

          <Form.Item style={{ marginTop: 40 }}>
            <Button 
              type="primary" 
              htmlType="submit" 
              loading={loading} 
              block
              style={{
                height: 52,
                borderRadius: 12,
                fontWeight: 600,
                fontSize: 16,
                background: accountType === 'team' 
                  ? 'linear-gradient(135deg, #3B82F6 0%, #1D4ED8 100%)'
                  : 'linear-gradient(135deg, #22C55E 0%, #15803D 100%)',
                border: 'none',
                boxShadow: accountType === 'team' 
                  ? '0 6px 20px rgba(59, 130, 246, 0.4)'
                  : '0 6px 20px rgba(34, 197, 94, 0.4)',
              }}
            >
              登 录
            </Button>
          </Form.Item>
        </Form>
        
        {/* 底部版本信息 */}
        <div style={{ textAlign: 'center', marginTop: 24 }}>
          <Text style={{ color: '#475569', fontSize: 13 }}>
            天链光储充运维系统 v1.0
          </Text>
        </div>
      </Card>
    </div>
  );
};

export default LoginPage;