/**
 * 智能诊断页面 - 天链运维平台
 * 五维度健康度评估 + 故障预测 + 维修建议
 */
import React, { useEffect, useState } from 'react';
import ReactECharts from 'echarts-for-react';
import { Card, Row, Col, Select, Button, Table, Tag, List, Spin, Alert, Progress, Statistic } from 'antd';
import { 
  MedicineBoxOutlined, WarningOutlined, CheckCircleOutlined, 
  ThunderboltOutlined, ToolOutlined, ReloadOutlined
} from '@ant-design/icons';
import api from '../../api';

interface DeviceDiagnosis {
  device_id: number;
  device_code: string;
  device_name: string;
  status: string;
  health_score: number;
  health_grade: string;
  station_id: number;
  station_name: string;
}

interface DiagnosisDetail {
  device: {
    id: number;
    code: string;
    name: string;
    type: string;
    status: string;
    station_id: number;
    station_name: string;
  };
  overall_health: {
    score: number;
    grade: string;
    status: string;
  };
  dimension_scores: {
    [key: string]: {
      name: string;
      score: number;
      weight: number;
      status: string;
      metrics: string[];
    };
  };
  fault_predictions: any[];
  repair_suggestions: any[];
  alarm_count: number;
  work_order_count: number;
}

interface HealthTrend {
  device_id: number;
  device_name: string;
  days: number;
  current_score: number;
  trend_direction: string;
  trend_change: number;
  trend_data: {
    date: string;
    score: number;
    grade: string;
  }[];
}

const Diagnosis: React.FC = () => {
  const [devices, setDevices] = useState<DeviceDiagnosis[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<number | null>(null);
  const [diagnosisDetail, setDiagnosisDetail] = useState<DiagnosisDetail | null>(null);
  const [healthTrend, setHealthTrend] = useState<HealthTrend | null>(null);
  const [loading, setLoading] = useState(false);
  const [batchLoading, setBatchLoading] = useState(false);
  const [batchStats, setBatchStats] = useState<any>(null);

  useEffect(() => {
    loadBatchDiagnosis();
  }, []);

  const loadBatchDiagnosis = async () => {
    setBatchLoading(true);
    try {
      const res = await api.post('/api/v1/diagnosis/batch', {});
      setBatchStats(res.data);
      setDevices(res.data.devices || []);
    } catch (error) {
      console.error('批量诊断失败:', error);
    } finally {
      setBatchLoading(false);
    }
  };

  const loadDeviceDiagnosis = async (deviceId: number) => {
    setLoading(true);
    setSelectedDevice(deviceId);
    try {
      const [detailRes, trendRes] = await Promise.all([
        api.get(`/api/v1/diagnosis/device/${deviceId}`),
        api.get(`/api/v1/diagnosis/health-trend/${deviceId}?days=7`),
      ]);
      setDiagnosisDetail(detailRes.data);
      setHealthTrend(trendRes.data);
    } catch (error) {
      console.error('设备诊断失败:', error);
    } finally {
      setLoading(false);
    }
  };

  // 五维度雷达图
  const radarOption = diagnosisDetail ? {
    title: { text: '健康度五维度评估', left: 'center' },
    tooltip: {},
    radar: {
      indicator: Object.entries(diagnosisDetail.dimension_scores).map(([key, value]) => ({
        name: value.name,
        max: 100,
      })),
      shape: 'polygon',
      splitNumber: 5,
      axisName: {
        color: '#333',
      },
    },
    series: [{
      type: 'radar',
      data: [{
        value: Object.values(diagnosisDetail.dimension_scores).map((v) => v.score),
        name: diagnosisDetail.device.name,
        itemStyle: {
          color: diagnosisDetail.overall_health.score >= 80 ? '#52c41a' : '#faad14',
        },
        areaStyle: {
          opacity: 0.3,
        },
      }],
    }],
  } : null;

  // 健康趋势图
  const trendOption = healthTrend ? {
    title: { text: `${healthTrend.device_name} 健康度趋势`, left: 'center' },
    tooltip: { trigger: 'axis' },
    xAxis: {
      type: 'category',
      data: healthTrend.trend_data.map((item) => item.date),
    },
    yAxis: {
      type: 'value',
      name: '健康度(分)',
      min: 0,
      max: 100,
    },
    series: [{
      data: healthTrend.trend_data.map((item) => item.score),
      type: 'line',
      smooth: true,
      areaStyle: {
        color: 'rgba(82, 196, 26, 0.2)',
      },
      itemStyle: {
        color: '#52c41a',
      },
      markLine: {
        data: [
          { yAxis: 80, name: '健康线', lineStyle: { color: '#52c41a' } },
          { yAxis: 60, name: '警告线', lineStyle: { color: '#faad14' } },
        ],
      },
    }],
  } : null;

  const getStatusColor = (status: string) => {
    switch (status) {
      case '健康':
        return 'green';
      case '亚健康':
        return 'orange';
      case '需维护':
        return 'red';
      default:
        return 'default';
    }
  };

  const getGradeColor = (grade: string) => {
    switch (grade) {
      case 'A':
        return 'green';
      case 'B':
        return 'lime';
      case 'C':
        return 'gold';
      case 'D':
        return 'orange';
      case 'E':
        return 'red';
      default:
        return 'default';
    }
  };

  const deviceColumns = [
    { title: '设备编码', dataIndex: 'device_code', key: 'device_code' },
    { title: '设备名称', dataIndex: 'device_name', key: 'device_name' },
    { title: '站点', dataIndex: 'station_name', key: 'station_name' },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => <Tag color={status === 'online' ? 'green' : 'red'}>{status}</Tag>,
    },
    {
      title: '健康度',
      dataIndex: 'health_score',
      key: 'health_score',
      render: (score: number) => (
        <Progress
          percent={score}
          size="small"
          strokeColor={score >= 80 ? '#52c41a' : score >= 60 ? '#faad14' : '#f5222d'}
        />
      ),
    },
    {
      title: '等级',
      dataIndex: 'health_grade',
      key: 'health_grade',
      render: (grade: string) => <Tag color={getGradeColor(grade)}>{grade}</Tag>,
    },
    {
      title: '操作',
      key: 'action',
      render: (record: DeviceDiagnosis) => (
        <Button type="link" onClick={() => loadDeviceDiagnosis(record.device_id)}>
          详细诊断
        </Button>
      ),
    },
  ];

  return (
    <div style={{ padding: '20px' }}>
      {/* 顶部统计 */}
      {batchStats && (
        <Row gutter={[16, 16]} style={{ marginBottom: '20px' }}>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="设备总数"
                value={batchStats.total_devices}
                suffix="台"
                prefix={<ThunderboltOutlined />}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="健康设备"
                value={batchStats.healthy_devices}
                suffix="台"
                prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />}
                valueStyle={{ color: '#52c41a' }}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="亚健康设备"
                value={batchStats.warning_devices}
                suffix="台"
                prefix={<WarningOutlined style={{ color: '#faad14' }} />}
                valueStyle={{ color: '#faad14' }}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="故障设备"
                value={batchStats.fault_devices}
                suffix="台"
                prefix={<WarningOutlined style={{ color: '#f5222d' }} />}
                valueStyle={{ color: '#f5222d' }}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="平均健康度"
                value={batchStats.avg_health_score}
                suffix="分"
                prefix={<MedicineBoxOutlined />}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={4}>
            <Card>
              <Statistic
                title="健康率"
                value={batchStats.health_rate}
                suffix="%"
                prefix={<CheckCircleOutlined />}
              />
            </Card>
          </Col>
        </Row>
      )}

      {/* 设备列表 */}
      <Card title="设备健康度列表" extra={<Button icon={<ReloadOutlined />} onClick={loadBatchDiagnosis}>刷新</Button>}>
        <Table
          dataSource={devices}
          columns={deviceColumns}
          rowKey="device_id"
          loading={batchLoading}
          pagination={{ pageSize: 10 }}
          onRow={(record) => ({
            onClick: () => loadDeviceDiagnosis(record.device_id),
            style: { cursor: 'pointer' },
          })}
        />
      </Card>

      {/* 详细诊断 */}
      {selectedDevice && diagnosisDetail && (
        <div style={{ marginTop: '20px' }}>
          {/* 紧急告警 */}
          {diagnosisDetail.fault_predictions.length > 0 && (
            <Alert
              message={`发现 ${diagnosisDetail.fault_predictions.length} 个潜在故障风险`}
              type="warning"
              showIcon
              style={{ marginBottom: '20px' }}
            />
          )}

          {/* 设备概览 */}
          <Card title={`设备: ${diagnosisDetail.device.name}`} style={{ marginBottom: '20px' }}>
            <Row gutter={[16, 16]}>
              <Col span={6}>
                <Statistic title="设备编码" value={diagnosisDetail.device.code} />
              </Col>
              <Col span={6}>
                <Statistic title="设备类型" value={diagnosisDetail.device.type} />
              </Col>
              <Col span={6}>
                <Statistic title="站点" value={diagnosisDetail.device.station_name || '未知'} />
              </Col>
              <Col span={6}>
                <Statistic
                  title="综合健康度"
                  value={diagnosisDetail.overall_health.score}
                  suffix="分"
                  valueStyle={{ color: diagnosisDetail.overall_health.score >= 80 ? '#52c41a' : '#faad14' }}
                />
              </Col>
            </Row>
          </Card>

          {/* 五维度雷达图 */}
          <Row gutter={[16, 16]}>
            <Col xs={24} lg={8}>
              <Card title="健康度维度">
                {radarOption && <ReactECharts option={radarOption} style={{ height: 300 }} />}
              </Card>
            </Col>

            {/* 维度详情 */}
            <Col xs={24} lg={8}>
              <Card title="维度详情">
                <List
                  dataSource={Object.entries(diagnosisDetail.dimension_scores)}
                  renderItem={([key, value]) => (
                    <List.Item>
                      <List.Item.Meta
                        title={<span><Tag color={getStatusColor(value.status)}>{value.status}</Tag> {value.name}</span>}
                        description={
                          <div>
                            <Progress percent={value.score} size="small" strokeColor={value.score >= 80 ? '#52c41a' : '#faad14'} />
                            <small>权重: {value.weight * 100}% | 指标: {value.metrics.join(', ')}</small>
                          </div>
                        }
                      />
                    </List.Item>
                  )}
                />
              </Card>
            </Col>

            {/* 健康趋势 */}
            <Col xs={24} lg={8}>
              <Card title="健康度趋势">
                {trendOption && <ReactECharts option={trendOption} style={{ height: 300 }} />}
              </Card>
            </Col>
          </Row>

          {/* 故障预测 */}
          {diagnosisDetail.fault_predictions.length > 0 && (
            <Card title="故障预测" style={{ marginTop: '20px' }}>
              <List
                dataSource={diagnosisDetail.fault_predictions}
                renderItem={(prediction) => (
                  <List.Item>
                    <List.Item.Meta
                      title={
                        <span>
                          <Tag color={prediction.risk_level === '高' ? 'red' : 'orange'}>
                            {prediction.risk_level}风险
                          </Tag>
                          {prediction.dimension}: {prediction.predicted_fault}
                        </span>
                      }
                      description={
                        <div>
                          <p>概率: {prediction.probability}% | 时间: {prediction.timeframe}</p>
                          <p>建议: {prediction.suggested_action}</p>
                        </div>
                      }
                    />
                  </List.Item>
                )}
              />
            </Card>
          )}

          {/* 维修建议 */}
          <Card title="维修建议" style={{ marginTop: '20px' }}>
            <List
              dataSource={diagnosisDetail.repair_suggestions}
              renderItem={(suggestion) => (
                <List.Item>
                  <List.Item.Meta
                    title={
                      <span>
                        <Tag color={suggestion.priority === 'critical' ? 'red' : suggestion.priority === 'high' ? 'orange' : 'default'}>
                          {suggestion.priority}
                        </Tag>
                        {suggestion.title}
                      </span>
                    }
                    description={suggestion.description}
                  />
                  <Button type="primary" size="small">
                    {suggestion.action}
                  </Button>
                </List.Item>
              )}
            />
          </Card>
        </div>
      )}

      {/* 加载状态 */}
      {loading && (
        <div style={{ textAlign: 'center', padding: '50px' }}>
          <Spin size="large" tip="正在分析设备健康度..." />
        </div>
      )}
    </div>
  );
};

export default Diagnosis;